('c23dbf3e-78db-42f3-bd2b-03a47ef52aae', 'number_operations', 'grade_3', 'foundation', 'multiple_choice', 'Jayden''s class raised $47 at the cake stall and $36 at the raffle table on fete day. How much did they raise altogether?', '["$83","$73","$93","$11"]'::jsonb, 0, 'Add the ones: 7 + 6 = 13, write 3 and carry 1. Add the tens: 4 + 3 + 1 = 8. Total: $83.', 'AC9M3N04', null, null, true, null, null, null, null),
('39e52f17-8622-49bc-b73a-5cdecc3668ae', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'The school canteen sold 248 sausage rolls on Monday and 375 on Tuesday. How many sausage rolls did it sell in total across the two days?', '["623","533","613","127"]'::jsonb, 0, 'Add the two days together: 248 + 375 = 623.', 'AC9M4N04', null, null, true, null, null, null, null),
('458f66e7-5d18-40f3-af46-16ff171e225f', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'A market stallholder arranges 15 crates of oranges with 24 oranges in each crate. How many oranges are there in total?', '["360","340","380","350"]'::jsonb, 0, '15 × 24 = 15 × 20 + 15 × 4 = 300 + 60 = 360.', 'AC9M5N04', null, null, true, null, null, null, null),
('6c56f7ea-0f72-407b-a5b7-6cf68fe4ce6c', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'Chloe jogs ¾ of a lap before school and ½ of a lap after school. How many laps does she jog in total?', '["1¼","1","1½","¾"]'::jsonb, 0, 'Convert to a common denominator: ¾ + 2⁄4 = 5⁄4 = 1¼.', 'AC9M6N04', null, null, true, null, null, null, null),
('96262ed4-eb11-4c6a-a91d-fe6a373063c9', 'number_operations', 'grade_6', 'proficient', 'multiple_choice', 'A school fete made $450 in total sales. 20% of the sales came from the sausage sizzle. How much money did the sausage sizzle raise?', '["$80","$85","$100","$90"]'::jsonb, 3, '20% = 20/100 = 1/5. $450 ÷ 5 = $90.', 'AC9M6N05', null, null, true, null, null, null, null),
('617d183d-8898-4592-9695-72582b0109bb', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'In a survey, 0.35 of Year 7 students said maths is their favourite subject. Write 0.35 as a fraction in simplest form.', '["7/20","3/5","35/100","7/10"]'::jsonb, 0, '0.35 = 35/100. Simplify by dividing by 5: 7/20.', 'AC9M7N03', null, null, true, null, null, null, null),
('ac08bd38-3a7d-4b96-b583-ff63e763bb9c', 'number_operations', 'year_8', 'proficient', 'short_answer', 'In a card game, a player''s score is calculated as −3 × (−4) + 2, where the first two numbers represent stacked penalty multipliers and the +2 is a bonus point. What is the player''s final score?', null, null, '−3 × −4 = +12. Then 12 + 2 = 14.', 'AC9M8N03', null, null, true, '14', null, null, null),
('61a7eacb-c722-480d-92b1-edd7865d8250', 'algebra_equations', 'year_7', 'foundation', 'multiple_choice', 'A fair charges $4 entry plus $2 per raffle ticket. Kyle spent $16 in total at the fair. Write an equation for the number of tickets, t, he bought, then solve it.', '["t = 6","t = 5","t = 8","t = 10"]'::jsonb, 0, 'Let t = number of tickets. 4 + 2t = 16, so 2t = 12, t = 6.', 'AC9M7A02', null, null, true, null, null, null, null),
('2d67f5a7-047c-4453-98f5-13a4a897d540', 'algebra_equations', 'year_7', 'developing', 'multiple_choice', 'A stadium''s seating chart adds seats in each new row: row 1 has 3 seats, row 2 has 7, row 3 has 11, row 4 has 15. If the pattern of adding 4 extra seats per row continues, how many seats are in row 5?', '["17","19","18","20"]'::jsonb, 1, 'The common difference is +4. 15 + 4 = 19 seats.', 'AC9M7A01', null, null, true, null, null, null, null),
('c8d6e78d-84e3-48e8-8778-634f0db174a4', 'algebra_equations', 'year_8', 'developing', 'multiple_choice', 'A fencing company''s total wire length, in metres, for a job is 4x + 3x − 2x, where x is the length of each roll used. Simplify this expression.', '["6x","8x","7x","5x"]'::jsonb, 3, 'Collect like terms: (4 + 3 − 2)x = 5x metres.', 'AC9M8A01', null, null, true, null, null, null, null),
('f21ff070-d3d8-4e69-b9d1-cc965b53e1ff', 'algebra_equations', 'year_9', 'proficient', 'multiple_choice', 'Factorise the expression x² − 9.', '["(x+3)(x+3)","(x−3)(x+3)","(x−9)(x+1)","(x+9)(x−1)"]'::jsonb, 1, 'Difference of two squares: a² − b² = (a−b)(a+b). So x² − 9 = (x−3)(x+3).', 'AC9M9A01', null, null, true, null, null, null, null),
('98490cd9-b9c1-4b78-a692-4636eea71cbc', 'algebra_equations', 'year_10', 'proficient', 'multiple_choice', 'If f(x) = 2x² − 3, what is f(−2)?', '["5","−11","−5","11"]'::jsonb, 0, 'f(−2) = 2(−2)² − 3 = 2(4) − 3 = 8 − 3 = 5.', 'AC9M10A02', null, null, true, null, null, null, null),
('7fe9cb1e-c2f8-4b27-a07d-159bc4219368', 'statistics_probability', 'grade_4', 'foundation', 'multiple_choice', 'Seven students were asked how many pets they own:
Student | Pets
Amy     | 2
Bo      | 4
Chen    | 4
Dina    | 5
Eli     | 6
Fay     | 4
Gus     | 7
What is the mode (most common) number of pets?', '["2","4","5","6"]'::jsonb, 1, 'The mode is the value that appears most often. 4 appears three times (Bo, Chen, Fay) — more than any other value.', 'AC9M4ST01', null, null, true, null, null, null, null),
('c2bbbfe9-28fb-4857-861d-f5050375b792', 'statistics_probability', 'grade_5', 'developing', 'multiple_choice', 'The bar chart shows how many students were absent from each class on Monday. How many students were absent altogether?', '["5","12","14","16"]'::jsonb, 2, 'Add the four bars: 3 + 5 + 2 + 4 = 14 students.', 'AC9M5ST01', null, null, true, null, null, null, null),
('0b6ec697-94fb-42c6-959f-6e7abc8cb892', 'statistics_probability', 'grade_6', 'proficient', 'multiple_choice', 'Five students recorded how many books they read last month:
Ali: 3, Ben: 7, Cara: 5, Dev: 3, Ella: 12.
What is the median number of books read?', '["5","3","6","12"]'::jsonb, 0, 'Ordered: 3, 3, 5, 7, 12. The middle value is 5.', 'AC9M6ST01', null, null, true, null, null, null, null),
('df773e2f-c2be-4735-bdef-ae4030e187a0', 'statistics_probability', 'year_7', 'foundation', 'multiple_choice', 'A fair six-sided die, numbered 1 to 6, is rolled once. What is the probability of rolling a 6?', '["1/3","1/4","1/6","1/2"]'::jsonb, 2, 'There are 6 equally likely outcomes (1–6), and only one of them is a 6: P(6) = 1/6.', 'AC9M7P01', null, null, true, null, null, null, null),
('fb70f0b9-45af-44ca-a7d5-379f78d6917b', 'statistics_probability', 'year_8', 'proficient', 'multiple_choice', 'The maximum daily temperature (°C) was recorded for 5 days:
Day       | Temp (°C)
Monday    | 12
Tuesday   | 7
Wednesday | 19
Thursday  | 3
Friday    | 15
What is the range of the daily temperatures?', '["12","16","7","19"]'::jsonb, 1, 'Range = max − min = 19 − 3 = 16.', 'AC9M8ST01', null, null, true, null, null, null, null),
('4c9c48fc-ba92-47c2-b8e7-d85eee10b828', 'reading_comprehension', 'grade_3', 'foundation', 'multiple_choice', 'Read: "Tom packed his bag and ran to catch the bus. He was late for school." Why did Tom run?', '["He wanted exercise","He was late for school","He lost his bag","He missed the bus"]'::jsonb, 1, 'The passage says Tom ''was late for school,'' which is why he ran to catch the bus.', 'AC9E3LY06', null, null, true, null, null, null, null),
('88176768-82e6-40f6-a4b6-e2a8449adfe7', 'reading_comprehension', 'grade_5', 'developing', 'multiple_choice', 'Read: "Although it was raining, Maya decided to go for a walk because she loved the smell of wet earth." What is Maya''s motivation for going outside?', '["She had to walk the dog","She loved the smell of rain","She was late","She wanted to get wet"]'::jsonb, 1, 'The word ''because'' signals her reason: she loved the smell of wet earth.', 'AC9E5LY07', null, null, true, null, null, null, null),
('f32db62e-cfd9-4ce9-a39e-0bf06cb95bc2', 'reading_comprehension', 'grade_6', 'developing', 'multiple_choice', 'In a story, a character who changes and grows over time is called a:', '["Static character","Dynamic character","Narrator","Antagonist"]'::jsonb, 1, 'A dynamic character undergoes meaningful internal change during the story.', 'AC9E6LE07', null, null, true, null, null, null, null),
('57e7176d-1784-41e5-b934-b008fe956f1a', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'Read: "The old bridge groaned under the weight of the truck, its timbers creaking like tired bones." This sentence mainly uses which literary device?', '["Simile","Metaphor","Onomatopoeia","Hyperbole"]'::jsonb, 0, '''Creaking like tired bones'' compares the bridge''s sound to bones using ''like'', which makes it a simile.', 'AC9E7LE05', null, null, true, null, null, null, null),
('f8f0d371-501c-4e1e-8a34-ba7636d6558d', 'reading_literary_analysis', 'year_9', 'advanced', 'multiple_choice', 'An author who writes with a critical or mocking tone about the flaws of society is using:', '["Satire","Elegy","Parody","Soliloquy"]'::jsonb, 0, 'Satire uses irony, humour, and exaggeration to criticise society''s flaws.', 'AC9E9LE04', null, null, true, null, null, null, null),
('13289b3d-55d7-4388-8289-12e944e75a28', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which sentence uses the correct punctuation?', '["Where is my hat","Where is my hat.","Where is my hat?","Where is my hat??"]'::jsonb, 2, 'Questions must end with a question mark and start with a capital letter.', 'AC9E3LA05', null, null, true, null, null, null, null),
('b4e8d10c-3038-4248-acbf-99c71fe7dd11', 'grammar_punctuation', 'grade_4', 'developing', 'multiple_choice', 'Choose the correctly punctuated sentence.', '["Its a sunny day.","It''s a sunny day.","Its'' a sunny day.","Its a sunny day"]'::jsonb, 1, '''It''s'' is the contraction of ''it is''. ''Its'' (no apostrophe) shows possession.', 'AC9E4LA06', null, null, true, null, null, null, null),
('50d57618-b6ac-4a40-9414-11fc145bebcb', 'grammar_punctuation', 'grade_6', 'proficient', 'multiple_choice', 'Identify the sentence with correct subject-verb agreement.', '["The team are winning.","The team is winning.","The team am winning.","The team be winning."]'::jsonb, 1, '''Team'' is a collective noun treated as singular in Australian English, so it takes ''is''.', 'AC9E6LA07', null, null, true, null, null, null, null),
('44031c53-3fe9-401e-be48-ed1ff2ccc2bc', 'grammar_punctuation', 'year_7', 'developing', 'multiple_choice', 'Which word correctly completes: ''Neither the students nor the teacher ___ ready.''', '["was","were","is","are"]'::jsonb, 0, 'With ''neither/nor'', the verb agrees with the nearer subject, ''teacher'' (singular), so ''was''.', 'AC9E7LA05', null, null, true, null, null, null, null),
('06ae62bf-37df-4c5e-a56e-ed9c1cf7512c', 'grammar_punctuation', 'year_8', 'proficient', 'multiple_choice', 'Which sentence correctly uses a semicolon?', '["I like tea; however, I prefer coffee.","I like tea, however I prefer coffee.","I like tea; and coffee.","I like tea however; I prefer coffee."]'::jsonb, 0, 'A semicolon can join two related independent clauses, often before a conjunctive adverb like ''however''.', 'AC9E8LA06', null, null, true, null, null, null, null),
('d0787f9d-fc16-4824-bd33-9b5a9ce48d10', 'vocabulary', 'grade_3', 'foundation', 'multiple_choice', 'Which word means the same as ''happy''?', '["Glad","Sad","Angry","Tired"]'::jsonb, 0, '''Glad'' is a synonym for ''happy''; both describe feeling pleased.', 'AC9E3LA09', null, null, true, null, null, null, null),
('38223913-5840-4bd4-8f9d-1bbea56a700f', 'vocabulary', 'grade_5', 'developing', 'multiple_choice', 'What is the antonym (opposite) of ''generous''?', '["Kind","Selfish","Wealthy","Helpful"]'::jsonb, 1, '''Selfish'' means the opposite of ''generous'', which means willing to give.', 'AC9E5LA10', null, null, true, null, null, null, null),
('ef89ac55-5590-45b9-8ca7-8a935961c8a9', 'vocabulary', 'grade_6', 'developing', 'multiple_choice', 'The prefix ''un-'' in the word ''unhappy'' means:', '["Very","Again","Not","Before"]'::jsonb, 2, 'The prefix ''un-'' means ''not'', so ''unhappy'' means ''not happy''.', 'AC9E6LA09', null, null, true, null, null, null, null),
('96962a07-d84a-4489-b4b4-4324f88b2b26', 'vocabulary', 'year_7', 'proficient', 'multiple_choice', 'Which word best fits: ''The detective''s ___ observation solved the case.''', '["meticulous","careless","hasty","vague"]'::jsonb, 0, '''Meticulous'' means very careful and precise, fitting a detective solving a case.', 'AC9E7LA10', null, null, true, null, null, null, null),
('bf750551-cf5e-491e-9e3c-eac4f1057ee0', 'vocabulary', 'year_9', 'advanced', 'multiple_choice', '''Ubiquitous'' most nearly means:', '["Rare","Present everywhere","Ancient","Loud"]'::jsonb, 1, '''Ubiquitous'' describes something found everywhere or very common.', 'AC9E9LA08', null, null, true, null, null, null, null),
('5ca913e1-318e-47f6-b043-4719b7bb1540', 'life_science', 'grade_3', 'foundation', 'multiple_choice', 'Which of these is a living thing?', '["Rock","Tree","Chair","Cloud"]'::jsonb, 1, 'Living things grow, reproduce, and need energy, so a tree is alive, while rocks, chairs and clouds are not.', 'AC9S3U01', null, null, true, null, null, null, null),
('9bf731e1-fa29-4479-92ed-ba7882e1b692', 'life_science', 'grade_5', 'developing', 'multiple_choice', 'What is the main function of a plant''s roots?', '["Make food using sunlight","Absorb water and nutrients","Produce seeds","Release oxygen"]'::jsonb, 1, 'Roots anchor the plant and absorb water and nutrients from the soil.', 'AC9S5U01', null, null, true, null, null, null, null),
('12310b4f-6289-41b5-8379-2d52e086a163', 'life_science', 'grade_6', 'developing', 'multiple_choice', 'Which organ pumps blood around the human body?', '["Lungs","Liver","Heart","Stomach"]'::jsonb, 2, 'The heart is a muscular organ that pumps blood through the circulatory system.', 'AC9S6U02', null, null, true, null, null, null, null),
('a7543b7a-a68d-4973-bed4-370427f0228d', 'life_science', 'year_7', 'proficient', 'multiple_choice', 'In a food chain, what is the primary role of a producer?', '["Eats other animals","Makes its own food using sunlight","Decomposes dead matter","Hunts prey"]'::jsonb, 1, 'Producers, like plants, make their own food through photosynthesis.', 'AC9S7U03', null, null, true, null, null, null, null),
('75a77b8c-543b-4772-a94b-1f700d4c4f3f', 'life_science', 'year_9', 'advanced', 'multiple_choice', 'Which process allows cells to divide and produce two genetically identical daughter cells?', '["Meiosis","Mitosis","Fertilisation","Osmosis"]'::jsonb, 1, 'Mitosis produces two genetically identical daughter cells for growth and repair.', 'AC9S9U03', null, null, true, null, null, null, null),
('2f9423e0-9e64-47f0-ba90-f0e31d32a1ff', 'physical_science', 'grade_4', 'foundation', 'multiple_choice', 'What happens to water when it is heated to boiling point?', '["It freezes","It turns into gas","It turns into rock","It disappears forever"]'::jsonb, 1, 'At boiling point, water changes from a liquid to a gas (water vapour).', 'AC9S4U01', null, null, true, null, null, null, null),
('d7c1d9c5-c9de-4188-851b-fb10521c436b', 'physical_science', 'grade_6', 'developing', 'multiple_choice', 'Which of these is a force that slows down moving objects?', '["Gravity","Friction","Magnetism","Light"]'::jsonb, 1, 'Friction acts opposite to motion between surfaces, slowing objects down.', 'AC9S6U01', null, null, true, null, null, null, null),
('b4135d64-f9bb-403b-8899-464791404fae', 'physical_science', 'year_7', 'developing', 'multiple_choice', 'What is the unit used to measure electric current?', '["Volt","Watt","Ampere","Ohm"]'::jsonb, 2, 'Electric current is measured in amperes (amps), symbol A.', 'AC9S7U01', null, null, true, null, null, null, null),
('08c4487d-e0de-45dd-a475-9b23f8d3b6ee', 'physical_science', 'year_8', 'proficient', 'multiple_choice', 'Which state of matter has a fixed volume but no fixed shape?', '["Solid","Liquid","Gas","Plasma"]'::jsonb, 1, 'A liquid takes the shape of its container but keeps a fixed volume.', 'AC9S8U01', null, null, true, null, null, null, null),
('fa75ee6b-7411-4dc0-8f24-9db75d523b3e', 'physical_science', 'year_10', 'advanced', 'multiple_choice', 'According to Newton''s second law, force equals:', '["mass ÷ acceleration","mass × acceleration","mass + acceleration","acceleration ÷ mass"]'::jsonb, 1, 'Newton''s second law states F = m × a (force equals mass times acceleration).', 'AC9S10U03', null, null, true, null, null, null, null),
('5955cdef-1a18-49bc-867e-83772e0bb443', 'earth_space', 'grade_3', 'foundation', 'multiple_choice', 'What causes day and night on Earth?', '["The Moon orbiting Earth","Earth spinning on its axis","The Sun moving around Earth","Clouds covering the Sun"]'::jsonb, 1, 'Earth rotates on its axis once every 24 hours, causing day and night.', 'AC9S3U02', null, null, true, null, null, null, null),
('c6fb52e0-4bff-4659-bb3d-5374d17ab882', 'earth_space', 'grade_5', 'developing', 'multiple_choice', 'Which layer of the Earth is the hottest?', '["Crust","Mantle","Outer core","Inner core"]'::jsonb, 3, 'The inner core is the hottest layer, reaching temperatures similar to the Sun''s surface.', 'AC9S5U02', null, null, true, null, null, null, null),
('6eec1bb8-817f-4d8a-9cfe-f1fea7cc875b', 'earth_space', 'grade_6', 'developing', 'multiple_choice', 'What is the main cause of the seasons on Earth?', '["Distance from the Sun changing a lot","The tilt of Earth''s axis","The Moon''s gravity","Ocean currents"]'::jsonb, 1, 'Earth''s axial tilt means different hemispheres receive more or less direct sunlight through the year, causing seasons.', 'AC9S6U03', null, null, true, null, null, null, null),
('5327c5a5-d566-472a-9c20-46d7b7130175', 'earth_space', 'year_8', 'proficient', 'multiple_choice', 'Which type of rock forms from cooled magma or lava?', '["Sedimentary","Metamorphic","Igneous","Fossil"]'::jsonb, 2, 'Igneous rock forms when magma or lava cools and solidifies.', 'AC9S8U02', null, null, true, null, null, null, null),
('2a50a3c3-40ff-4e56-947a-394adc7cab21', 'earth_space', 'year_9', 'advanced', 'multiple_choice', 'What is the primary evidence used to support the theory of plate tectonics?', '["Fossil records only","Matching coastlines, fossils, and rock strata across continents","Ocean temperature","Moon phases"]'::jsonb, 1, 'Matching coastlines, fossil distributions, and rock strata across continents provide strong evidence for plate tectonics.', 'AC9S9U04', null, null, true, null, null, null, null),
('3b42d2be-fbd4-4d3b-8827-22a090d39f3e', 'chem_atomic_structure', 'year_11', 'foundation', 'multiple_choice', 'How many electrons can the first electron shell (n = 1) hold at maximum?', '["2","8","18","6"]'::jsonb, 0, 'The first shell (n = 1) holds a maximum of 2 electrons.', null, null, null, true, null, null, null, null),
('065e91db-0de0-4986-9df8-b9511054b68a', 'chem_atomic_structure', 'year_11', 'foundation', 'multiple_choice', 'What does the atomic number of an element tell you?', '["The number of neutrons","The number of protons","The number of protons plus neutrons","The number of outer-shell electrons"]'::jsonb, 1, 'The atomic number is the number of protons in the nucleus, which also equals the number of electrons in a neutral atom.', null, null, null, true, null, null, null, null),
('0ddf4f17-0812-4cdd-aa13-f4aaad38b896', 'chem_reactions', 'year_11', 'developing', 'multiple_choice', 'In the reaction Mg + 2HCl → MgCl₂ + H₂, what type of reaction is this?', '["Combustion","Displacement","Neutralisation","Decomposition"]'::jsonb, 1, 'Magnesium displaces hydrogen from hydrochloric acid, making this a displacement reaction.', null, null, null, true, null, null, null, null),
('557bbb2b-67b7-4b2b-9f4b-47b80434436d', 'chem_reactions', 'year_11', 'developing', 'multiple_choice', 'What are the correct coefficients to balance: __H₂ + __O₂ → __H₂O?', '["1, 1, 1","2, 1, 2","2, 2, 2","1, 2, 1"]'::jsonb, 1, '2H₂ + O₂ → 2H₂O balances both hydrogen (4 atoms) and oxygen (2 atoms) on each side.', null, null, null, true, null, null, null, null),
('0a07ed7f-3495-412f-843c-c967b7394a2b', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'A car accelerates from rest at 2 m/s² for 5 seconds. What is its final velocity?', '["5 m/s","10 m/s","15 m/s","20 m/s"]'::jsonb, 1, 'v = u + at = 0 + (2 × 5) = 10 m/s.', null, null, null, true, null, null, null, null),
('6c48df1d-33ae-4d32-91b5-6e353d6e176d', 'phys_mechanics', 'year_11', 'foundation', 'multiple_choice', 'Which formula gives the kinetic energy of a moving object?', '["mgh","½mv²","mv","ma"]'::jsonb, 1, 'Kinetic energy is calculated as ½mv², where m is mass and v is velocity.', null, null, null, true, null, null, null, null),
('f7de488d-5e3b-4931-b68a-5db63687a461', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'Using Ohm''s law, what is the current through a 10 Ω resistor with 20 V across it?', '["0.5 A","2 A","10 A","200 A"]'::jsonb, 1, 'I = V / R = 20 / 10 = 2 A.', null, null, null, true, null, null, null, null),
('044beb53-783a-4caf-a5b7-26d10f2e1650', 'phys_electricity', 'year_11', 'foundation', 'multiple_choice', 'Which particle carries negative charge and flows to create a typical electric current in a wire?', '["Proton","Neutron","Electron","Positron"]'::jsonb, 2, 'Electrons carry negative charge and are the particles that flow through a conductor.', null, null, null, true, null, null, null, null),
('c2a82f32-e1b5-4a7e-82e3-5843a6d0f39a', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate f(x) = 3x² + 2x.', '["f''(x) = 6x + 2","f''(x) = 3x + 2","f''(x) = 6x","f''(x) = 6x² + 2"]'::jsonb, 0, 'Using the power rule: d/dx(3x²) = 6x and d/dx(2x) = 2, giving 6x + 2.', null, null, null, true, null, null, null, null),
('2bd3853a-b67a-4cc7-baf4-227f343c1874', 'mm_calculus', 'year_11', 'foundation', 'multiple_choice', 'What is the derivative of a constant, such as f(x) = 7?', '["7","1","0","x"]'::jsonb, 2, 'The derivative of any constant is 0, since a constant does not change as x changes.', null, null, null, true, null, null, null, null),
('8205de0f-8534-4eb8-8199-371a67bc7156', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'A fair coin is tossed twice. What is the probability of getting exactly one head?', '["1/4","1/2","3/4","1"]'::jsonb, 1, 'Of the four equally likely outcomes (HH, HT, TH, TT), two have exactly one head, giving 2/4 = 1/2.', null, null, null, true, null, null, null, null),
('26ca60d4-2c6d-4f9e-b97c-c0f37655220c', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'If P(A) = 0.3 and P(B) = 0.4 and A and B are independent, what is P(A and B)?', '["0.7","0.12","0.1","0.34"]'::jsonb, 1, 'For independent events, P(A and B) = P(A) × P(B) = 0.3 × 0.4 = 0.12.', null, null, null, true, null, null, null, null),
('91dd8c91-8f1f-491f-96b8-e2610b41fe99', 'gm_data_analysis', 'year_11', 'foundation', 'multiple_choice', 'What does the median of a data set represent?', '["The most frequent value","The middle value when the data is ordered","The average of all values","The range of the values"]'::jsonb, 1, 'The median is the middle value once the data set is arranged in order.', null, null, null, true, null, null, null, null),
('91c45557-dbe3-465b-9fd5-3be3080e9dc9', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'A data set has Q1 = 10 and Q3 = 18. What is the interquartile range (IQR)?', '["8","18","28","10"]'::jsonb, 0, 'IQR = Q3 − Q1 = 18 − 10 = 8.', null, null, null, true, null, null, null, null),
('23d8c575-deee-4f27-b355-ce6a665086d3', 'gm_financial', 'year_11', 'developing', 'multiple_choice', '$1000 is invested at 5% simple interest per year. How much interest is earned after 3 years?', '["$50","$150","$1050","$1150"]'::jsonb, 1, 'Simple interest = P × r × t = 1000 × 0.05 × 3 = $150.', null, null, null, true, null, null, null, null),
('181fa7ab-86e6-4dde-b712-b5d3351df455', 'gm_financial', 'year_11', 'foundation', 'multiple_choice', 'What does "principal" mean in the context of a loan or investment?', '["The interest earned","The original amount borrowed or invested","The final balance","The interest rate"]'::jsonb, 1, 'The principal is the original sum of money borrowed or invested, before interest is applied.', null, null, null, true, null, null, null, null),
('3cad9f55-12a8-4c1a-86bb-c1aa38995a9d', 'sm_complex_numbers', 'year_11', 'foundation', 'multiple_choice', 'Simplify i², where i is the imaginary unit.', '["1","−1","i","−i"]'::jsonb, 1, 'By definition, i² = −1.', null, null, null, true, null, null, null, null),
('265515d5-2037-4970-afd7-2def26515b11', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is the modulus of the complex number 3 + 4i?', '["5","7","25","12"]'::jsonb, 0, 'The modulus is √(3² + 4²) = √(9 + 16) = √25 = 5.', null, null, null, true, null, null, null, null),
('82f2daa3-b0b0-4c9f-be83-ca7d3b56b0c9', 'sm_vectors', 'year_11', 'developing', 'multiple_choice', 'What is the magnitude of the vector (6, 8)?', '["10","14","48","100"]'::jsonb, 0, 'Magnitude = √(6² + 8²) = √(36 + 64) = √100 = 10.', null, null, null, true, null, null, null, null),
('e1a9f16e-7ff7-4bbd-9f4b-599e364ceb21', 'sm_vectors', 'year_11', 'foundation', 'multiple_choice', 'Two vectors are perpendicular to each other. What is their dot product?', '["1","−1","0","Undefined"]'::jsonb, 2, 'Perpendicular vectors always have a dot product of 0.', null, null, null, true, null, null, null, null),
('a7f17e19-70ad-40f0-bfc0-d76b0c26931a', 'number_operations', 'grade_3', 'foundation', 'multiple_choice', 'A school fun run sold 6,412 raffle tickets. What is the value of the digit 6 in 6,412?', '["6","60","600","6000"]'::jsonb, 3, 'The 6 is in the thousands place, so its value is 6000.', 'AC9M3N01', null, null, true, null, null, null, null),
('8bedce94-e8fc-4e88-8a38-7c7f514bb6f1', 'number_operations', 'grade_3', 'foundation', 'short_answer', 'Mrs Tan packs 4 lunchboxes with 5 apple slices in each box. How many apple slices does she pack in total?', null, null, '4 groups of 5 is 4 × 5 = 20 apple slices.', 'AC9M3N03', null, null, true, '20', null, null, null),
('901dcd31-d443-467f-91a9-d9d578afff40', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'Mia collected 92 stickers this term. She gave 37 of them to her little sister. How many stickers does Mia have left?', '["45","55","65","129"]'::jsonb, 1, '92 − 37 = 55.', 'AC9M3N04', null, null, true, null, null, null, null),
('240ef8c1-60fa-4578-bf90-c70fc58b5ae0', 'number_operations', 'grade_3', 'foundation', 'multiple_choice', 'Ravi cuts a pizza into 4 equal slices and eats 1 slice. What fraction of the pizza did he eat?', '["1/4","1/3","4/1","1/2"]'::jsonb, 0, 'One slice out of four equal slices is 1/4.', 'AC9M3N06', null, null, true, null, null, null, null),
('789052f2-8392-4aa8-9013-184a5e86ee00', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'Jack buys a pencil for $2 and a ruler for $3 at the school shop. He pays with a $10 note. How much change does he get?', '["$4","$5","$6","$15"]'::jsonb, 1, 'The pencil and ruler together cost $2 + $3 = $5. Change from $10 is $10 − $5 = $5.', 'AC9M3N07', null, null, true, null, null, null, null),
('ed1884fe-4bc5-44b2-9718-38b3189ed382', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'Milo had 52 marbles. He gave some to a friend and has 35 marbles left. Which number sentence can be used to find how many marbles Milo gave away?', '["52 − 35 = 17","52 + 35 = 87","35 − 52 = 17","17 − 35 = 52"]'::jsonb, 0, 'Start with what Milo had and take away what is left: 52 − 35 = 17 marbles given away.', 'AC9M3N04', null, null, true, null, null, null, null),
('a8b1afd2-e0d1-4c10-bc78-e0fcf35bb406', 'number_operations', 'grade_3', 'foundation', 'multiple_choice', 'Chairs are set up in an array of 3 rows with 6 chairs in each row for the school concert. How many chairs are there altogether?', '["9","15","18","21"]'::jsonb, 2, '3 rows of 6 is 3 × 6 = 18 chairs.', 'AC9M3N05', null, null, true, null, null, null, null),
('57b0cffa-6289-44a6-82cb-3104b794d79f', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'A charity bake sale raised $47,325. What is the value of the digit 7 in this amount?', '["7","70","700","7000"]'::jsonb, 3, 'In $47,325 the digit 7 is in the thousands place, so its value is 7000.', 'AC9M4N01', null, null, true, null, null, null, null),
('f651fd9c-2262-430e-8c88-2bbadb1d9717', 'number_operations', 'grade_4', 'developing', 'short_answer', 'Each table at the school trivia night seats 8 people, and 9 tables are set up. How many people can be seated in total?', null, null, '8 people per table × 9 tables = 72.', 'AC9M4N02', null, null, true, '72', null, null, null),
('02c33362-3536-4d1f-b984-9dec81fbf800', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'A toy shop had 452 toys in stock before the school holiday sale. It sold 189 of them during the sale. How many toys are left?', '["273","363","253","263"]'::jsonb, 3, '452 − 189 = 263.', 'AC9M4N03', null, null, true, null, null, null, null),
('885fc393-0504-4ee6-b444-8495374669b6', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'Using an area model, Noah calculates how many seedlings are in 34 rows of 6 seedlings each for the school garden. How many seedlings are there in total?', '["204","214","194","244"]'::jsonb, 0, 'Split 34 into 30 and 4: (30 × 6) + (4 × 6) = 180 + 24 = 204.', 'AC9M4N04', null, null, true, null, null, null, null),
('3b322639-2bba-42ff-8228-377ef77be486', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'Zara ate 1/2 of a block of chocolate. Which of these fractions shows the same amount she ate?', '["2/5","3/6","2/3","1/4"]'::jsonb, 1, '3/6 simplifies to 1/2, so 3/6 and 1/2 represent the same amount.', 'AC9M4N05', null, null, true, null, null, null, null),
('eab18812-c385-447d-957c-9fe1a0b3211f', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'In a long jump competition, four students jumped these distances in metres: 0.45, 0.5, 0.405 and 0.09. Which distance is the longest?', '["0.45 m","0.5 m","0.405 m","0.09 m"]'::jsonb, 1, '0.5 is the same as 0.50, which is greater than 0.45, 0.405 and 0.09.', 'AC9M4N06', null, null, true, null, null, null, null),
('9f1e5798-7d97-4268-97b8-c3ca89c328a9', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'At the canteen, Sam buys 3 juice boxes costing $2 each. How much does he spend in total?', '["$5","$6","$8","$9"]'::jsonb, 1, '3 × $2 = $6.', 'AC9M4N07', null, null, true, null, null, null, null),
('b9244bba-7580-430f-978d-2e4643bcd68b', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'A theme park sold sixty-two thousand, four hundred tickets last year. Which of these shows that number written in digits?', '["6240","62 040","62 400","624 000"]'::jsonb, 2, 'Sixty-two thousand is 62 000, and four hundred more makes 62 400.', 'AC9M5N01', null, null, true, null, null, null, null),
('6cb7aa7f-c502-43ba-a864-2bf0d591dc9f', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'Priya waters her garden with 3/8 of a litre of water in the morning and 2/8 of a litre in the afternoon. How much water does she use in total?', '["1/8 L","5/8 L","5/16 L","6/8 L"]'::jsonb, 1, 'The eighths can be added directly: 3/8 + 2/8 = 5/8 of a litre.', 'AC9M5N05', null, null, true, null, null, null, null),
('f37cd7d3-6c11-4349-83c0-f03a6b6b3454', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'A school orders 8 boxes of exercise books with 25 books in each box. How many exercise books is that altogether?', '["33","160","200","250"]'::jsonb, 2, '8 boxes of 25: 8 × 25 = 200 exercise books.', 'AC9M5N04', null, null, true, null, null, null, null),
('62740b2d-a99b-4272-a081-fde83a817382', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'A fun run course is 3.6 km long. If a relay team runs the full course 100 times over the school term, how many kilometres do they run in total?', '["3.6","36","360","3600"]'::jsonb, 2, 'Multiplying by 100 moves the decimal point two places right: 3.6 × 100 = 360 km.', 'AC9M5N04', null, null, true, null, null, null, null),
('b9e888a8-e8b0-4fb8-a34f-b74c6b6d9ab1', 'number_operations', 'grade_5', 'proficient', 'multiple_choice', 'A class of 40 students voted on their favourite sport. 15% of them chose swimming. How many students chose swimming?', '["4","5","6","8"]'::jsonb, 2, '15% of 40 = 15/100 × 40 = 6.', 'AC9M5N05', null, null, true, null, null, null, null),
('404e535b-f5e7-4379-a27b-9451fafa9ef3', 'number_operations', 'grade_5', 'proficient', 'multiple_choice', 'Ella has $85 saved for school camp. She spends $32 on a sleeping bag and $19 on snacks. How much money does she have left?', '["$24","$54","$44","$34"]'::jsonb, 3, '85 − 32 − 19 = 34.', 'AC9M5N06', null, null, true, null, null, null, null),
('206cede2-0210-4963-868d-d583553275a0', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'A weather app recorded these overnight temperatures across four cities: −2°C, 3°C, −7°C and 0°C. Which city had the coldest temperature?', '["−2°C","3°C","−7°C","0°C"]'::jsonb, 2, 'The further below zero a negative number is, the colder it is. −7°C is the lowest value.', 'AC9M6N01', null, null, true, null, null, null, null),
('7d839664-ff0d-492d-9c4a-235666dc97e0', 'number_operations', 'grade_6', 'developing', 'short_answer', 'In a maths game, a team scores points using the expression 6 + 4 × (5 − 2). What is the team''s total score?', null, null, 'Brackets first: 5 − 2 = 3. Then multiply: 4 × 3 = 12. Then add: 6 + 12 = 18.', 'AC9M6N02', null, null, true, '18', null, null, null),
('65ca8544-cd9a-4e8e-aa65-53ef8aedd472', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'A juice recipe uses 2/3 of a bottle of orange juice, but Mia only wants to make 3/4 of the full recipe. What fraction of a bottle does she need?', '["1/2","5/7","6/7","2/12"]'::jsonb, 0, 'Multiply numerators and denominators: (2×3)/(3×4) = 6/12, which simplifies to 1/2.', 'AC9M6N03', null, null, true, null, null, null, null),
('3521ae83-6ab9-428a-9494-3ae4e7d5a09e', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'A ribbon that is 4.8 m long is cut into pieces that are each 0.6 m long. How many pieces can be cut?', '["0.8","0.08","48","8"]'::jsonb, 3, 'Multiply both numbers by 10 to remove the decimals: 48 ÷ 6 = 8 pieces.', 'AC9M6N03', null, null, true, null, null, null, null),
('e9853db0-dc8c-4a79-8834-12183a4cfe9d', 'number_operations', 'grade_6', 'proficient', 'multiple_choice', 'A $60 jacket is discounted by 25% for an end-of-season sale. What is the sale price?', '["$35","$45","$15","$50"]'::jsonb, 1, '25% of $60 is $15. The new price is $60 − $15 = $45.', 'AC9M6N04', null, null, true, null, null, null, null),
('3bf73ba6-c1d3-41c7-bb32-cca1db6bde97', 'number_operations', 'grade_6', 'proficient', 'short_answer', 'A family''s restaurant bill is $80 before a 10% service charge is added. What is the total amount they must pay?', null, null, '10% of $80 is $8. Total cost is $80 + $8 = $88.', 'AC9M6N05', null, null, true, '$88', ARRAY['88']::text[], null, null),
('a0496bfd-d8e0-46d9-b6af-bbefcd641bf2', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'A survey shows that 3/4 of students walk to school. Written as a decimal, what fraction of students is that?', '["0.34","0.43","0.75","7.5"]'::jsonb, 2, '3/4 means 3 ÷ 4, which equals 0.75.', 'AC9M6N06', null, null, true, null, null, null, null),
('c46988b5-f4e6-47d2-806b-54ff80b87bb8', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'A lift starts at basement level −8 and rises 5 floors. Using integers, what floor is it on now (−8 + 5)?', '["13","3","−13","−3"]'::jsonb, 3, 'Starting at −8 and moving 5 floors up gives −3.', 'AC9M7N02', null, null, true, null, null, null, null),
('313de050-f86d-4513-a3cf-f48c96c07a20', 'number_operations', 'year_7', 'developing', 'short_answer', 'A hiker starts at an elevation of 4 m above sea level. A nearby valley floor sits at −9 m. What is the difference in elevation between the hiker and the valley floor (4 − (−9))?', null, null, 'Subtracting a negative is the same as adding: 4 − (−9) = 4 + 9 = 13 m.', 'AC9M7N02', null, null, true, '13', null, null, null),
('2fc97a40-bd34-4417-a714-a96c102b6413', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'A scuba diver descends at a steady rate of 6 metres per minute below sea level. What is the diver''s change in height after 3 minutes, expressed as −6 × 3?', '["18","−18","−9","9"]'::jsonb, 1, 'A negative times a positive is negative: −6 × 3 = −18 m.', 'AC9M7N02', null, null, true, null, null, null, null),
('f95f13ff-73ec-4cd4-a218-bb81acb3d8e6', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'A social media post is shared by 3 people, and each of those people shares it with 3 new people, and this pattern repeats for a total of 4 rounds of sharing. How many people receive the post in the 4th round alone (3^4)?', '["12","64","81","34"]'::jsonb, 2, '3^4 means 3 × 3 × 3 × 3 = 81.', 'AC9M7N01', null, null, true, null, null, null, null),
('5fc67278-0e64-4736-b656-15f81cc0ecfb', 'number_operations', 'year_7', 'proficient', 'multiple_choice', 'A café orders 3.6 kg of coffee beans every week. How many kilograms of coffee beans does the café order over 8 weeks?', '["26.8 kg","30.8 kg","28.8 kg","21.6 kg"]'::jsonb, 2, '3.6 × 8 = 28.8 kg.', 'AC9M7N04', null, true, true, null, null, null, null),
('dc316ba0-4192-4570-9780-3a43a39a35f5', 'number_operations', 'year_7', 'proficient', 'short_answer', 'A charity fun run collects $6.85 per entrant, and 214 people register. How much money is collected in total?', null, null, '6.85 × 214 = $1465.90.', 'AC9M7N04', null, true, true, '$1465.90', ARRAY['1465.90', '1465.9']::text[], null, null),
('e27f8705-f33b-40b5-abe6-c7bd90613821', 'number_operations', 'year_7', 'proficient', 'multiple_choice', 'A cyclist travels 187.5 km over 7.5 hours at a constant speed. What is the cyclist''s speed in km/h?', '["22.5 km/h","27.5 km/h","20 km/h","25 km/h"]'::jsonb, 3, 'Speed = distance ÷ time = 187.5 ÷ 7.5 = 25 km/h.', 'AC9M7N05', null, true, true, null, null, null, null),
('7a44651e-ab9a-4114-9fc8-1690c629b21c', 'number_operations', 'year_8', 'developing', 'short_answer', 'A diver''s score is calculated using the expression (−3) × 4 + 6, where −3 represents a deduction per fault, 4 is the number of faults, and 6 is a base score. What is the diver''s total score?', null, null, 'Multiply first: (−3) × 4 = −12. Then add: −12 + 6 = −6.', 'AC9M8N03', null, null, true, '−6', ARRAY['-6']::text[], null, null),
('1493a6a4-37c4-44b8-a4dc-bdf8fed2cbe2', 'number_operations', 'year_8', 'developing', 'multiple_choice', 'Amara is converting fractions to decimals for a maths project. Which of these fractions gives a recurring decimal?', '["1/4","1/3","1/2","3/5"]'::jsonb, 1, '1/3 = 0.333... which repeats forever. The others terminate.', 'AC9M8N01', null, null, true, null, null, null, null),
('90fb807a-6108-4f91-87b1-467c592c7f0b', 'number_operations', 'year_8', 'developing', 'multiple_choice', 'While simplifying an algebraic expression for a robotics project, Ty needs to simplify x^5 ÷ x^2. What is the simplified form?', '["x^3","x^7","x^10","x^2.5"]'::jsonb, 0, 'When dividing powers with the same base, subtract the exponents: 5 − 2 = 3.', 'AC9M8N02', null, null, true, null, null, null, null),
('4424b329-41fa-41d1-b667-2db2d5b3bbec', 'number_operations', 'year_8', 'developing', 'multiple_choice', 'A trail mix recipe uses 4 cups of nuts to 8 cups of dried fruit. Simplify this ratio to its simplest form.', '["4:8","2:1","1:12","1:2"]'::jsonb, 3, 'Divide both sides by the highest common factor, 4: 4:8 = 1:2.', 'AC9M8N05', null, null, true, null, null, null, null),
('2f33cf0a-264a-44db-8f9d-55699b5b64c6', 'number_operations', 'year_8', 'developing', 'multiple_choice', 'A laptop priced at $685 increases in price by 12% ahead of a product launch. What is the new price?', '["$757.20","$777.20","$767.20","$702.20"]'::jsonb, 2, '12% of $685 is $82.20. The new price is $685 + $82.20 = $767.20.', 'AC9M8N04', null, true, true, null, null, null, null),
('0ae9f71a-5b92-4524-8bc7-13e55917e978', 'number_operations', 'year_8', 'developing', 'short_answer', 'If 7 identical concert tickets cost $164.50 in total, what is the cost of 12 tickets at the same rate?', null, null, 'Each ticket costs 164.50 ÷ 7 = $23.50. So 12 tickets cost 12 × 23.50 = $282.00.', 'AC9M8N05', null, true, true, '$282.00', ARRAY['282.00', '282', '282.0']::text[], null, null),
('57bbfce9-d36c-4c3e-bb63-8ab24a43fa74', 'number_operations', 'year_9', 'developing', 'multiple_choice', 'A digital storage capacity is represented by (2³)². Simplify this expression as a single power of 2.', '["2⁵","2⁹","4⁶","2⁶"]'::jsonb, 3, 'When raising a power to a power, multiply the exponents: 3 × 2 = 6.', 'AC9M9N01', null, null, true, null, null, null, null),
('7d4e96aa-648a-4d6a-ab43-d8d65280e457', 'number_operations', 'year_9', 'developing', 'multiple_choice', 'A physics formula includes the term 5⁻². Write this as a fraction in simplest form.', '["−25","1/10","1/25","25"]'::jsonb, 2, 'A negative exponent means the reciprocal: 5⁻² = 1/5² = 1/25.', 'AC9M9N01', null, null, true, null, null, null, null),
('73d8b99d-af3a-40fb-8ca2-fe299089215c', 'number_operations', 'year_9', 'developing', 'multiple_choice', 'An architect is working with a length related to √50. Simplify √50 to simplest surd form.', '["10√5","2√5","25√2","5√2"]'::jsonb, 3, '50 = 25 × 2, and √25 = 5, so √50 = 5√2.', 'AC9M9N01', null, null, true, null, null, null, null),
('aaa8bb88-9515-4757-bc38-4149bd566e31', 'number_operations', 'year_9', 'proficient', 'short_answer', 'A square garden bed has an area of 144 m². What is the length of one side of the garden bed?', null, null, '12 × 12 = 144, so the side length is √144 = 12 m.', 'AC9M9N01', null, null, true, '12 m', ARRAY['12']::text[], null, null),
('b13fafbf-d4c9-4e5c-aea8-c80143858572', 'number_operations', 'year_9', 'proficient', 'multiple_choice', 'A virus particle measures 0.000067 m across. Write this measurement in scientific notation.', '["6.7 × 10⁵","6.7 × 10⁻⁴","67 × 10⁻⁶","6.7 × 10⁻⁵"]'::jsonb, 3, 'Move the decimal 5 places right to get 6.7, so the exponent is −5: 6.7 × 10⁻⁵.', 'AC9M9N02', null, null, true, null, null, null, null),
('fbaff0bc-53e5-4488-ad98-2fce8cac537c', 'number_operations', 'year_9', 'proficient', 'short_answer', 'Find the simple interest earned on $3,450 invested at 4.25% p.a. for 3.5 years.', null, null, 'Simple interest = P × R × T = 3450 × 0.0425 × 3.5 = $513.19 (rounded to the nearest cent).', 'AC9M9N02', null, true, true, '$513.19', ARRAY['513.19']::text[], null, null),
('b32a0243-b462-4c90-a2aa-9aa87f309c90', 'number_operations', 'year_10', 'developing', 'multiple_choice', 'Write 45000 in scientific notation.', '["4.5 × 10^5","4.5 × 10^4","4.5 × 10^3","5.5 × 10^4"]'::jsonb, 1, 'Move the decimal point so one non-zero digit remains before it; the number of places moved gives the exponent: 45000 = 4.5 × 10^4.', 'AC9M10N01', null, null, true, null, null, null, null),
('b26bbf0f-a601-4b42-a98c-48023f080bbc', 'number_operations', 'year_10', 'proficient', 'multiple_choice', 'Find the value of a $1000 investment after 2 years at 10% p.a. compound interest.', '["$1100","$1200","$1210","$1300"]'::jsonb, 2, 'Compound interest: 1000 × 1.1² = 1000 × 1.21 = $1210.', 'AC9M10N01', null, null, true, null, null, null, null),
('ff00843a-5a16-4895-90d5-a33fe20a5ca6', 'number_operations', 'year_10', 'developing', 'multiple_choice', 'Simplify: 2^−3', '["−8","1/8","8","−1/8"]'::jsonb, 1, 'A negative exponent means the reciprocal: 2^−3 = 1/2³ = 1/8.', 'AC9M10N01', null, null, true, null, null, null, null),
('904bda3f-a679-4ee5-bcf9-e1a72312636e', 'number_operations', 'year_10', 'proficient', 'multiple_choice', 'Simplify √72 to simplest surd form.', '["6√2","8√3","2√18","36√2"]'::jsonb, 0, '72 = 36 × 2, and √36 = 6, so √72 = 6√2.', 'AC9M10N01', null, null, true, null, null, null, null),
('d423a0cd-68bf-42d5-815e-ccecb203bcc6', 'number_operations', 'year_10', 'proficient', 'multiple_choice', 'What is the cube root of 27?', '["9","3","4","6"]'::jsonb, 1, '3 × 3 × 3 = 27, so the cube root of 27 is 3.', 'AC9M10N01', null, null, true, null, null, null, null),
('e10e329a-885c-4e04-a86d-38d46211122e', 'number_operations', 'year_10', 'proficient', 'multiple_choice', 'Evaluate: 16^(1/2)', '["2","4","8","16"]'::jsonb, 1, 'A power of 1/2 means square root: 16^(1/2) = √16 = 4.', 'AC9M10N01', null, null, true, null, null, null, null),
('8cdc15f6-8c9e-4c68-a92e-b29a71242536', 'number_patterns', 'grade_3', 'foundation', 'multiple_choice', 'A gardener plants tomato seedlings in rows, adding 2 more seedlings than the row before: row 1 has 2, row 2 has 4, row 3 has 6, row 4 has 8. How many seedlings are in row 5?', '["10","9","16","12"]'::jsonb, 0, 'Each row has 2 more seedlings than the last: 2, 4, 6, 8, 10 — row 5 has 10 seedlings (8 + 2).', 'AC9M3A01', null, null, true, null, null, null, null),
('c6047629-3095-49b9-89ce-9f56396799bc', 'number_patterns', 'grade_3', 'foundation', 'multiple_choice', 'A water tank has a leak and loses 3 litres every hour. The tank has 20, then 17, then 14, then 11 litres left after each hour. How much water is left after the next hour?', '["9","8","7","10"]'::jsonb, 1, 'The tank loses 3 litres each hour: 20, 17, 14, 11, 8 — after the next hour, 11 − 3 = 8 litres remain.', 'AC9M3A01', null, null, true, null, null, null, null),
('2e9c24a7-ad65-4def-bbd6-e718831c3066', 'number_patterns', 'grade_3', 'foundation', 'multiple_choice', 'A school fun run tracks the total number of laps completed by the whole class every 10 minutes: 43, 53, 63, 73 laps so far. If the pattern continues, how many laps will be completed after the next 10 minutes?', '["93","80","83","74"]'::jsonb, 2, 'The total laps increase by 10 every 10 minutes: 43, 53, 63, 73, 83 — the next total is 73 + 10 = 83.', 'AC9M3A01', null, null, true, null, null, null, null),
('27e9be6f-8a16-4343-a8ed-97b9836fd4bf', 'number_patterns', 'grade_4', 'developing', 'multiple_choice', 'A café puts out muffins in batches, adding 3 more than the hour before: 3, 6, 9, ___, 15 muffins are on display at the end of hours 1 to 5. How many muffins are on display at the end of hour 4?', '["12","15","9","14"]'::jsonb, 0, 'Each hour adds 3 more muffins than the last: 3, 6, 9, 12, 15 — hour 4 has 12 muffins.', 'AC9M4A01', null, null, true, null, null, null, null),
('11794e2c-3a11-4c5f-8721-297b898ef21c', 'number_patterns', 'grade_4', 'developing', 'multiple_choice', 'A charity''s collection tin starts with 50 toys and gives away 5 toys each day: 50, 45, 40, ___, 30 toys remain after each day. How many toys remain after day 4?', '["30","35","25","40"]'::jsonb, 1, 'Each day 5 toys are given away: 50, 45, 40, 35, 30 — after day 4, 35 toys remain.', 'AC9M4A01', null, null, true, null, null, null, null),
('eaa56829-dc04-4fb1-aacf-8c39351a6aea', 'number_patterns', 'grade_4', 'developing', 'short_answer', 'A plant is 8 cm tall and grows the same amount every week. After one more week it is 15 cm tall. How many centimetres does the plant grow each week?', null, null, 'The plant grew from 8 cm to 15 cm in one week: 15 − 8 = 7 cm growth per week.', 'AC9M4A02', null, null, true, '7', null, null, null),
('13e3708c-35af-423c-b04e-e6206f020edb', 'number_patterns', 'grade_5', 'developing', 'multiple_choice', 'A gym membership fee increases by $7 every year it is renewed, starting at $7 in year 1. Following this pattern, what is the fee in year 4?', '["28","22","35","21"]'::jsonb, 0, 'The fee increases by $7 each year: $7, $14, $21, $28 — year 4’s fee is $28.', 'AC9M5A01', null, null, true, null, null, null, null),
('1f347057-49ff-45d0-886a-6adf2c58c5c6', 'number_patterns', 'grade_5', 'developing', 'multiple_choice', 'A hiker walks the same distance each day of a 100 km trail. The distance remaining is 92 km after day 1, 84 km after day 2, 76 km after day 3. How many kilometres remain after day 4?', '["76","68","84","92"]'::jsonb, 1, 'Each day the hiker covers 8 km: the remaining distance is 100, 92, 84, 76, 68 — after day 4, 68 km remain.', 'AC9M5A01', null, null, true, null, null, null, null),
('413724d7-b33b-4f6a-8abf-630c28857a14', 'number_patterns', 'grade_5', 'developing', 'short_answer', 'Tickets to the school concert are sold in packs of equal size. 6 packs contain a total of 42 tickets. How many tickets are in one pack?', null, null, '42 ÷ 6 = 7, so each pack has 7 tickets.', 'AC9M5A02', null, null, true, '7', null, null, null),
('99c2522a-2e6a-440d-bc3c-6584b544621a', 'number_patterns', 'grade_6', 'developing', 'multiple_choice', 'A carnival game doubles your ticket count, then adds 3 bonus tickets. If you start with 5 tickets, how many do you have after the game?', '["13","8","11","16"]'::jsonb, 0, 'Double the 5 tickets to get 10, then add the 3 bonus tickets: 10 + 3 = 13.', 'AC9M6A01', null, null, true, null, null, null, null),
('3960e6eb-eca2-4f55-82b9-54b591c873f1', 'number_patterns', 'grade_6', 'developing', 'multiple_choice', 'A gardening app triples the number of plants you record, then subtracts 4 for plants that did not survive. If you recorded 6 plants, what number does the app show?', '["18","14","22","10"]'::jsonb, 1, 'Triple 6 to get 18, then subtract 4 for plants that did not survive: 18 − 4 = 14.', 'AC9M6A01', null, null, true, null, null, null, null),
('5ecadc6f-4dc6-4441-b875-2edcab49c2fb', 'number_patterns', 'grade_6', 'developing', 'multiple_choice', 'Five friends split a $45 gardening job payment equally. Using the equation 5n = 45, how much does each friend receive?', '["8","10","9","7"]'::jsonb, 2, '45 ÷ 5 = 9, so each friend receives $9 (n = 9).', 'AC9M6A02', null, null, true, null, null, null, null),
('97842e1a-eb3a-4b59-93c6-d22c807daecc', 'number_patterns', 'grade_6', 'developing', 'short_answer', 'After spending $12 on lunch, Ravi has $20 left in his wallet. Using the equation n − 12 = 20, how much money did he start with?', null, null, '20 + 12 = 32, so Ravi started with $32 (n = 32).', 'AC9M6A02', null, null, true, '32', null, null, null),
('9ca182f3-aa85-4808-9eac-0ba9d53a7a73', 'algebra_equations', 'year_7', 'foundation', 'multiple_choice', 'Jayden had some marbles. After his friend gave him 9 more, he had 15 marbles in total. How many marbles did Jayden start with?', '["7","9","6","24"]'::jsonb, 2, 'Let x = marbles Jayden started with. x + 9 = 15, so x = 15 − 9 = 6.', 'AC9M7A02', null, null, true, null, null, null, null),
('1034b9c8-fcdb-4e09-83e0-7a6acb0b5534', 'algebra_equations', 'year_7', 'developing', 'short_answer', 'Sam starts with $3 saved and adds $2 to his money box every week. After how many weeks, w, will he have saved $11 in total?', null, null, 'Subtract the initial $3: 2w = 8. Divide by 2: w = 4 weeks.', 'AC9M7A02', null, null, true, 'w = 4', ARRAY['4']::text[], null, null),
('2ec5007b-d101-4f23-971a-aa1ff1ccbd92', 'algebra_equations', 'year_7', 'foundation', 'multiple_choice', 'After giving away 5 of his trading cards, Oliver has 9 left. How many trading cards did he start with?', '["4","9","45","14"]'::jsonb, 3, 'Let x = the number Oliver started with. x − 5 = 9, so x = 9 + 5 = 14.', 'AC9M7A02', null, null, true, null, null, null, null),
('6265866a-edcd-44cb-9263-12c42b079adc', 'algebra_equations', 'year_7', 'developing', 'short_answer', 'A savings challenge: Chloe saves $2 in week 1, $5 in week 2, $8 in week 3, and $11 in week 4, saving $3 more than the previous week each time. Following this pattern, how much does she save in week 5?', null, null, 'The pattern increases by $3 each week. 11 + 3 = $14.', 'AC9M7A01', null, null, true, '$14', ARRAY['14']::text[], null, null),
('5fed5491-2c68-4447-b6d8-66e1657075a0', 'algebra_equations', 'year_8', 'developing', 'short_answer', 'A market stall''s profit, in dollars, is modelled as P = 4x − 2y, where x is the number of items sold and y is the number of hours worked. What is the profit when x = 3 and y = 5?', null, null, 'Substitute the values: (4 × 3) − (2 × 5) = 12 − 10 = $2.', 'AC9M8A01', null, null, true, '$2', ARRAY['2']::text[], null, null),
('1efad3ea-77b7-4da3-b2e5-7440a0f5633e', 'algebra_equations', 'year_8', 'developing', 'multiple_choice', 'Three identical garden beds are laid out in a row, each with length (x + 4) metres. Write an expanded expression for their combined length: 3(x + 4).', '["3x + 12","3x + 4","x + 12","3x + 7"]'::jsonb, 0, 'Multiply each term inside the brackets by 3: 3 × x + 3 × 4 = 3x + 12 metres.', 'AC9M8A01', null, null, true, null, null, null, null),
('36863242-edcc-4ec0-972d-13e1d7adc1ea', 'algebra_equations', 'year_8', 'proficient', 'multiple_choice', 'A gift card''s balance was tripled by a store promotion, then $5 was spent on a coffee, leaving $16 on the card. What was the original balance, x, in dollars?', '["x = 5","x = 7","x = 11","x = 21"]'::jsonb, 1, 'Add 5 to both sides: 3x = 21. Divide by 3: x = $7.', 'AC9M8A02', null, null, true, null, null, null, null),
('38bb97ff-90c9-4a51-a22b-6bd878efc1c9', 'algebra_equations', 'year_9', 'proficient', 'multiple_choice', 'Solve the inequality 3x − 5 > 13.', '["x > 6","x > 8","x < 6","x > 18"]'::jsonb, 0, 'Add 5 to both sides: 3x > 18. Divide both sides by 3: x > 6.', 'AC9M9A02', null, null, true, null, null, null, null),
('cdb1676d-faf1-4a1a-b5a8-6abd8d8fcd55', 'algebra_equations', 'year_9', 'proficient', 'multiple_choice', 'Expand and simplify (x + 4)².', '["x² + 16","x² + 8x + 16","x² + 4x + 16","x² + 8x + 8"]'::jsonb, 1, '(x + 4)² = (x + 4)(x + 4) = x² + 4x + 4x + 16 = x² + 8x + 16.', 'AC9M9A02', null, null, true, null, null, null, null),
('2e3ec299-6c90-4274-a80c-063637322cad', 'algebra_equations', 'year_9', 'developing', 'short_answer', 'The perimeter of a triangular garden bed is given by the expression 4x + 12. Factorise this expression to write it as a product of two factors.', null, null, '4 is the highest common factor of 4x and 12: 4x + 12 = 4(x + 3).', 'AC9M9A02', null, null, true, '4(x + 3)', null, null, null),
('2b040909-ef98-42cd-b62e-15d11622c042', 'algebra_equations', 'year_9', 'proficient', 'short_answer', 'If a = −3 and b = 5, what is the value of 2a² − b?', null, null, 'a² = (−3)² = 9, so 2a² = 18. Then 18 − 5 = 13.', 'AC9M9A02', null, null, true, '13', null, null, null),
('c831234d-63b0-48fc-a865-d80d2c0d00fc', 'algebra_equations', 'year_10', 'proficient', 'multiple_choice', 'If f(x) = 2x² − 3, what is f(4)?', '["32","31","5","29"]'::jsonb, 3, 'f(4) = 2(4)² − 3 = 32 − 3 = 29.', 'AC9M10A02', null, null, true, null, null, null, null),
('5cd03b0a-fa8f-4aaf-a9ab-52d0e9c65fd9', 'algebra_equations', 'year_10', 'proficient', 'multiple_choice', 'What are the solutions of x² − 5x + 6 = 0?', '["x = 2 or x = 3","x = −2 or x = −3","x = 1 or x = 6","x = 6 or x = −1"]'::jsonb, 0, 'Factorise: (x − 2)(x − 3) = 0, so x = 2 or x = 3.', 'AC9M10A01', null, null, true, null, null, null, null),
('9eea03a2-7aaf-4102-9dae-7d1af6e23012', 'algebra_equations', 'year_10', 'proficient', 'multiple_choice', 'If f(x) = x² − 5, what is f(3)?', '["−2","4","9","6"]'::jsonb, 1, 'f(3) = 3² − 5 = 9 − 5 = 4.', 'AC9M10A02', null, null, true, null, null, null, null),
('9190e288-22eb-429b-bbff-ad3610605c4c', 'geometry_measurement', 'year_10', 'proficient', 'multiple_choice', 'What is the volume of a cylinder with radius 5 cm and height 10 cm? (use π ≈ 3.14)', '["785 cm³","157 cm³","835 cm³","79 cm³"]'::jsonb, 0, 'V = πr²h = 3.14 × 5² × 10 = 785 cm³.', 'AC9M10M01', null, null, true, null, null, null, null),
('22ac34c3-6ca4-41f6-a24b-c44d778edee9', 'geometry_measurement', 'year_10', 'proficient', 'multiple_choice', 'What is the volume of a sphere with radius 3 cm? (use π ≈ 3.14, V = 4/3πr³)', '["113.1 cm³","84.8 cm³","37.7 cm³","339.1 cm³"]'::jsonb, 0, 'V = 4/3 × 3.14 × 3³ = 4/3 × 3.14 × 27 = 113.1 cm³.', 'AC9M10M01', null, null, true, null, null, null, null),
('b353a08f-7d72-48af-833a-46de67966067', 'geometry_measurement', 'year_10', 'proficient', 'multiple_choice', 'What is the volume of a cone with radius 3 cm and height 9 cm? (use π ≈ 3.14, V = 1/3πr²h)', '["84.8 cm³","254.3 cm³","28.3 cm³","169.6 cm³"]'::jsonb, 0, 'V = 1/3 × 3.14 × 3² × 9 = 1/3 × 3.14 × 81 = 84.8 cm³.', 'AC9M10M01', null, null, true, null, null, null, null),
('05a57552-ed53-4b9d-831c-484584279528', 'statistics_probability', 'grade_3', 'foundation', 'multiple_choice', 'A class voted for their favourite fruit. Here are the tally results:
Fruit   | Tally
Apples  | ||||
Bananas | ||
Oranges | |||
Which fruit did the most students choose?', '["Apples","Bananas","Oranges","They are equal"]'::jsonb, 0, 'Apples has 4 tally marks, more than Bananas (2) or Oranges (3).', 'AC9M3ST01', null, null, true, null, null, null, null),
('05719c4f-9249-49e6-9b94-0b181e02e565', 'statistics_probability', 'grade_3', 'foundation', 'multiple_choice', 'The pictogram shows the pets chosen as favourites by a class. How many more students chose Cats than Dogs?', '["1","2","3","8"]'::jsonb, 1, 'Cats has 5 paw prints and Dogs has 3, and each paw print stands for 1 student: 5 − 3 = 2 more students chose Cats.', 'AC9M3ST01', null, null, true, null, null, null, null),
('4f7789eb-70d3-4156-accc-9e4b09e89db6', 'statistics_probability', 'grade_3', 'developing', 'multiple_choice', 'A class kept a record of the pets owned by its students:
Pet  | Number of pets
Dogs | 6
Cats | 4
Fish | 2
How many pets were counted in total?', '["10","12","6","8"]'::jsonb, 1, '6 + 4 + 2 = 12 pets in total.', 'AC9M3ST01', null, null, true, null, null, null, null),
('0e92e0f3-a5aa-4263-9f92-ffd09f22a318', 'statistics_probability', 'grade_4', 'developing', 'multiple_choice', 'A column graph shows how many books a class read each day:
Day       | Books
Monday    | 3
Tuesday   | 5
Wednesday | 2
Thursday  | 4
On which day were the fewest books read?', '["Monday","Tuesday","Wednesday","Thursday"]'::jsonb, 2, 'Wednesday has the smallest value, 2 books.', 'AC9M4ST01', null, null, true, null, null, null, null),
('3cc0f8f9-eaea-4a3f-a2a1-071a073e9eb9', 'statistics_probability', 'grade_4', 'developing', 'multiple_choice', 'A survey of 16 students asked their favourite sport:
Sport   | Students
Soccer  | 8
Netball | 5
Tennis  | 3
What fraction of the 16 students chose soccer?', '["1/2","1/3","1/4","3/8"]'::jsonb, 0, '8 out of 16 students chose soccer: 8/16 simplifies to 1/2.', 'AC9M4ST01', null, null, true, null, null, null, null),
('dadda4b0-cbba-44f0-a743-2d224a1902a0', 'statistics_probability', 'grade_4', 'developing', 'multiple_choice', 'The table shows the number of goals scored by a soccer team in 5 matches:
Match | Goals
1     | 9
2     | 2
3     | 2
4     | 2
5     | 8
What is the mode of the goals scored?', '["2","9","10","8"]'::jsonb, 0, 'The mode is the most frequent value. The team scored 2 goals in three of the five matches.', 'AC9M4ST01', null, null, true, null, null, null, null),
('22633c3a-dee6-4cf1-8a3d-78db545838a8', 'statistics_probability', 'grade_5', 'developing', 'multiple_choice', 'A picture graph shows the fruit sold at the canteen. Each ◆ stands for 4 pieces of fruit.
Apples:  ◆ ◆ ◆
Bananas: ◆ ◆ ◆ ◆ ◆
Pears:   ◆ ◆
How many bananas were sold?', '["5","9","20","24"]'::jsonb, 2, 'Bananas have 5 symbols and each symbol stands for 4 pieces of fruit: 5 × 4 = 20 bananas.', 'AC9M5ST01', null, null, true, null, null, null, null),
('94fed85d-71e8-407d-97a9-3e2c5a7bc803', 'statistics_probability', 'grade_5', 'foundation', 'multiple_choice', 'The dot plot shows how many books each student in a group borrowed from the library. How many students are in the group?', '["4","8","10","22"]'::jsonb, 1, 'Count every dot, because each dot stands for one student: 1 + 2 + 3 + 2 = 8 students.', 'AC9M5ST01', null, null, true, null, null, null, null),
('3635ff5d-9926-4dea-b316-50f847a12e1d', 'statistics_probability', 'grade_5', 'developing', 'multiple_choice', 'The bar chart shows how many laps each student ran. How many more laps did Isla run than Noah?', '["3","5","6","17"]'::jsonb, 1, 'Isla ran 11 laps and Noah ran 6: 11 − 6 = 5 more laps.', 'AC9M5ST01', null, null, true, null, null, null, null),
('17979ab6-55da-43b2-96eb-384c0d3f1bf1', 'statistics_probability', 'grade_6', 'proficient', 'multiple_choice', 'The overnight temperature (°C) was recorded for 6 nights:
Night | Temp (°C)
1     | 4
2     | 8
3     | 6
4     | 2
5     | 10
6     | 12
What is the median overnight temperature?', '["6","7","8","9"]'::jsonb, 1, 'Ordered: 2, 4, 6, 8, 10, 12. With 6 values, the median is the mean of the two middle values: (6 + 8) ÷ 2 = 7.', 'AC9M6ST01', null, null, true, null, null, null, null),
('8bee9e7e-b126-4b7f-88cf-9b807f7bc89b', 'statistics_probability', 'grade_6', 'developing', 'multiple_choice', 'A café recorded the number of coffees sold each hour it was open:
Hour  | Coffees sold
1     | 2
2     | 6
3     | 8
4     | 10
5     | 14
What is the mode of the coffees sold per hour?', '["There is no mode","14","6","8"]'::jsonb, 0, 'Every value (2, 6, 8, 10, 14) appears exactly once, so there is no mode.', 'AC9M6ST01', null, null, true, null, null, null, null),
('78e484a8-d49c-4e70-b0a0-a48f0d120f41', 'statistics_probability', 'grade_6', 'developing', 'multiple_choice', 'A hiker recorded the distance (km) walked on 7 different days:
Day | Distance (km)
1   | 5
2   | 8
3   | 5
4   | 3
5   | 9
6   | 5
7   | 7
What is the range of the distances walked?', '["5","6","9","4"]'::jsonb, 1, 'Range = max − min = 9 − 3 = 6.', 'AC9M6ST01', null, null, true, null, null, null, null),
('7ae20c34-1e76-4ccb-bea8-715be3833434', 'statistics_probability', 'year_7', 'developing', 'multiple_choice', 'A bag contains counters of two colours:
Colour | Count
Red    | 4
Blue   | 6
What is the probability of drawing a blue counter?', '["3/5","2/5","4/10","6/4"]'::jsonb, 0, 'There are 6 blue counters out of 10 total: 6/10 simplifies to 3/5.', 'AC9M7P01', null, null, true, null, null, null, null),
('01a71c8b-d3c3-45b7-a9f9-aec9fb89aa2f', 'statistics_probability', 'year_7', 'developing', 'multiple_choice', 'The weather bureau reports that the probability it rains tomorrow is 0.3. What is the probability that it does NOT rain?', '["0.3","0.7","1.3","0"]'::jsonb, 1, 'Probabilities of complementary events add to 1: 1 − 0.3 = 0.7.', 'AC9M7P02', null, null, true, null, null, null, null),
('24ca0892-e742-40b3-90d2-bacd6f042369', 'statistics_probability', 'year_7', 'developing', 'short_answer', 'A spinner has 8 equal sections numbered 1 to 8. What is the probability, as a fraction in simplest form, of landing on a number greater than 6?', null, null, 'Numbers greater than 6 are 7 and 8 — that is 2 out of 8 sections, which simplifies to 1/4.', 'AC9M7P01', null, null, true, '1/4', ARRAY['2/8', '0.25', '25%']::text[], null, null),
('c5c7eb76-54bf-4f9c-b00b-44897e638c16', 'statistics_probability', 'year_8', 'advanced', 'multiple_choice', 'A survey of 60 Year 8 students asked whether they own a pet, split by whether they are a day student or a boarder:
            | Owns a pet | No pet | Total
Day student | 24         | 16     | 40
Boarder     | 9          | 11     | 20
Total       | 33         | 27     | 60
What is the probability that a randomly selected student is a boarder who owns a pet?', '["3/20","9/60","9/20","11/60"]'::jsonb, 0, '9 of the 60 students are boarders who own a pet: 9/60 simplifies to 3/20.', 'AC9M8ST02', null, null, true, null, null, null, null),
('a5905cfb-1498-4cc9-b88c-b66171e8b927', 'statistics_probability', 'year_8', 'proficient', 'multiple_choice', 'The times (in seconds) for 5 runners in a 100 m sprint were:
Runner | Time (s)
A      | 15.2
B      | 20.1
C      | 12.8
D      | 14.6
E      | 13.9
What is the median race time?', '["14.6","13.9","15.2","14.2"]'::jsonb, 0, 'Ordered: 12.8, 13.9, 14.6, 15.2, 20.1. With 5 values, the median is the 3rd value: 14.6.', 'AC9M8ST01', null, null, true, null, null, null, null),
('1c05508f-88a4-44e6-92c3-ef70bfe815f8', 'statistics_probability', 'year_8', 'developing', 'short_answer', 'A shoe shop recorded the shoe sizes sold to 5 customers:
Customer | Shoe size
1        | 8
2        | 2
3        | 16
4        | 4
5        | 10
What is the range of the shoe sizes sold?', null, null, 'Range = max − min = 16 − 2 = 14.', 'AC9M8ST01', null, null, true, '14', ARRAY['14 sizes']::text[], null, null),
('ad5e5694-03c5-45e1-80ae-e76b2276f813', 'statistics_probability', 'year_9', 'developing', 'multiple_choice', 'On a given day, the probability of rain is 0.5, and the probability of strong wind is 0.4. These two events are independent. What is the probability that it rains AND is windy on that day?', '["0.9","0.1","0.5","0.2"]'::jsonb, 3, 'For independent events, P(A and B) = P(A) × P(B) = 0.5 × 0.4 = 0.2.', 'AC9M9P01', null, null, true, null, null, null, null),
('58bfdf43-2257-4814-9ae8-879911ca29b1', 'statistics_probability', 'year_9', 'proficient', 'multiple_choice', 'A card is drawn from a standard 52-card deck. Let A = drawing a heart, with P(A) = 0.25, and B = drawing a spade, with P(B) = 0.25. A card cannot be both a heart and a spade, so A and B are mutually exclusive. What is P(A or B)?', '["0.5","0.0625","0.25","1"]'::jsonb, 0, 'For mutually exclusive events, P(A or B) = P(A) + P(B) = 0.25 + 0.25 = 0.5.', 'AC9M9P01', null, null, true, null, null, null, null),
('ef259b67-35f8-4296-ac80-2e647796ccf0', 'statistics_probability', 'year_9', 'developing', 'multiple_choice', 'A quality inspector finds that the probability a light bulb fails a test is 0.1. What is the probability that a randomly chosen bulb passes the test?', '["0.1","0.9","1.1","0"]'::jsonb, 1, 'Probabilities of complementary events add to 1: 1 − 0.1 = 0.9.', 'AC9M9P02', null, null, true, null, null, null, null),
('33ba0bde-9e60-4363-b071-94f8999ec83e', 'statistics_probability', 'year_10', 'developing', 'multiple_choice', 'A data set has Q1 = 10 and Q3 = 18. What is the interquartile range (IQR)?', '["8","18","10","19"]'::jsonb, 0, 'IQR = Q3 − Q1 = 18 − 10 = 8.', 'AC9M10ST01', null, null, true, null, null, null, null),
('1627fa12-a6e1-42f8-bb1f-9234b9c854a7', 'statistics_probability', 'year_10', 'developing', 'multiple_choice', 'A data set has Q1 = 15 and Q3 = 25. What is the interquartile range (IQR)?', '["25","15","26","10"]'::jsonb, 3, 'IQR = Q3 − Q1 = 25 − 15 = 10.', 'AC9M10ST01', null, null, true, null, null, null, null),
('b38473c1-47fc-4301-a8cc-5bd40adbe16f', 'statistics_probability', 'year_10', 'developing', 'multiple_choice', 'An ordered data set is: 2, 4, 5, 7, 9, 12, 15. What is the median of this data set?', '["5","7","9","4"]'::jsonb, 1, 'With 7 values, the median is the 4th value: 7.', 'AC9M10ST01', null, null, true, null, null, null, null),
('623b4eb3-bc36-4ee6-ad22-f40f68a81bec', 'reading_comprehension', 'grade_3', 'foundation', 'multiple_choice', 'Read: "The puppy chased its tail in circles until it got dizzy and flopped onto the grass." What happened after the puppy chased its tail?', '["It ran away","It fell asleep","It chased a cat","It flopped onto the grass"]'::jsonb, 3, 'The passage says the puppy "flopped onto the grass" after getting dizzy from chasing its tail.', 'AC9E3LY06', null, null, true, null, null, null, null),
('09b17030-e907-4497-a0ba-49ffcd93f568', 'reading_comprehension', 'grade_3', 'developing', 'multiple_choice', 'Read: "Mia forgot her umbrella, so she got soaked walking home in the rain." Why did Mia get soaked?', '["She dropped her umbrella","She stood in a puddle","She forgot her umbrella","She walked too slowly"]'::jsonb, 2, 'The word "so" signals the reason: Mia forgot her umbrella, which is why she got soaked.', 'AC9E3LY06', null, null, true, null, null, null, null),
('4b595291-84d1-4e63-be7e-5dee4e35c421', 'reading_comprehension', 'grade_4', 'developing', 'multiple_choice', 'Read: "Even though Sam was scared of the dark, he walked into the basement to find the flashlight for his dad." What can you tell about Sam?', '["He was looking for a toy","He was brave despite his fear","He was not afraid of anything","He refused to help his dad"]'::jsonb, 1, 'Sam went into the dark basement even though he was scared, showing he acted bravely despite his fear.', 'AC9E4LY07', null, null, true, null, null, null, null),
('43ff48d0-9ead-4b89-848e-df4e9d20f7a2', 'reading_comprehension', 'grade_4', 'developing', 'multiple_choice', 'Read: "The recipe said to bake the cake for 30 minutes, but after 20 minutes it already smelled burnt." What might happen next?', '["The cake may need to be checked or removed early","The cake will taste better","The oven will turn off by itself","The recipe was wrong about the ingredients"]'::jsonb, 0, 'A burnt smell before the timer ends suggests the cake should be checked, since it may be overcooking.', 'AC9E4LY07', null, null, true, null, null, null, null),
('770bdf3e-1561-40a5-b3d1-53064b6b431c', 'reading_comprehension', 'grade_5', 'developing', 'multiple_choice', 'Read: "Even though the shop was closing, the shopkeeper let the child search a little longer for her lost coin." What does this show about the shopkeeper?', '["He was in a hurry to leave","He was patient and kind","He disliked children","He wanted to close early"]'::jsonb, 1, 'Letting the child keep searching despite closing time shows the shopkeeper being patient and kind.', 'AC9E5LY07', null, null, true, null, null, null, null),
('6b2d3c0d-2330-4040-9a4e-273c6ffb690e', 'reading_comprehension', 'grade_5', 'proficient', 'multiple_choice', 'Read: "The old dog no longer chased balls, but its tail still wagged the moment its owner walked through the door." What does this suggest about the dog?', '["It is a puppy learning new tricks","It is afraid of its owner","It is older and slower, but still loves its owner","It no longer likes its owner"]'::jsonb, 2, 'The dog''s slower behaviour paired with its wagging tail suggests age has not changed its affection for its owner.', 'AC9E5LY07', null, null, true, null, null, null, null),
('98be739d-2fde-47b4-9c42-69962c3c5031', 'reading_comprehension', 'grade_6', 'developing', 'multiple_choice', 'A story told from the perspective of a character using "I" and "me" is written in which point of view?', '["Third person omniscient","First person","Second person","Third person limited"]'::jsonb, 1, 'First person narration uses "I" and "me" because the narrator is a character inside the story.', 'AC9E6LE07', null, null, true, null, null, null, null),
('328d774b-e27a-49d0-bc8b-be509b424240', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'Read: "The coach benched their star player for missing practice, even though it meant a tougher game ahead." What value does this show the coach holds?', '["Discipline matters more than winning","Winning is the only priority","Practice is unimportant","Star players deserve special treatment"]'::jsonb, 0, 'Choosing to bench a key player despite the cost to the team shows the coach values discipline over winning.', 'AC9E6LY08', null, null, true, null, null, null, null),
('84ebf2ed-7779-4e09-bcae-e390049ba658', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'Read: "The classroom was a zoo the moment the teacher stepped out." This sentence mainly uses which literary device?', '["Simile","Metaphor","Onomatopoeia","Alliteration"]'::jsonb, 1, 'Calling the classroom "a zoo" directly, without using "like" or "as", makes this a metaphor.', 'AC9E7LE05', null, null, true, null, null, null, null),
('33c43391-43cc-458f-ba46-227185b1a029', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'Read: "She smiled and wished them luck, but her clenched fists told a different story." What technique is being used here?', '["A flashback to an earlier event","Dialogue between two characters","Contrast between words and actions to reveal true feelings","A direct statement of her feelings"]'::jsonb, 2, 'The gap between her smiling words and clenched fists shows the reader her true feelings without stating them directly.', 'AC9E7LE05', null, null, true, null, null, null, null),
('1933a286-11e0-4eaa-89c8-019c574bdb87', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'Read: "The committee ''carefully considered'' the proposal for three years before rejecting it in a five-minute meeting." The phrase "carefully considered" is likely being used:', '["To describe a scientific process","Ironically, to suggest the opposite was true","Literally, to praise the committee","As a direct quotation from the proposal"]'::jsonb, 1, 'The contrast between three years of "careful" consideration and a five-minute rejection signals irony.', 'AC9E8LE05', null, null, true, null, null, null, null),
('feca9da2-0898-43b8-8692-6b5b5522d2eb', 'reading_literary_analysis', 'year_8', 'developing', 'multiple_choice', 'What is the primary purpose of a topic sentence in a paragraph?', '["To state the main idea the paragraph will develop","To conclude the paragraph","To provide a citation","To ask a rhetorical question"]'::jsonb, 0, 'A topic sentence introduces the main idea that the rest of the paragraph explains or supports.', 'AC9E8LY07', null, null, true, null, null, null, null),
('27871b25-bb65-41f1-8e4b-7a279d3863a2', 'reading_literary_analysis', 'year_9', 'advanced', 'multiple_choice', 'A brief, exaggerated imitation of another work, created for comic effect, is called a:', '["Elegy","Parody","Soliloquy","Satire"]'::jsonb, 1, 'A parody humorously imitates the style of another work, whereas satire more broadly criticises a subject.', 'AC9E9LE04', null, null, true, null, null, null, null),
('c711af90-db1d-490b-bd37-0bfaeec82ce2', 'reading_literary_analysis', 'year_9', 'proficient', 'multiple_choice', 'Read: "Progress," the mayor announced, standing before the newly bulldozed park. What is the effect of placing "Progress" before describing the bulldozed park?', '["It shows the mayor dislikes progress","It is simply a neutral description","It creates irony by contrasting the word with the destruction shown","It proves the mayor is honest"]'::jsonb, 2, 'Opening with "Progress" right before revealing a destroyed park creates a jarring, ironic contrast.', 'AC9E9LE04', null, null, true, null, null, null, null),
('436f667e-877d-420c-bbac-7fe10db6b9bd', 'reading_literary_analysis', 'year_10', 'advanced', 'multiple_choice', 'In a persuasive text, an appeal to the audience''s emotions is known as:', '["Kairos","Pathos","Logos","Ethos"]'::jsonb, 1, 'Pathos refers to a persuasive appeal to the audience''s emotions, as distinct from logos (logic) and ethos (credibility).', 'AC9E10LE05', null, null, true, null, null, null, null),
('a06f3979-5b58-46d5-a0e3-698f7430b297', 'reading_literary_analysis', 'year_10', 'proficient', 'multiple_choice', 'Read: "The report concluded that further research was needed, a phrase repeated in every study the company had funded for a decade." What does this suggest about the company''s intentions?', '["It may be deliberately delaying a definitive conclusion","It is committed to rapid scientific progress","It has already solved the problem","It disagrees with all its own research"]'::jsonb, 0, 'A decade of studies all reaching the same inconclusive result suggests the delay may be intentional rather than accidental.', 'AC9E10LY07', null, null, true, null, null, null, null),
('18b155bb-548c-4040-9968-5522e31026cb', 'reading_comprehension', 'grade_3', 'developing', 'multiple_choice', 'Read: "Ben planted a seed and watered it every day until a tiny green sprout appeared." What lesson does this story teach?', '["Seeds grow without water","Plants grow overnight","Watering plants is unnecessary","Patience and care lead to growth"]'::jsonb, 3, 'Ben''s daily care over time, ending in a sprout, shows that patience and care lead to results.', 'AC9E3LY06', null, null, true, null, null, null, null),
('ee79bbce-3912-4e91-bd70-d0589438a95d', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'Read: "Lily wanted to join the soccer team, but she practised kicking a ball alone in her backyard for weeks first." What does this show about Lily?', '["She is not a team player","She gave up on her goal","She prepares before taking on a challenge","She dislikes soccer"]'::jsonb, 2, 'Practising alone for weeks before joining shows Lily prepares herself before facing a new challenge.', 'AC9E4LY07', null, null, true, null, null, null, null),
('fbb0f1ed-8775-4083-9e1e-ef902c7fe830', 'reading_comprehension', 'grade_5', 'proficient', 'multiple_choice', 'Read: "The librarian whispered even when the library was empty, out of habit." What does this detail suggest about the librarian?', '["The librarian is afraid of being heard","Years of habit shape behaviour even when it is not needed","The librarian dislikes silence","The library is never empty"]'::jsonb, 1, 'Whispering out of habit, even alone, shows how a long-practised behaviour can continue automatically.', 'AC9E5LY07', null, null, true, null, null, null, null),
('6bb7f299-1ee6-49a3-b7a1-9be4915d8ffb', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'Read: "The map was old and torn, but the explorer trusted it more than the shiny new one in his pocket." What can you infer about the explorer?', '["He values experience and familiarity over newness","He dislikes maps in general","He is lost without any map","He prefers new technology"]'::jsonb, 0, 'Trusting the old, worn map over a new one suggests the explorer values familiarity and proven reliability.', 'AC9E6LY08', null, null, true, null, null, null, null),
('7e00dce8-0d74-4a87-a49e-2c0c5debd1ed', 'reading_literary_analysis', 'year_7', 'developing', 'multiple_choice', 'Read: "The crowd fell silent the moment the conductor raised his baton." What is the effect of this sentence?', '["It shows the audience was bored","It suggests the concert had ended","It describes the conductor leaving the stage","It builds anticipation before the music begins"]'::jsonb, 3, 'The sudden silence right before the baton rises creates a sense of anticipation for what is about to happen.', 'AC9E7LE05', null, null, true, null, null, null, null),
('f5f03776-8a15-41a2-9526-81c26f13d799', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'Read: "He apologised with his mouth, but his eyes never left his phone." What technique is the author using?', '["Foreshadowing a future event","A direct statement of the character''s honesty","Contrasting words and actions to reveal insincerity","A literal description of an apology"]'::jsonb, 2, 'Placing the spoken apology next to the distracted action reveals that the apology was not sincere.', 'AC9E8LE05', null, null, true, null, null, null, null),
('c9b26a99-93a8-4f9e-a2ca-d3d179f86c82', 'reading_literary_analysis', 'year_9', 'proficient', 'multiple_choice', 'Read: "The factory''s brochure called it a ''family,'' though most employees had never met the owner." What is implied by this sentence?', '["The factory is small and close-knit","The word \"family\" may be misleading marketing language","The employees are all related","The owner visits often"]'::jsonb, 1, 'The contrast between the word "family" and employees never meeting the owner suggests the term is used loosely, perhaps for marketing effect.', 'AC9E9LY07', null, null, true, null, null, null, null),
('ef3f93b1-2b8b-4db2-8299-e13112850520', 'reading_literary_analysis', 'year_10', 'advanced', 'multiple_choice', 'Read: "The senator promised transparency, then closed the meeting to the public for the third time that year." What rhetorical effect does this sequence create?', '["It exposes a contradiction between the senator''s words and actions","It confirms the senator kept their promise","It shows the senator dislikes public meetings","It has no particular effect"]'::jsonb, 0, 'Stating a promise of transparency immediately before describing closed meetings highlights the contradiction between word and deed.', 'AC9E10LE05', null, null, true, null, null, null, null),
('42b696fb-1053-48fa-9656-45a4e5141a7b', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which sentence is punctuated correctly?', '["my dog is called max.","My dog is called max","My dog is called Max.","My Dog is called max"]'::jsonb, 2, 'Sentences start with a capital letter, names are capitalised, and statements end with a full stop.', 'AC9E3LA05', null, null, true, null, null, null, null),
('aab3ff12-c8b9-4ba9-965f-3186716d33f7', 'grammar_punctuation', 'grade_3', 'developing', 'multiple_choice', 'Which word correctly completes: ''I ___ to the park yesterday.''', '["goes","going","went","go"]'::jsonb, 2, '''Went'' is the past tense of ''go'', matching the word ''yesterday''.', 'AC9E3LA06', null, null, true, null, null, null, null),
('83502520-39b2-4d5f-8508-a10b47070e8f', 'grammar_punctuation', 'grade_4', 'developing', 'multiple_choice', 'Which sentence uses "there", "their", or "they''re" correctly?', '["Their going to the park.","They''re going to the park.","There going to the park.","They is going to the park."]'::jsonb, 1, '''They''re'' is the contraction of ''they are'', which fits before ''going''.', 'AC9E4LA07', null, null, true, null, null, null, null),
('8d305fb5-75f6-4354-99df-5b2252eb4b8a', 'grammar_punctuation', 'grade_4', 'developing', 'multiple_choice', 'Which sentence uses commas correctly in a list?', '["I packed apples, bananas, and grapes.","I packed apples bananas and grapes.","I packed apples, bananas and, grapes.","I packed, apples, bananas, and grapes."]'::jsonb, 0, 'Commas separate each item in a list, with the last item usually joined by "and".', 'AC9E4LA07', null, null, true, null, null, null, null),
('4bd961ca-c77a-40b6-85dd-48a1e56447c0', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which sentence uses the correct homophone?', '["Their going to there house over they''re.","There going to their house over they''re.","They''re going to they''re house over their.","They''re going to their house over there."]'::jsonb, 3, '''They''re'' = they are, ''their'' = possession, ''there'' = a place. Only the first sentence uses all three correctly.', 'AC9E5LA08', null, null, true, null, null, null, null),
('6c1a9c18-df74-41d7-b403-81292d5c89d7', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which sentence correctly uses quotation marks for speech?', '["\"I am ready,\" said Maya","''I am ready,'' said Maya.\"","\"I am ready,\" said Maya.","I am ready, said Maya."]'::jsonb, 2, 'Quotation marks surround the exact words spoken, with punctuation inside the closing mark.', 'AC9E5LA09', null, null, true, null, null, null, null),
('1d3c4617-39fd-4fb7-8f70-b8327c5e6f1a', 'grammar_punctuation', 'grade_6', 'proficient', 'multiple_choice', 'Which sentence has correct subject-verb agreement?', '["The class have a test today.","The class has a test today.","The class having a test today.","The class have has a test today."]'::jsonb, 1, '''Class'' is a collective noun treated as singular in Australian English, so it takes ''has''.', 'AC9E6LA07', null, null, true, null, null, null, null),
('ed971577-6cda-4791-a618-1e206bd5d838', 'grammar_punctuation', 'grade_6', 'developing', 'multiple_choice', 'Which sentence uses the correct pronoun?', '["She gave the book to him and me.","She gave the book to him and I.","She gave the book to he and I.","She gave the book to him and myself."]'::jsonb, 0, '''Me'' is the correct object pronoun after a preposition like ''to'', not ''I''.', 'AC9E6LA08', null, null, true, null, null, null, null),
('415dc692-53e4-4e69-aeb7-7c0d6b71e90e', 'grammar_punctuation', 'year_7', 'developing', 'multiple_choice', 'Which word correctly completes: ''Each of the students ___ a locker.''', '["have","has","were","are"]'::jsonb, 1, '''Each'' is singular, so it takes the singular verb ''has'', even though ''students'' is plural.', 'AC9E7LA05', null, null, true, null, null, null, null),
('0980a6fc-b23f-4807-bbf0-a1c5f37b0323', 'grammar_punctuation', 'year_7', 'developing', 'multiple_choice', 'Which sentence avoids a comma splice?', '["I was tired I went to bed.","I was tired, and, I went to bed.","I was tired, so I went to bed.","I was tired, I went to bed."]'::jsonb, 2, 'A comma splice joins two independent clauses with only a comma; adding a conjunction like "so" fixes it.', 'AC9E7LA06', null, null, true, null, null, null, null),
('419ca4df-a461-4094-adb2-160c1ca07d86', 'grammar_punctuation', 'year_8', 'proficient', 'multiple_choice', 'Which sentence correctly uses a dash for emphasis?', '["The plan was perfect, until it wasn''t.","The plan was perfect until it wasn''t—","The plan was perfect—until it wasn''t.","The plan was perfect; until, it wasn''t."]'::jsonb, 2, 'A dash can be used to create a dramatic pause before an unexpected turn, placed directly between the two clauses.', 'AC9E8LA06', null, null, true, null, null, null, null),
('9f5794dc-cd81-46ca-966b-15ccf4b957d8', 'grammar_punctuation', 'year_8', 'developing', 'multiple_choice', 'Which sentence correctly uses "affect" or "effect"?', '["The weather will affect our plans.","The weather will effect our plans.","The weather will have an affect on our plans.","The weather will affects our plans."]'::jsonb, 0, '''Affect'' is usually a verb meaning to influence; ''effect'' is usually a noun meaning a result.', 'AC9E8LA07', null, null, true, null, null, null, null),
('eeaad202-185f-466d-9105-44350a102553', 'grammar_punctuation', 'year_9', 'proficient', 'multiple_choice', 'Which sentence correctly uses "which" to add extra, non-essential information?', '["The book which I borrowed last week is overdue.","The book, that I borrowed last week, is overdue.","The book who I borrowed last week is overdue.","The book, which I borrowed last week, is overdue."]'::jsonb, 3, '''Which'' introduces non-essential information and is set off with commas; ''that'' introduces essential information without commas.', 'AC9E9LA06', null, null, true, null, null, null, null),
('d441055b-36ae-46d3-bcf8-9f1339d19840', 'grammar_punctuation', 'year_9', 'proficient', 'multiple_choice', 'Identify the sentence written in the passive voice.', '["The storm is breaking the window.","The storm will break the window.","The window was broken by the storm.","The storm broke the window."]'::jsonb, 2, 'In the passive voice, the subject receives the action instead of performing it: "the window was broken" rather than "the storm broke".', 'AC9E9LA07', null, null, true, null, null, null, null),
('1a2b8b90-23cb-4a4c-ba56-e1f69eb5bf8b', 'grammar_punctuation', 'year_10', 'proficient', 'multiple_choice', 'Which sentence correctly uses the conditional tense?', '["If it would rain, I stay home.","If it rained, I would stay home.","If it rains, I would stay home.","If it rained, I will stay home."]'::jsonb, 1, 'A hypothetical condition in the past tense ("if it rained") pairs with "would" in the result clause.', 'AC9E10LA06', null, null, true, null, null, null, null),
('bdee6a98-b2c7-49e4-bca6-5437992f5bd8', 'grammar_punctuation', 'year_10', 'proficient', 'multiple_choice', 'Which sentence correctly uses "fewer" rather than "less"?', '["There are fewer students in this class.","There is less students in this class.","There are less students in this class.","There are fewer student in this class."]'::jsonb, 0, '''Fewer'' is used for countable nouns like ''students''; ''less'' is used for uncountable quantities.', 'AC9E10LA07', null, null, true, null, null, null, null),
('cb264ff5-f2a1-43f3-b425-4dd2a0e38312', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which sentence is a complete sentence?', '["Barked loudly.","The dog.","Loudly barked.","The dog barked loudly."]'::jsonb, 3, 'A complete sentence needs both a subject (the dog) and a verb (barked).', 'AC9E3LA05', null, null, true, null, null, null, null),
('b5bf7939-662f-4e8f-b1f5-1bc9c46f887c', 'grammar_punctuation', 'grade_3', 'developing', 'multiple_choice', 'Which word is spelled correctly?', '["becouse","beacause","because","becuase"]'::jsonb, 2, '''Because'' is spelled b-e-c-a-u-s-e.', 'AC9E3LA07', null, null, true, null, null, null, null),
('37c278a6-c23c-4a4e-bff0-b5dcb0e081a6', 'grammar_punctuation', 'grade_4', 'developing', 'multiple_choice', 'Which sentence uses the correct plural?', '["The child played outside.","The children played outside.","The childs played outside.","The childrens played outside."]'::jsonb, 1, '''Children'' is the irregular plural of ''child''.', 'AC9E4LA06', null, null, true, null, null, null, null),
('82e123eb-29fc-4f08-a911-81dedb6de651', 'grammar_punctuation', 'grade_4', 'developing', 'multiple_choice', 'Which sentence correctly uses "a" or "an"?', '["She ate an apple.","She ate a apple.","She ate an banana.","She ate a orange."]'::jsonb, 0, '''An'' is used before words that start with a vowel sound, like ''apple''.', 'AC9E4LA06', null, null, true, null, null, null, null),
('994b6be4-e9dd-463c-ab01-911049316286', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which sentence uses the correct verb tense?', '["Yesterday, we walk to school.","Yesterday, we walking to school.","Yesterday, we will walk to school.","Yesterday, we walked to school."]'::jsonb, 3, '''Walked'' is the past tense, matching the word ''yesterday''.', 'AC9E5LA08', null, null, true, null, null, null, null),
('ab8b2ecc-38b1-4095-ac73-3147016fc59c', 'grammar_punctuation', 'grade_5', 'proficient', 'multiple_choice', 'Which sentence correctly uses an adverb?', '["She ran quickness to the bus.","She ran quicker to the bus fastly.","She ran quickly to the bus.","She ran quick to the bus."]'::jsonb, 2, '''Quickly'' is an adverb describing how she ran; adverbs often end in ''-ly''.', 'AC9E5LA09', null, null, true, null, null, null, null),
('63a99f0d-ce9c-4eb4-8b13-3bbdfd925ca4', 'grammar_punctuation', 'grade_6', 'developing', 'multiple_choice', 'Which sentence uses an apostrophe correctly to show possession?', '["The dog''s'' bone was buried in the yard.","The dog''s bone was buried in the yard.","The dogs'' bone was buried in the yard.","The dogs bone was buried in the yard."]'::jsonb, 1, 'For a single dog, the apostrophe goes before the s: dog''s.', 'AC9E6LA07', null, null, true, null, null, null, null),
('ca820a5b-2273-4657-9717-dc224d70719e', 'grammar_punctuation', 'grade_6', 'proficient', 'multiple_choice', 'Which sentence is written in the active voice?', '["The cat chased the mouse.","The mouse was chased by the cat.","The mouse is being chased.","The mouse had been chased."]'::jsonb, 0, 'In the active voice, the subject (the cat) performs the action directly.', 'AC9E6LA08', null, null, true, null, null, null, null),
('31bb0035-32e4-4cfa-91d2-261eeb8a89c2', 'grammar_punctuation', 'year_7', 'proficient', 'multiple_choice', 'Which sentence uses "who" correctly?', '["The woman whom called is my aunt.","The woman which called is my aunt.","The woman who called was my aunt yesterday still calling.","The woman who called is my aunt."]'::jsonb, 3, '''Who'' refers to the subject performing the action (called); ''whom'' refers to an object.', 'AC9E7LA05', null, null, true, null, null, null, null),
('b46b99a1-a469-45c4-b4da-bb8b35203cfd', 'grammar_punctuation', 'year_7', 'developing', 'multiple_choice', 'Which sentence shows correct parallel structure?', '["She likes to hike, swimming, and biking.","She likes hiking, to swim, and biking.","She likes hiking, swimming, and biking.","She likes hiking, swimming, and to bike."]'::jsonb, 2, 'Parallel structure keeps items in a list in the same grammatical form; all three should end in "-ing".', 'AC9E7LA06', null, null, true, null, null, null, null),
('c2565fdf-21b6-4047-870a-d1d5db76d492', 'grammar_punctuation', 'year_8', 'developing', 'multiple_choice', 'Which sentence avoids a dangling modifier?', '["Walking to school, the rainbow was seen by Ben.","Walking to school, Ben saw a rainbow.","Walking to school, a rainbow appeared to Ben.","A rainbow was walking to school, Ben saw."]'::jsonb, 1, 'The modifier "walking to school" should describe the person doing the walking, which is Ben.', 'AC9E8LA06', null, null, true, null, null, null, null),
('dba9784f-21e1-464c-ab61-976912fb6d00', 'grammar_punctuation', 'year_8', 'proficient', 'multiple_choice', 'Which sentence correctly uses a colon?', '["She packed three things: a map, a torch, and water.","She packed: three things, a map, a torch, and water.","She packed three things, a map, a torch, and water:","She packed three things a map: a torch, and water."]'::jsonb, 0, 'A colon introduces a list after a complete independent clause.', 'AC9E8LA07', null, null, true, null, null, null, null),
('04b86f71-cfed-40b6-9529-1116068da867', 'grammar_punctuation', 'year_9', 'proficient', 'multiple_choice', 'Identify the subordinate clause in this sentence: "Although it was raining, we went outside."', '["We went outside","It was raining outside","Although we went outside","Although it was raining"]'::jsonb, 3, 'A subordinate clause cannot stand alone; "although it was raining" depends on the main clause "we went outside".', 'AC9E9LA06', null, null, true, null, null, null, null),
('2eb29ebd-6a5a-4b1b-aefb-da04ca178d09', 'grammar_punctuation', 'year_9', 'developing', 'multiple_choice', 'Which sentence correctly uses "that" for essential information, without commas?', '["The book, which I borrowed is overdue.","The book that, I borrowed, is overdue.","The book that I borrowed is overdue.","The book, that I borrowed, is overdue."]'::jsonb, 2, '''That'' introduces essential information and is not set off by commas.', 'AC9E9LA07', null, null, true, null, null, null, null),
('52ec8f3e-bc8a-460b-a4be-6681e3f8604c', 'grammar_punctuation', 'year_10', 'advanced', 'multiple_choice', 'Which sentence uses parallel structure correctly?', '["Not only finishing the race, but she also broke the record.","Not only did she finish the race, but she also broke the record.","Not only she finished the race, but also breaking the record.","Not only did she finish the race, but also she broke the record differently."]'::jsonb, 1, 'Parallel structure requires matching grammatical forms after "not only" and "but also".', 'AC9E10LA06', null, null, true, null, null, null, null),
('ed01bd6d-9738-4f02-9096-481cac56cbd2', 'grammar_punctuation', 'year_10', 'proficient', 'multiple_choice', 'Which sentence is a complete sentence rather than a fragment?', '["Because the storm was approaching, the ship returned to port.","Because the storm was approaching.","The ship, because the storm was approaching.","Returning to port because of the storm."]'::jsonb, 0, 'A sentence fragment is missing an independent clause; only the first option has both a subordinate and a main clause.', 'AC9E10LA07', null, null, true, null, null, null, null),
('71447fea-2b90-447a-9c4a-4398dc460a93', 'vocabulary', 'grade_3', 'foundation', 'multiple_choice', 'Which word means the same as ''small''?', '["Tiny","Wide","Tall","Heavy"]'::jsonb, 0, '''Tiny'' is a synonym for ''small''; both carry a similar meaning.', 'AC9E3LA09', null, null, true, null, null, null, null),
('761ad35c-48aa-4aa5-84b3-dfc4d85f3fa3', 'vocabulary', 'grade_3', 'foundation', 'multiple_choice', 'Which word means the same as ''big''?', '["Narrow","Short","Large","Tiny"]'::jsonb, 2, '''Large'' is a synonym for ''big''; both carry a similar meaning.', 'AC9E3LA09', null, null, true, null, null, null, null),
