('540f251a-a7fb-4da4-972a-1a23a376e6a3', 'life_science', 'grade_4', 'developing', 'multiple_choice', 'An animal''s natural home and surroundings are called its:', '["Species","Predator","Diet","Habitat"]'::jsonb, 3, 'A habitat is the natural environment where an animal lives and finds what it needs to survive.', 'AC9S4U02', null, null, true, null, null, null, null),
('0e5d077c-9a7b-4428-8cad-0cad99342c9e', 'life_science', 'grade_4', 'developing', 'multiple_choice', 'Animals with a backbone are called:', '["Mammals","Amphibians","Vertebrates","Invertebrates"]'::jsonb, 2, 'Vertebrates are animals that have a backbone, such as fish, birds, and mammals.', 'AC9S4U02', null, null, true, null, null, null, null),
('be4a6bdf-c30b-4c64-899f-1b932858ef2b', 'life_science', 'grade_5', 'developing', 'multiple_choice', 'What is the process called when pollen moves from one flower to another, helping plants reproduce?', '["Respiration","Pollination","Germination","Photosynthesis"]'::jsonb, 1, 'Pollination is the transfer of pollen between flowers, which allows plants to produce seeds.', 'AC9S5U01', null, null, true, null, null, null, null),
('7de1f0b5-e8b1-4eaa-abc1-3caa76f5045a', 'life_science', 'grade_5', 'developing', 'multiple_choice', 'In a food chain, what do we call an animal that eats other animals?', '["Consumer","Producer","Decomposer","Photosynthesiser"]'::jsonb, 0, 'Consumers are organisms that eat other organisms to get energy, unlike producers, which make their own food.', 'AC9S5U01', null, null, true, null, null, null, null),
('64e3c69b-3f63-4b40-bebd-34488fe25a0d', 'life_science', 'grade_5', 'proficient', 'multiple_choice', 'What role do decomposers play in an ecosystem?', '["They produce their own food from sunlight","They hunt other animals for food","They only live in water","They break down dead plants and animals"]'::jsonb, 3, 'Decomposers, like fungi and bacteria, break down dead organisms and recycle nutrients back into the ecosystem.', 'AC9S5U01', null, null, true, null, null, null, null),
('90416ab9-5e63-4b2b-bc46-d71d4dd1f2a8', 'life_science', 'grade_6', 'developing', 'multiple_choice', 'What is the basic unit of life that makes up all living things?', '["Organ","Atom","Cell","Tissue"]'::jsonb, 2, 'The cell is the smallest basic unit of structure and function in all living organisms.', 'AC9S6U02', null, null, true, null, null, null, null),
('7a236cce-9535-4a4a-b389-30a5cc64d202', 'life_science', 'grade_6', 'developing', 'multiple_choice', 'Which human body system is mainly responsible for breaking down food?', '["Skeletal system","Digestive system","Respiratory system","Circulatory system"]'::jsonb, 1, 'The digestive system breaks down food into nutrients the body can absorb and use.', 'AC9S6U02', null, null, true, null, null, null, null),
('a0de0071-bbbf-4d98-8efa-460543a417c6', 'life_science', 'grade_6', 'proficient', 'multiple_choice', 'A feature that helps an organism survive in its environment is called an:', '["Adaptation","Extinction","Habitat","Ecosystem"]'::jsonb, 0, 'An adaptation is a trait that helps an organism survive and reproduce in its specific environment.', 'AC9S6U02', null, null, true, null, null, null, null),
('16eb5ce5-48a4-4390-86f8-bc10d75191e3', 'life_science', 'year_7', 'developing', 'multiple_choice', 'What are the two main products of photosynthesis?', '["Carbon dioxide and water","Nitrogen and glucose","Water and oxygen only","Glucose and oxygen"]'::jsonb, 3, 'Photosynthesis converts carbon dioxide and water into glucose (food) and oxygen, using light energy.', 'AC9S7U03', null, null, true, null, null, null, null),
('3ae05ecd-749d-41a9-9d1b-91ab3ccb7a98', 'life_science', 'year_7', 'developing', 'multiple_choice', 'Which of these is an example of an invertebrate?', '["Eagle","Shark","Jellyfish","Dog"]'::jsonb, 2, 'A jellyfish has no backbone, making it an invertebrate, unlike dogs, eagles, and sharks.', 'AC9S7U03', null, null, true, null, null, null, null),
('660d6e9a-b0b7-4f13-8008-d45b4e2804ff', 'life_science', 'year_7', 'proficient', 'multiple_choice', 'What is the main function of red blood cells?', '["Send nerve signals","Carry oxygen around the body","Fight infection","Digest food"]'::jsonb, 1, 'Red blood cells contain haemoglobin, which binds to oxygen and carries it through the bloodstream.', 'AC9S7U03', null, null, true, null, null, null, null),
('97164156-018a-44bc-9612-73d79a81d9c3', 'life_science', 'year_8', 'developing', 'multiple_choice', 'Which part of a cell contains its genetic material?', '["Nucleus","Cytoplasm","Cell membrane","Cell wall"]'::jsonb, 0, 'The nucleus contains DNA, which holds the genetic instructions for the cell.', 'AC9S8U02', null, null, true, null, null, null, null),
('790854c3-25d6-46d7-8173-d0cdb85b11e0', 'life_science', 'year_8', 'developing', 'multiple_choice', 'A trait passed from parent to offspring, such as eye colour, is called:', '["A learned behaviour","A mutation only","An adaptation only","An inherited trait"]'::jsonb, 3, 'Inherited traits are passed genetically from parents to their offspring.', 'AC9S8U02', null, null, true, null, null, null, null),
('a53d1c70-b7d9-41e1-884c-ee93e78a9abc', 'life_science', 'year_8', 'proficient', 'multiple_choice', 'What are microorganisms too small to see without a microscope, such as bacteria, generally called?', '["Cells only","Tissues","Microbes","Fungi only"]'::jsonb, 2, 'Microbes (or microorganisms) are tiny living things, including bacteria and some fungi and viruses.', 'AC9S8U02', null, null, true, null, null, null, null),
('86b39d8e-f376-4bfa-b591-957f45768cc6', 'life_science', 'year_9', 'developing', 'multiple_choice', 'What is the molecule that carries genetic information in living cells?', '["Glucose","DNA","RNA only","Protein"]'::jsonb, 1, 'DNA (deoxyribonucleic acid) carries the genetic instructions used in the growth and functioning of living organisms.', 'AC9S9U03', null, null, true, null, null, null, null),
('77def386-4f12-4f80-a33c-a06bf88d196c', 'life_science', 'year_9', 'proficient', 'multiple_choice', 'The process by which organisms best suited to their environment are more likely to survive and reproduce is called:', '["Natural selection","Photosynthesis","Fermentation","Pollination"]'::jsonb, 0, 'Natural selection is the process where organisms with favourable traits are more likely to survive and pass those traits on.', 'AC9S9U03', null, null, true, null, null, null, null),
('b0f3fe36-1292-48a9-a45c-96d253ac6692', 'life_science', 'year_9', 'proficient', 'multiple_choice', 'In an ecosystem, energy generally flows in which direction through a food chain?', '["From consumers to producers","Equally in both directions","It does not flow, only matter does","From producers to consumers"]'::jsonb, 3, 'Energy flows from producers (which capture energy from sunlight) up through the levels of consumers in a food chain.', 'AC9S9U03', null, null, true, null, null, null, null),
('4080e668-6840-4eb2-a059-eece6007a29b', 'life_science', 'year_10', 'developing', 'multiple_choice', 'The process by which the body maintains a stable internal environment is called:', '["Respiration","Digestion","Homeostasis","Metabolism"]'::jsonb, 2, 'Homeostasis is the regulation of internal conditions, such as temperature, to keep the body stable.', 'AC9S10U01', null, null, true, null, null, null, null),
('092c450c-1e6d-46fb-ab36-eb483275c87c', 'life_science', 'year_10', 'proficient', 'multiple_choice', 'Which scientist is most associated with the theory of evolution by natural selection?', '["Louis Pasteur","Charles Darwin","Gregor Mendel","Isaac Newton"]'::jsonb, 1, 'Charles Darwin proposed the theory of evolution by natural selection in his book "On the Origin of Species".', 'AC9S10U01', null, null, true, null, null, null, null),
('da82552d-59a3-4e77-ac3a-5eef92ac4957', 'life_science', 'year_10', 'proficient', 'multiple_choice', 'Using living organisms or their processes to develop products, such as genetically modified crops, is called:', '["Biotechnology","Astronomy","Meteorology","Geology"]'::jsonb, 0, 'Biotechnology applies biological processes and organisms to develop products and technologies.', 'AC9S10U01', null, null, true, null, null, null, null),
('27876fbb-4ec2-4cfa-8a50-2c410ab85990', 'life_science', 'grade_3', 'developing', 'multiple_choice', 'Which of these describes something that is NOT alive?', '["It grows over time","It needs food and water","It can reproduce","It does not grow, move on its own, or need food"]'::jsonb, 3, 'Living things grow, need food and water, and can reproduce; non-living things do none of these.', 'AC9S3U01', null, null, true, null, null, null, null),
('b4b3215c-864e-4ca0-80fa-960d40c14d9a', 'life_science', 'grade_3', 'foundation', 'multiple_choice', 'Which sense do you use to hear a bird singing?', '["Taste","Smell","Hearing","Sight"]'::jsonb, 2, 'Hearing is the sense used to detect sounds, like a bird singing.', 'AC9S3U01', null, null, true, null, null, null, null),
('840c6518-618a-47c8-a664-616eec72f143', 'life_science', 'grade_4', 'developing', 'multiple_choice', 'Which of these is a carnivore, an animal that only eats meat?', '["Horse","Lion","Cow","Rabbit"]'::jsonb, 1, 'A lion hunts and eats other animals, making it a carnivore.', 'AC9S4U02', null, null, true, null, null, null, null),
('78e23eeb-1e19-4212-bc80-16768376b4a4', 'life_science', 'grade_4', 'developing', 'multiple_choice', 'What do bees help plants do when they move between flowers?', '["Pollinate","Photosynthesise","Hibernate","Decompose"]'::jsonb, 0, 'Bees carry pollen between flowers as they feed, helping plants pollinate and produce seeds.', 'AC9S4U02', null, null, true, null, null, null, null),
('b6f5d759-6eb3-4606-abca-1789ebdae9ad', 'life_science', 'grade_4', 'foundation', 'multiple_choice', 'Which body part pumps blood in humans and most animals?', '["Lungs","Stomach","Brain","Heart"]'::jsonb, 3, 'The heart is a muscular organ that pumps blood around the body.', 'AC9S4U02', null, null, true, null, null, null, null),
('a5343ce2-8552-4f7c-a18d-c23ae9b7ea37', 'life_science', 'grade_5', 'developing', 'multiple_choice', 'What gas do plants absorb from the air during photosynthesis?', '["Nitrogen","Hydrogen","Carbon dioxide","Oxygen"]'::jsonb, 2, 'Plants absorb carbon dioxide from the air and use it, along with water and sunlight, to make food.', 'AC9S5U01', null, null, true, null, null, null, null),
('a89f3d69-adcf-4940-b7b1-cc5740f22a28', 'life_science', 'grade_5', 'developing', 'multiple_choice', 'Which of these is an example of a producer in a food chain?', '["Wolf","Grass","Lion","Eagle"]'::jsonb, 1, 'Producers, like grass, make their own food from sunlight and are the base of most food chains.', 'AC9S5U01', null, null, true, null, null, null, null),
('38b6fda1-f9c8-4194-9364-bae79e78ad7f', 'life_science', 'grade_6', 'developing', 'multiple_choice', 'Which organ in the human body is mainly responsible for filtering waste from the blood?', '["Kidneys","Liver","Lungs","Stomach"]'::jsonb, 0, 'The kidneys filter waste products and excess water from the blood to form urine.', 'AC9S6U02', null, null, true, null, null, null, null),
('26a9c14b-0ae3-4a8c-a4d6-4a36132fb90a', 'life_science', 'grade_6', 'proficient', 'multiple_choice', 'What is a group of the same species living in the same area called?', '["A community","An ecosystem","A habitat","A population"]'::jsonb, 3, 'A population refers to all the members of one species living in a particular area.', 'AC9S6U02', null, null, true, null, null, null, null),
('720f28c0-6494-4525-9af7-168e35ced411', 'life_science', 'year_7', 'developing', 'multiple_choice', 'Which organelle in a plant cell is responsible for photosynthesis?', '["Mitochondria","Vacuole","Chloroplast","Nucleus"]'::jsonb, 2, 'Chloroplasts contain chlorophyll and are the site of photosynthesis in plant cells.', 'AC9S7U03', null, null, true, null, null, null, null),
('5921421d-f0a2-43b9-8d4d-bc8642d1edff', 'life_science', 'year_7', 'proficient', 'multiple_choice', 'Which of these best describes the role of white blood cells in the body?', '["Sending nerve signals","Fighting infection","Carrying oxygen","Digesting food"]'::jsonb, 1, 'White blood cells are part of the immune system and help the body fight off infections.', 'AC9S7U03', null, null, true, null, null, null, null),
('347ef2ad-fb11-4182-8ab3-44512490561e', 'life_science', 'year_8', 'developing', 'multiple_choice', 'Which structure controls what enters and leaves a cell?', '["Cell membrane","Nucleus","Cell wall","Cytoplasm"]'::jsonb, 0, 'The cell membrane is a selective barrier that controls the movement of substances into and out of the cell.', 'AC9S8U02', null, null, true, null, null, null, null),
('ab645c82-6fb3-441a-a747-df06d2113dba', 'life_science', 'year_8', 'proficient', 'multiple_choice', 'A characteristic that appears due to a change in an organism''s DNA is called a:', '["Habitat","Adaptation only","Ecosystem","Mutation"]'::jsonb, 3, 'A mutation is a change in an organism''s DNA, which can sometimes lead to new traits.', 'AC9S8U02', null, null, true, null, null, null, null),
('c2b4f143-93a0-4dcd-9001-3f5a2a3e8f9a', 'life_science', 'year_9', 'developing', 'multiple_choice', 'Which process do plants and animals both use to release energy from food?', '["Pollination","Excretion","Respiration","Photosynthesis"]'::jsonb, 2, 'Respiration is the process of breaking down food to release energy, which occurs in both plants and animals.', 'AC9S9U03', null, null, true, null, null, null, null),
('06148d85-95f5-46c1-8bcc-bf0a878a9346', 'life_science', 'year_9', 'proficient', 'multiple_choice', 'A community of living organisms interacting with their non-living environment is called a:', '["A habitat only","An ecosystem","A population","A species"]'::jsonb, 1, 'An ecosystem includes all living organisms in an area, along with the non-living parts of their environment, like water and soil.', 'AC9S9U03', null, null, true, null, null, null, null),
('6f519d8e-2989-447a-a806-94cb2189dac8', 'life_science', 'year_10', 'developing', 'multiple_choice', 'What is the term for an organism''s complete set of genetic material?', '["Genome","Genotype only","Phenotype","Chromosome"]'::jsonb, 0, 'The genome is the complete set of genetic material, or DNA, found in an organism.', 'AC9S10U01', null, null, true, null, null, null, null),
('69e15a87-caf3-4abf-b42c-79428dda33ed', 'life_science', 'year_10', 'proficient', 'multiple_choice', 'Selective breeding is best described as:', '["Random mating between any organisms","Genetically modifying DNA directly","Cloning an organism exactly","Choosing organisms with desired traits to breed together"]'::jsonb, 3, 'Selective breeding involves choosing parent organisms with desirable traits, over generations, to produce offspring with those traits.', 'AC9S10U01', null, null, true, null, null, null, null),
('d2188057-80d6-4a36-b71d-c14a8cb34619', 'physical_science', 'grade_3', 'foundation', 'multiple_choice', 'Which of these is a solid?', '["Air","Steam","A rock","Water"]'::jsonb, 2, 'A rock keeps its own shape and does not flow, which makes it a solid.', 'AC9S3U03', null, null, true, null, null, null, null),
('a3c33f6b-62a0-4c9a-b60a-142f65f87ad9', 'physical_science', 'grade_3', 'developing', 'multiple_choice', 'What happens when two magnets have opposite poles facing each other?', '["They both become non-magnetic","They attract (pull together)","They repel (push apart)","Nothing happens"]'::jsonb, 1, 'Opposite magnetic poles (north and south) attract each other, while like poles repel.', 'AC9S3U03', null, null, true, null, null, null, null),
('2a257334-197b-4b2f-9c94-dcc95344a84c', 'physical_science', 'grade_3', 'developing', 'multiple_choice', 'A push or a pull on an object is called a:', '["Force","Mass","Energy source","Material"]'::jsonb, 0, 'A force is a push or a pull that can change an object''s motion or shape.', 'AC9S3U03', null, null, true, null, null, null, null),
('e1537fee-6551-4a53-8b51-48b3c07db65b', 'physical_science', 'grade_4', 'developing', 'multiple_choice', 'What is needed for sound to travel from one place to another?', '["Complete silence","Darkness","A magnet","A medium, such as air or water, to vibrate through"]'::jsonb, 3, 'Sound travels as vibrations through a medium like air, water, or solids; it cannot travel through a vacuum.', 'AC9S4U01', null, null, true, null, null, null, null),
('516f74df-0e2c-4a3d-a2f7-491482a76075', 'physical_science', 'grade_4', 'developing', 'multiple_choice', 'What causes a shadow to form?', '["An object being heavy","An object being magnetic","An object blocking light","An object making sound"]'::jsonb, 2, 'A shadow forms when an object blocks light from reaching a surface behind it.', 'AC9S4U01', null, null, true, null, null, null, null),
('f285d11d-fdea-4178-b623-162113760bc9', 'physical_science', 'grade_5', 'developing', 'multiple_choice', 'A simple machine that uses a rope over a wheel to lift objects is called a:', '["Screw","Pulley","Lever","Wedge"]'::jsonb, 1, 'A pulley uses a wheel and rope to change the direction of a force, making it easier to lift objects.', 'AC9S5U03', null, null, true, null, null, null, null),
('aafd55a4-fb09-4404-a213-541d1ce1d360', 'physical_science', 'grade_5', 'developing', 'multiple_choice', 'Heat moving through a solid material, such as a metal spoon in hot soup, is called:', '["Conduction","Convection","Radiation","Evaporation"]'::jsonb, 0, 'Conduction is the transfer of heat through direct contact within a solid material.', 'AC9S5U03', null, null, true, null, null, null, null),
('81b17d0e-ebba-49bb-86a9-59d06f8cb4aa', 'physical_science', 'grade_5', 'proficient', 'multiple_choice', 'What is needed to make a simple electric circuit work?', '["A magnet only","Sunlight only","A gap in the wire","A closed, unbroken loop for current to flow"]'::jsonb, 3, 'An electric circuit needs a complete, unbroken loop for electric current to flow through it.', 'AC9S5U03', null, null, true, null, null, null, null),
('4af16baf-7024-4f17-8028-f6d77f8d5e43', 'physical_science', 'grade_6', 'developing', 'multiple_choice', 'Which of these is a form of energy stored due to an object''s position, such as a ball held high?', '["Sound energy","Chemical energy","Potential energy","Kinetic energy"]'::jsonb, 2, 'Potential energy is stored energy based on an object''s position, such as height above the ground.', 'AC9S6U01', null, null, true, null, null, null, null),
('43265bbe-19e9-4c0a-aa8e-48ad4b778295', 'physical_science', 'grade_6', 'developing', 'multiple_choice', 'What is the energy of movement called?', '["Nuclear energy","Kinetic energy","Potential energy","Thermal energy"]'::jsonb, 1, 'Kinetic energy is the energy an object has because it is moving.', 'AC9S6U01', null, null, true, null, null, null, null),
('a66279c6-c848-40e0-abc5-ed8825b64a38', 'physical_science', 'grade_6', 'proficient', 'multiple_choice', 'A higher-pitched sound generally has a:', '["Higher frequency","Lower frequency","Louder volume","Longer wavelength only"]'::jsonb, 0, 'Pitch is related to frequency: higher frequency vibrations produce higher-pitched sounds.', 'AC9S6U01', null, null, true, null, null, null, null),
('43a9e33d-9bc6-4225-9f0a-e53f2d98f407', 'physical_science', 'year_7', 'developing', 'multiple_choice', 'When water changes from a liquid to a gas, this process is called:', '["Condensation","Freezing","Melting","Evaporation"]'::jsonb, 3, 'Evaporation is the change of state from liquid to gas, usually caused by heating.', 'AC9S7U01', null, null, true, null, null, null, null),
('34548b0f-1ceb-46d0-af4a-d7be95b21631', 'physical_science', 'year_7', 'developing', 'multiple_choice', 'Density is best described as:', '["Volume of an object only","Temperature of a substance","Mass per unit of volume","Weight of an object only"]'::jsonb, 2, 'Density measures how much mass is packed into a given volume of a substance.', 'AC9S7U01', null, null, true, null, null, null, null),
('37d5ba84-b1b0-49de-b88e-3c6483a406b2', 'physical_science', 'year_7', 'proficient', 'multiple_choice', 'In a series circuit, if one globe burns out, what happens to the rest of the circuit?', '["Nothing changes","All the globes turn off","Only that globe turns off, the rest stay on","The circuit gets brighter"]'::jsonb, 1, 'In a series circuit there is only one path for current, so a break anywhere stops current everywhere in the loop.', 'AC9S7U01', null, null, true, null, null, null, null),
('909dd0e9-4828-487e-a54b-8ec7a5d54dc1', 'physical_science', 'year_8', 'developing', 'multiple_choice', 'According to Newton''s first law, an object at rest will stay at rest unless:', '["Acted on by an unbalanced force","It is very heavy","It is made of metal","It is left alone for a long time"]'::jsonb, 0, 'Newton''s first law states that an object remains at rest, or in uniform motion, unless acted on by an unbalanced force.', 'AC9S8U01', null, null, true, null, null, null, null),
('dfbeb1bd-0e2c-402b-b1ce-861fd91e9b1b', 'physical_science', 'year_8', 'developing', 'multiple_choice', 'Sound waves and water waves are both examples of which type of wave, since they need a medium to travel through?', '["Electromagnetic waves","Light waves","Radio waves","Mechanical waves"]'::jsonb, 3, 'Mechanical waves, like sound and water waves, require a medium (such as air or water) to travel through.', 'AC9S8U01', null, null, true, null, null, null, null),
('5f48e025-4c14-42e8-89b5-aaed3be746ab', 'physical_science', 'year_8', 'proficient', 'multiple_choice', 'What is the process called when a substance changes state without a chemical reaction occurring, such as ice melting?', '["A nuclear reaction","Combustion","A physical change","A chemical change"]'::jsonb, 2, 'A physical change, like melting or freezing, alters a substance''s state without changing its chemical makeup.', 'AC9S8U01', null, null, true, null, null, null, null),
('a00cf390-03e0-4aac-b21d-710de91af173', 'physical_science', 'year_9', 'developing', 'multiple_choice', 'What is the formula for calculating average speed?', '["Distance + time","Distance ÷ time","Distance × time","Time ÷ distance"]'::jsonb, 1, 'Average speed is calculated as the distance travelled divided by the time taken.', 'AC9S9U01', null, null, true, null, null, null, null),
('8a7bb997-6650-4ac7-b1b4-22fe56eadaf7', 'physical_science', 'year_9', 'developing', 'multiple_choice', 'According to the law of conservation of energy, energy can:', '["Not be created or destroyed, only transformed","Be created but not destroyed","Be destroyed but not created","Only exist as heat"]'::jsonb, 0, 'The law of conservation of energy states that energy cannot be created or destroyed, only transformed from one form to another.', 'AC9S9U01', null, null, true, null, null, null, null),
('bf7ae28f-322b-459e-a179-dcda96748857', 'physical_science', 'year_9', 'proficient', 'multiple_choice', 'Rusting of iron is an example of a:', '["Physical change","Change of state","Nuclear change","Chemical change"]'::jsonb, 3, 'Rusting involves a chemical reaction between iron, oxygen, and water, forming a new substance (iron oxide).', 'AC9S9U01', null, null, true, null, null, null, null),
('a8fb4908-f37c-4d12-ab5b-19a39cc5a542', 'physical_science', 'year_10', 'developing', 'multiple_choice', 'What unit is used to measure electrical resistance?', '["Watt","Ampere","Ohm","Volt"]'::jsonb, 2, 'Electrical resistance is measured in ohms, symbol Ω.', 'AC9S10U03', null, null, true, null, null, null, null),
('38b503b8-fa93-4962-8eca-f38417780e67', 'physical_science', 'year_10', 'developing', 'multiple_choice', 'The number of wave crests passing a point each second is called the wave''s:', '["Speed","Frequency","Amplitude","Wavelength"]'::jsonb, 1, 'Frequency measures how many complete waves pass a point per second, measured in hertz (Hz).', 'AC9S10U03', null, null, true, null, null, null, null),
('6de0e8f2-1778-4048-b023-ea41fe126300', 'physical_science', 'year_10', 'proficient', 'multiple_choice', 'What is the relationship between voltage, current, and resistance, according to Ohm''s law?', '["Voltage = current × resistance","Voltage = current ÷ resistance","Voltage = current + resistance","Voltage = resistance ÷ current"]'::jsonb, 0, 'Ohm''s law states V = I × R, where V is voltage, I is current, and R is resistance.', 'AC9S10U03', null, null, true, null, null, null, null),
('edb4d129-3d00-4472-a241-56443bf94ba2', 'physical_science', 'grade_3', 'developing', 'multiple_choice', 'Which of these is a liquid?', '["A rock","Air","A block of wood","Milk"]'::jsonb, 3, 'Milk flows and takes the shape of its container, which makes it a liquid.', 'AC9S3U03', null, null, true, null, null, null, null),
('8c40cd49-1fe5-48f0-a28d-b4e5b19ac88f', 'physical_science', 'grade_3', 'foundation', 'multiple_choice', 'What is it called when an object is pulled toward the Earth?', '["Magnetism","Electricity","Gravity","Friction"]'::jsonb, 2, 'Gravity is the force that pulls objects toward the Earth.', 'AC9S3U03', null, null, true, null, null, null, null),
('959eb318-91f4-4a63-9915-ce32b628024f', 'physical_science', 'grade_4', 'developing', 'multiple_choice', 'Which of these materials is a good conductor of electricity?', '["Wood","Copper","Rubber","Plastic"]'::jsonb, 1, 'Copper is a metal, and metals are generally good conductors of electricity.', 'AC9S4U01', null, null, true, null, null, null, null),
('a2808b56-6156-42f2-91e0-3e83609ad71c', 'physical_science', 'grade_4', 'developing', 'multiple_choice', 'What happens to most materials when they are heated?', '["They expand","They always shrink","They become magnetic","They disappear"]'::jsonb, 0, 'Most materials expand slightly when heated, as their particles move faster and spread apart.', 'AC9S4U01', null, null, true, null, null, null, null),
('277455a3-4ac3-4b36-9818-1ebffbfaea19', 'physical_science', 'grade_5', 'developing', 'multiple_choice', 'Which simple machine is a ramp that makes it easier to move objects to a higher place?', '["Lever","Wheel and axle","Pulley","Inclined plane"]'::jsonb, 3, 'An inclined plane, or ramp, reduces the force needed to raise an object by spreading the work over a longer distance.', 'AC9S5U03', null, null, true, null, null, null, null),
('d4d288c0-6575-470b-9e0b-16f7ea04dcbb', 'physical_science', 'grade_5', 'proficient', 'multiple_choice', 'What is the transfer of heat through empty space, such as heat from the sun, called?', '["Convection","Insulation","Radiation","Conduction"]'::jsonb, 2, 'Radiation transfers heat as electromagnetic waves and can travel through empty space, unlike conduction or convection.', 'AC9S5U03', null, null, true, null, null, null, null),
('a9fe29a8-16cc-48d8-b572-54bac049c42d', 'physical_science', 'grade_6', 'developing', 'multiple_choice', 'Which of these is an example of stored chemical energy?', '["A stretched rubber band","A battery","A moving car","Sunlight"]'::jsonb, 1, 'A battery stores energy in chemical form, which is converted to electrical energy when used.', 'AC9S6U01', null, null, true, null, null, null, null),
('a41fe943-bd18-448b-96f8-673807a07814', 'physical_science', 'grade_6', 'developing', 'multiple_choice', 'What happens to the pitch of a sound as the frequency of vibration decreases?', '["The pitch gets lower","The pitch gets higher","The pitch stays the same","The sound becomes silent"]'::jsonb, 0, 'Lower frequency vibrations produce a lower-pitched sound.', 'AC9S6U01', null, null, true, null, null, null, null),
('3fcb0332-ed03-4968-a37c-15c313ebfda1', 'physical_science', 'year_7', 'developing', 'multiple_choice', 'Which state of matter has a definite shape and volume?', '["Liquid","Gas","Plasma","Solid"]'::jsonb, 3, 'A solid keeps both its shape and volume, unlike liquids and gases.', 'AC9S7U01', null, null, true, null, null, null, null),
('64403791-d6de-4978-bd47-6e5c4419b935', 'physical_science', 'year_7', 'proficient', 'multiple_choice', 'In a parallel circuit, if one globe burns out, what happens to the other globes?', '["They get dimmer and turn off","The circuit stops working entirely","They stay on","They all turn off"]'::jsonb, 2, 'In a parallel circuit, each globe has its own separate path, so the others keep working if one fails.', 'AC9S7U01', null, null, true, null, null, null, null),
('dbade988-155b-4c69-88ed-e54e37faf6ca', 'physical_science', 'year_8', 'developing', 'multiple_choice', 'Which of Newton''s laws states that for every action there is an equal and opposite reaction?', '["The law of gravity","The third law","The first law","The second law"]'::jsonb, 1, 'Newton''s third law states that every action force has an equal and opposite reaction force.', 'AC9S8U01', null, null, true, null, null, null, null),
('971fde25-bc5c-4406-92f1-864f18465d7b', 'physical_science', 'year_8', 'proficient', 'multiple_choice', 'What type of wave requires no medium and can travel through the vacuum of space?', '["Electromagnetic wave","Sound wave","Water wave","Seismic wave"]'::jsonb, 0, 'Electromagnetic waves, like light, can travel through the vacuum of space without needing a medium.', 'AC9S8U01', null, null, true, null, null, null, null),
('5522aa73-cdbe-4be7-91c0-68ef6b63b563', 'physical_science', 'year_9', 'developing', 'multiple_choice', 'Freezing water into ice is an example of a:', '["Chemical change","Nuclear change","Combustion reaction","Physical change"]'::jsonb, 3, 'Freezing changes water''s state without forming a new substance, making it a physical change.', 'AC9S9U01', null, null, true, null, null, null, null),
('8f9593bb-1192-4729-b332-2cde6ae433fb', 'physical_science', 'year_9', 'proficient', 'multiple_choice', 'If a car travels 150 km in 3 hours, what is its average speed?', '["50 m/s","3 km/h","50 km/h","450 km/h"]'::jsonb, 2, 'Average speed = distance ÷ time = 150 km ÷ 3 h = 50 km/h.', 'AC9S9U01', null, null, true, null, null, null, null),
('9f679146-255a-419f-a8b7-35a0ea856654', 'physical_science', 'year_10', 'developing', 'multiple_choice', 'What is the SI unit used to measure electric current?', '["Watt","Ampere","Volt","Ohm"]'::jsonb, 1, 'Electric current is measured in amperes (amps), symbol A.', 'AC9S10U03', null, null, true, null, null, null, null),
('1826d930-a611-4415-89da-1a8f78b3d561', 'physical_science', 'year_10', 'proficient', 'multiple_choice', 'A wave with a short wavelength has a:', '["High frequency","Low frequency","Low speed only","No energy"]'::jsonb, 0, 'Wavelength and frequency are inversely related for waves travelling at the same speed, so a short wavelength means a high frequency.', 'AC9S10U03', null, null, true, null, null, null, null),
('03431a77-0f9e-4291-9f77-fdeafb4055f9', 'earth_space', 'grade_3', 'developing', 'multiple_choice', 'What are the four seasons, in order, starting from summer?', '["Winter, spring, summer, autumn","Spring, summer, autumn, winter","Autumn, winter, spring, summer","Summer, autumn, winter, spring"]'::jsonb, 3, 'Starting from summer, the seasons follow the order: summer, autumn, winter, spring.', 'AC9S3U02', null, null, true, null, null, null, null),
('93b93e73-e0ea-42a4-95df-d42b43c227d2', 'earth_space', 'grade_3', 'foundation', 'multiple_choice', 'What is the difference between weather and climate?', '["Climate changes daily; weather does not","Weather only happens in winter","Weather is day-to-day conditions; climate is the pattern over many years","Weather and climate mean exactly the same thing"]'::jsonb, 2, 'Weather describes short-term daily conditions, while climate describes long-term average weather patterns in a region.', 'AC9S3U02', null, null, true, null, null, null, null),
('8787955e-c833-4dc6-9396-740220634954', 'earth_space', 'grade_4', 'developing', 'multiple_choice', 'Which type of rock is formed from layers of sediment pressed together over time?', '["Volcanic rock","Sedimentary rock","Igneous rock","Metamorphic rock"]'::jsonb, 1, 'Sedimentary rock forms when layers of sediment, like sand or mud, are compressed together over long periods.', 'AC9S4U03', null, null, true, null, null, null, null),
('c16e18dc-53e6-4149-9af7-2d4890fa4a80', 'earth_space', 'grade_4', 'developing', 'multiple_choice', 'What is the continuous movement of water between the sky, land, and oceans called?', '["The water cycle","The rock cycle","The carbon cycle","The food cycle"]'::jsonb, 0, 'The water cycle describes how water evaporates, condenses into clouds, and falls as precipitation, again and again.', 'AC9S4U03', null, null, true, null, null, null, null),
('673a1ef3-1191-4d49-a14d-59533db7a825', 'earth_space', 'grade_5', 'developing', 'multiple_choice', 'Which planet is known as the "Red Planet"?', '["Venus","Jupiter","Mercury","Mars"]'::jsonb, 3, 'Mars appears red due to iron oxide (rust) on its surface, earning it the nickname "the Red Planet".', 'AC9S5U02', null, null, true, null, null, null, null),
('4beff8bd-1407-45df-964c-3e21327980f2', 'earth_space', 'grade_5', 'developing', 'multiple_choice', 'Put these planets in order from closest to the Sun: Earth, Mercury, Venus.', '["Venus, Mercury, Earth","Mercury, Earth, Venus","Mercury, Venus, Earth","Earth, Venus, Mercury"]'::jsonb, 2, 'The order of the closest planets to the Sun is Mercury, then Venus, then Earth.', 'AC9S5U02', null, null, true, null, null, null, null),
('0d12466d-92ce-49d8-8b9f-0f5a8c689f10', 'earth_space', 'grade_6', 'developing', 'multiple_choice', 'The gradual wearing away of rock and soil by wind, water, or ice is called:', '["Combustion","Erosion","Evaporation","Condensation"]'::jsonb, 1, 'Erosion is the process by which wind, water, or ice gradually wear away and move rock and soil.', 'AC9S6U03', null, null, true, null, null, null, null),
('1ca087db-5e18-43fe-8712-99c191ccbfd3', 'earth_space', 'grade_6', 'developing', 'multiple_choice', 'Which of these is a renewable energy resource?', '["Solar power","Coal","Natural gas","Oil"]'::jsonb, 0, 'Solar power comes from the sun, a resource that naturally replenishes and will not run out, unlike fossil fuels.', 'AC9S6U03', null, null, true, null, null, null, null),
('793f6542-4f26-4ed5-adc6-df887b2fbcd1', 'earth_space', 'year_7', 'developing', 'multiple_choice', 'The continuous process by which rocks are formed, broken down, and reformed over millions of years is called the:', '["Water cycle","Carbon cycle","Nitrogen cycle","Rock cycle"]'::jsonb, 3, 'The rock cycle describes how igneous, sedimentary, and metamorphic rocks transform into one another over geological time.', 'AC9S7U02', null, null, true, null, null, null, null),
('cdb4a7f2-76d9-4eae-a60f-05c1eeebcaf3', 'earth_space', 'year_7', 'developing', 'multiple_choice', 'A fossil is most likely to form when an organism is:', '["Burned in a fire","Frozen only briefly","Buried quickly in sediment after death","Left exposed to air for a long time"]'::jsonb, 2, 'Fossils typically form when an organism is buried quickly in sediment, protecting it from decay while it mineralises over time.', 'AC9S7U02', null, null, true, null, null, null, null),
('7feb0878-7350-4c28-8663-5297fac0d6a2', 'earth_space', 'year_8', 'developing', 'multiple_choice', 'Volcanic eruptions and earthquakes most commonly occur along:', '["Areas with no rock layers","Tectonic plate boundaries","The centre of continents only","The equator only"]'::jsonb, 1, 'Most volcanic and earthquake activity occurs where tectonic plates meet, due to the movement and pressure at these boundaries.', 'AC9S8U02', null, null, true, null, null, null, null),
('6a9c251d-f7a0-4373-9a05-3dc6a5213439', 'earth_space', 'year_8', 'developing', 'multiple_choice', 'Which layer of the atmosphere is closest to Earth''s surface, where weather occurs?', '["Troposphere","Stratosphere","Mesosphere","Thermosphere"]'::jsonb, 0, 'The troposphere is the lowest layer of the atmosphere, where almost all weather takes place.', 'AC9S8U02', null, null, true, null, null, null, null),
('2e29ec3d-4463-4367-a993-cefb6ebddc1d', 'earth_space', 'year_9', 'developing', 'multiple_choice', 'The natural process by which gases trap heat in Earth''s atmosphere is called the:', '["Water cycle","Rock cycle","Carbon capture","Greenhouse effect"]'::jsonb, 3, 'The greenhouse effect occurs when gases like carbon dioxide trap heat from the sun in the atmosphere, warming the planet.', 'AC9S9U04', null, null, true, null, null, null, null),
('aed732ac-94ce-4597-ae8f-3bf5969da433', 'earth_space', 'year_9', 'proficient', 'multiple_choice', 'A resource that can be replenished naturally within a human lifetime, such as wind or timber, is called:', '["A fossil fuel","A mineral resource only","A renewable resource","A non-renewable resource"]'::jsonb, 2, 'Renewable resources, like wind and timber, can be naturally replenished within a relatively short time.', 'AC9S9U04', null, null, true, null, null, null, null),
('e311c7e4-79b4-4227-af8b-dce8925952dc', 'earth_space', 'year_10', 'developing', 'multiple_choice', 'The Earth is estimated to be approximately how old?', '["100 million years","4.5 billion years","4.5 million years","10,000 years"]'::jsonb, 1, 'Scientific evidence, including radiometric dating, estimates Earth''s age at approximately 4.5 billion years.', 'AC9S10U02', null, null, true, null, null, null, null),
('6b39fe15-ae4e-45ac-a8e4-69323992403b', 'earth_space', 'year_10', 'proficient', 'multiple_choice', 'A sudden, violent shaking of the ground caused by the movement of tectonic plates is called a:', '["Earthquake","Tsunami","Landslide","Volcano"]'::jsonb, 0, 'An earthquake is caused by the sudden release of energy as tectonic plates shift, causing the ground to shake.', 'AC9S10U02', null, null, true, null, null, null, null),
('81f0d130-14f5-44c4-8482-421d2be96cbf', 'earth_space', 'year_10', 'developing', 'multiple_choice', 'Which of these is considered a renewable source of electricity generation?', '["Coal-fired power stations","Natural gas plants","Oil-fired power stations","Wind turbines"]'::jsonb, 3, 'Wind turbines generate electricity from wind, a naturally replenishing resource, unlike fossil fuels.', 'AC9S10U02', null, null, true, null, null, null, null),
('e4097d3e-fb18-42f1-9b01-eff03e271b19', 'earth_space', 'grade_3', 'developing', 'multiple_choice', 'What causes the different phases of the Moon that we see from Earth?', '["Clouds covering the Moon","The Moon moving closer and farther from Earth","The changing amount of sunlit Moon visible from Earth as it orbits","The Moon changing shape"]'::jsonb, 2, 'As the Moon orbits Earth, we see different amounts of its sunlit half, creating the phases we observe.', 'AC9S3U02', null, null, true, null, null, null, null),
('75a2addb-9ebe-4b17-8e91-3d25a3bc88ff', 'earth_space', 'grade_4', 'developing', 'multiple_choice', 'Which of these is a source of fresh water?', '["Sea water","A river","The ocean","A salt lake"]'::jsonb, 1, 'Rivers are a common source of fresh water, unlike oceans and salt lakes, which contain salt water.', 'AC9S4U03', null, null, true, null, null, null, null),
('a25d74d4-cece-4b6b-a48c-e6f14137f07c', 'earth_space', 'grade_4', 'foundation', 'multiple_choice', 'What is the star at the centre of our solar system called?', '["The Sun","The Moon","Earth","Mars"]'::jsonb, 0, 'The Sun is the star at the centre of our solar system, and all the planets orbit around it.', 'AC9S4U03', null, null, true, null, null, null, null),
('40488c0d-1663-4350-a322-97d5c6bc197e', 'earth_space', 'grade_5', 'developing', 'multiple_choice', 'Which of these best describes the shape of Earth''s orbit around the Sun?', '["A perfect square","A straight line","A perfect triangle","An ellipse (a slightly stretched circle)"]'::jsonb, 3, 'Earth orbits the Sun in a slightly elongated circle known as an ellipse.', 'AC9S5U02', null, null, true, null, null, null, null),
('fbd0c82a-fed7-4658-961c-e2da033f2a6d', 'earth_space', 'grade_6', 'developing', 'multiple_choice', 'Which of these is an example of a non-renewable resource?', '["Wind","Timber from a managed forest","Coal","Solar energy"]'::jsonb, 2, 'Coal takes millions of years to form and cannot be replenished within a human lifetime, making it non-renewable.', 'AC9S6U03', null, null, true, null, null, null, null),
('bac08012-8cfa-4d1e-98f0-dc143bb9f6d2', 'earth_space', 'grade_6', 'proficient', 'multiple_choice', 'What is the layer of the Earth that we live on, made of solid rock, called?', '["The inner core","The crust","The mantle","The outer core"]'::jsonb, 1, 'The crust is the thin, solid outer layer of the Earth where we live.', 'AC9S6U03', null, null, true, null, null, null, null),
('46ef8104-e8cb-4306-b347-3c7be356109d', 'earth_space', 'year_7', 'developing', 'multiple_choice', 'Which type of rock forms when heat and pressure change an existing rock, without it melting?', '["Metamorphic rock","Igneous rock","Sedimentary rock","Volcanic rock"]'::jsonb, 0, 'Metamorphic rock forms when existing rock is changed by intense heat and pressure, without fully melting.', 'AC9S7U02', null, null, true, null, null, null, null),
('4d66b7b7-d370-410a-b0fd-427ca9a423b1', 'earth_space', 'year_8', 'developing', 'multiple_choice', 'Which layer of the atmosphere contains the ozone layer that absorbs harmful UV radiation?', '["Troposphere","Mesosphere","Exosphere","Stratosphere"]'::jsonb, 3, 'The ozone layer, which absorbs most of the sun''s harmful UV radiation, is located in the stratosphere.', 'AC9S8U02', null, null, true, null, null, null, null),
('14e20853-9c3f-48cc-90e3-cfedaa366d27', 'earth_space', 'year_9', 'developing', 'multiple_choice', 'Which human activity most contributes to an increase in atmospheric carbon dioxide?', '["Recycling paper","Using solar panels","Burning fossil fuels","Planting trees"]'::jsonb, 2, 'Burning fossil fuels, such as coal and oil, releases large amounts of carbon dioxide into the atmosphere.', 'AC9S9U04', null, null, true, null, null, null, null),
('e0f81a76-aa5e-4c87-90de-947d080b0fb5', 'earth_space', 'year_10', 'developing', 'multiple_choice', 'A large-scale wave, often caused by an underwater earthquake, is called a:', '["Drought","Tsunami","Hurricane","Blizzard"]'::jsonb, 1, 'A tsunami is a large ocean wave, most commonly triggered by an underwater earthquake or volcanic eruption.', 'AC9S10U02', null, null, true, null, null, null, null),
('148a2ead-f194-4f6b-9bd6-5cc9d82a08b2', 'chem_atomic_structure', 'year_11', 'foundation', 'multiple_choice', 'How many electrons can the second electron shell (n = 2) hold at maximum?', '["2","18","6","8"]'::jsonb, 3, 'The second shell (n = 2) holds a maximum of 8 electrons (2n² = 2×2² = 8).', null, null, null, true, null, null, null, null),
('13847855-2d4f-4490-b87d-26fcbb47be5f', 'chem_atomic_structure', 'year_11', 'developing', 'multiple_choice', 'An atom of carbon has atomic number 6. How many protons does it have?', '["8","14","6","12"]'::jsonb, 2, 'The atomic number equals the number of protons, so carbon has 6 protons.', null, null, null, true, null, null, null, null),
('a92eede6-c83d-4e2b-9332-da81f7464b43', 'chem_atomic_structure', 'year_11', 'developing', 'multiple_choice', 'What is the term for atoms of the same element with different numbers of neutrons?', '["Molecules","Isotopes","Ions","Isomers"]'::jsonb, 1, 'Isotopes are atoms of the same element (same protons) with a different number of neutrons.', null, null, null, true, null, null, null, null),
('ec2e421f-7d5d-440a-8388-dd0d7a13c772', 'chem_atomic_structure', 'year_11', 'developing', 'multiple_choice', 'What charge does a neutron carry?', '["No charge (neutral)","Positive charge","Negative charge","Variable charge"]'::jsonb, 0, 'A neutron has no electric charge, unlike protons (positive) and electrons (negative).', null, null, null, true, null, null, null, null),
('d8c1ef5c-5ec7-4685-963a-697e60a7a0be', 'chem_atomic_structure', 'year_11', 'proficient', 'multiple_choice', 'An atom that has lost an electron becomes a:', '["Negative ion (anion)","Neutral atom","Isotope","Positive ion (cation)"]'::jsonb, 3, 'Losing a negatively charged electron leaves the atom with a net positive charge, forming a cation.', null, null, null, true, null, null, null, null),
('b53694b4-19e3-4392-801f-716046d4746a', 'chem_atomic_structure', 'year_11', 'developing', 'multiple_choice', 'Elements in the same column (group) of the periodic table generally have the same number of:', '["Protons","Total electron shells","Valence (outer shell) electrons","Neutrons"]'::jsonb, 2, 'Elements in the same group share the same number of valence electrons, giving them similar chemical properties.', null, null, null, true, null, null, null, null),
('e1d34880-ea89-4a48-a8e6-e2963f88e52a', 'chem_reactions', 'year_11', 'developing', 'multiple_choice', 'What type of reaction releases heat energy to the surroundings?', '["Reduction reaction only","Exothermic reaction","Endothermic reaction","Neutral reaction"]'::jsonb, 1, 'An exothermic reaction releases energy, usually as heat, to its surroundings.', null, null, null, true, null, null, null, null),
('086fbfc9-dc42-4767-9ae6-0faed1e02d95', 'chem_reactions', 'year_11', 'developing', 'multiple_choice', 'What is produced when an acid reacts with a base?', '["A salt and water","Only a gas","Only a salt","Oxygen and hydrogen"]'::jsonb, 0, 'A neutralisation reaction between an acid and a base produces a salt and water.', null, null, null, true, null, null, null, null),
('fc7f0a6a-7046-44cd-9719-8743c94b6570', 'chem_reactions', 'year_11', 'proficient', 'multiple_choice', 'Balance the equation: __N2 + __H2 → __NH3', '["1, 2, 1","2, 3, 1","1, 3, 3","1, 3, 2"]'::jsonb, 3, 'N2 + 3H2 → 2NH3 balances nitrogen (2 atoms each side) and hydrogen (6 atoms each side).', null, null, null, true, null, null, null, null),
('8bcf73d5-f780-46c8-b6d1-97ee5d021b5f', 'chem_reactions', 'year_11', 'developing', 'multiple_choice', 'What is the correct chemical formula for water?', '["HO2","H3O","H2O","H2O2"]'::jsonb, 2, 'Water is made of two hydrogen atoms and one oxygen atom, giving the formula H2O.', null, null, null, true, null, null, null, null),
('a9bb8b8f-6e43-45a1-8134-27480896bfa5', 'chem_reactions', 'year_11', 'proficient', 'multiple_choice', 'In the reaction Zn + CuSO4 → ZnSO4 + Cu, zinc displaces copper. What type of reaction is this?', '["A decomposition reaction","A single displacement reaction","A combustion reaction","A neutralisation reaction"]'::jsonb, 1, 'Zinc, a more reactive metal, displaces copper from the compound, which is a single displacement reaction.', null, null, null, true, null, null, null, null),
('8ab671dd-8d31-4c98-9b08-81e60d6b3eb5', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'An object travels 20 m in 4 seconds at a constant speed. What is its speed?', '["5 m/s","7 m/s","3 m/s","10 m/s"]'::jsonb, 0, 'Speed = distance ÷ time = 20 ÷ 4 = 5 m/s.', null, null, null, true, null, null, null, null),
