('67bd79ea-d1f4-4e36-b3f0-b460773f5a5c', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'Using F = ma, what is the force on an object with mass 5 kg accelerating at 3 m/s²?', '["8 N","15 N","20 N","12 N"]'::jsonb, 1, 'F = m × a = 5 × 3 = 15 N.', null, null, null, true, null, null, null, null),
('ab8ee86c-9db0-40ab-a18a-a690d757a16c', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'Using F = ma, what is the force on an object with mass 10 kg accelerating at 2 m/s²?', '["20 N","30 N","18 N","12 N"]'::jsonb, 0, 'F = m × a = 10 × 2 = 20 N.', null, null, null, true, null, null, null, null),
('8235976f-ed56-4801-9f47-565b3e4d14d3', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'Using F = ma, what is the force on an object with mass 4 kg accelerating at 6 m/s²?', '["28 N","18 N","10 N","24 N"]'::jsonb, 3, 'F = m × a = 4 × 6 = 24 N.', null, null, null, true, null, null, null, null),
('cbca9365-056c-4a3b-9052-35c732aa4cd1', 'phys_mechanics', 'year_11', 'foundation', 'multiple_choice', 'What quantity measures how fast an object''s velocity is changing?', '["Displacement","Momentum","Acceleration","Speed"]'::jsonb, 2, 'Acceleration measures the rate of change of velocity over time.', null, null, null, true, null, null, null, null),
('ff0469a5-bbfe-4e11-822f-d5bf750b3f29', 'phys_mechanics', 'year_11', 'proficient', 'multiple_choice', 'What is the momentum of an object with mass 4 kg moving at 5 m/s?', '["45 kg·m/s","20 kg·m/s","9 kg·m/s","1.25 kg·m/s"]'::jsonb, 1, 'Momentum = mass × velocity = 4 × 5 = 20 kg·m/s.', null, null, null, true, null, null, null, null),
('6eb6f7c9-bb6f-4d0f-9c5c-3b5a6e009842', 'phys_mechanics', 'year_11', 'proficient', 'multiple_choice', 'Using Ep = mgh with m = 1 kg, g ≈ 10 m/s², and h = 80 m, what is the gravitational potential energy?', '["800 J","810 J","720 J","400 J"]'::jsonb, 0, 'Ep = mgh = 1 × 10 × 80 = 800 J.', null, null, null, true, null, null, null, null),
('4d40d0a3-5392-45aa-ad5a-5673d389e427', 'phys_mechanics', 'year_11', 'proficient', 'multiple_choice', 'Using Ep = mgh with m = 1 kg, g ≈ 9.8 m/s², and h = 50 m, what is the gravitational potential energy?', '["500 J","440 J","245 J","490 J"]'::jsonb, 3, 'Ep = mgh = 1 × 9.8 × 50 = 490 J.', null, null, null, true, null, null, null, null),
('b9bf1e8b-c7c4-4461-affa-3f7e9567c146', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'Using Ohm''s law, what is the current through a 4 Ω resistor with 12 V across it?', '["6 A","5 A","3 A","4 A"]'::jsonb, 2, 'I = V ÷ R = 12 ÷ 4 = 3 A.', null, null, null, true, null, null, null, null),
('d0a88c5f-f107-41bb-923c-3146b027450d', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'Using Ohm''s law, what is the current through a 4 Ω resistor with 20 V across it?', '["4 A","5 A","6 A","10 A"]'::jsonb, 1, 'I = V ÷ R = 20 ÷ 4 = 5 A.', null, null, null, true, null, null, null, null),
('205afd4c-b25d-4c6c-99dc-73e945ada9ce', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'Using Ohm''s law, what is the current through a 3 Ω resistor with 18 V across it?', '["6 A","7 A","12 A","3 A"]'::jsonb, 0, 'I = V ÷ R = 18 ÷ 3 = 6 A.', null, null, null, true, null, null, null, null),
('0f655e13-5eef-49d4-bd5e-a99c9658a07a', 'phys_electricity', 'year_11', 'foundation', 'multiple_choice', 'What is the unit of electrical charge?', '["Ampere","Volt","Watt","Coulomb"]'::jsonb, 3, 'Electrical charge is measured in coulombs, symbol C.', null, null, null, true, null, null, null, null),
('0d6a5df5-385e-4833-8784-818535cc176b', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'In a series circuit, how does the total resistance relate to the individual resistances?', '["It is always less than any individual resistance","It is the difference between the resistances","It is the sum of all the resistances","It is the average of the resistances"]'::jsonb, 2, 'In a series circuit, total resistance equals the sum of each individual resistance.', null, null, null, true, null, null, null, null),
('16e04cc5-be59-4405-8ae8-d6eebda267c4', 'phys_electricity', 'year_11', 'proficient', 'multiple_choice', 'What is the power used by a device with voltage 12 V and current 2 A? (P = VI)', '["10 W","24 W","14 W","6 W"]'::jsonb, 1, 'Power = voltage × current = 12 × 2 = 24 W.', null, null, null, true, null, null, null, null),
('1bc89c1b-aaa7-4887-997e-29c0ab65973f', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'Which material is generally the best electrical insulator?', '["Rubber","Copper","Silver","Aluminium"]'::jsonb, 0, 'Rubber does not allow electric current to flow easily through it, making it a good insulator, unlike metals.', null, null, null, true, null, null, null, null),
('d017ee6a-6aea-48f0-b97d-a441052976e6', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate: f(x) = 4x^3 + 2x', '["f''(x) = 12x^2","f''(x) = 12x^2 + 2","f''(x) = 4x^2 + 2","f''(x) = 12x^3 + 2"]'::jsonb, 1, 'Using the power rule, d/dx(4x^3) = 12x^2, and d/dx(2x) = 2.', null, null, null, true, null, null, null, null),
('26973d1f-693b-469d-9f0e-46e7dce7676a', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate: f(x) = 5x^2 + 3x', '["f''(x) = 10x^1 + 3","f''(x) = 5x^1 + 3","f''(x) = 10x^2 + 3","f''(x) = 10x^1"]'::jsonb, 0, 'Using the power rule, d/dx(5x^2) = 10x^1, and d/dx(3x) = 3.', null, null, null, true, null, null, null, null),
('e0f8577c-c08d-411c-9783-1a80f09313fa', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate: f(x) = 3x^4 + 4x', '["f''(x) = 3x^3 + 4","f''(x) = 12x^4 + 4","f''(x) = 12x^3","f''(x) = 12x^3 + 4"]'::jsonb, 3, 'Using the power rule, d/dx(3x^4) = 12x^3, and d/dx(4x) = 4.', null, null, null, true, null, null, null, null),
('b1074d16-1caa-4075-bff3-38d64c5273c0', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate: f(x) = 6x^2 + 5x', '["f''(x) = 12x^2 + 5","f''(x) = 12x^1","f''(x) = 12x^1 + 5","f''(x) = 6x^1 + 5"]'::jsonb, 2, 'Using the power rule, d/dx(6x^2) = 12x^1, and d/dx(5x) = 5.', null, null, null, true, null, null, null, null),
('ae1dca68-d197-4d15-8766-80bf59e38448', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate: f(x) = 2x^5 + 3x', '["f''(x) = 10x^4","f''(x) = 10x^4 + 3","f''(x) = 2x^4 + 3","f''(x) = 10x^5 + 3"]'::jsonb, 1, 'Using the power rule, d/dx(2x^5) = 10x^4, and d/dx(3x) = 3.', null, null, null, true, null, null, null, null),
('0b939f58-e4c9-4c94-8234-5171b533274e', 'mm_calculus', 'year_11', 'proficient', 'multiple_choice', 'If f(x) = 3x² + 2x, what is f''(1)?', '["8","11","6","5"]'::jsonb, 0, 'f''(x) = 6x + 2. At x = 1: 6 × 1 + 2 = 8.', null, null, null, true, null, null, null, null),
('e552d368-f94c-4168-9052-e16b4d8a8da2', 'mm_calculus', 'year_11', 'proficient', 'multiple_choice', 'If f(x) = 2x² − 3x, what is f''(4)?', '["15","16","5","13"]'::jsonb, 3, 'f''(x) = 4x − 3. At x = 4: 4 × 4 − 3 = 13.', null, null, null, true, null, null, null, null),
('9d22b63a-057f-470b-b725-e50c310ebafb', 'mm_calculus', 'year_11', 'proficient', 'multiple_choice', 'If f(x) = 5x² + 4x, what is f''(−2)?', '["−20","−6","−16","−11"]'::jsonb, 2, 'f''(x) = 10x + 4. At x = −2: 10 × −2 + 4 = −16.', null, null, null, true, null, null, null, null),
('0a522667-4d68-42f6-95f6-2882f3a1b45a', 'mm_calculus', 'year_11', 'foundation', 'multiple_choice', 'What does the derivative of a function represent at a point?', '["The maximum value of the function","The gradient (slope) of the tangent at that point","The area under the curve","The y-intercept of the function"]'::jsonb, 1, 'The derivative gives the instantaneous rate of change, which is the gradient of the tangent line at that point.', null, null, null, true, null, null, null, null),
('ca8ceb94-0802-4794-adfb-53d9f438a48c', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'What is the derivative of f(x) = x³?', '["f''(x) = 3x²","f''(x) = x²","f''(x) = 3x³","f''(x) = x²/3"]'::jsonb, 0, 'Using the power rule: d/dx(x³) = 3x².', null, null, null, true, null, null, null, null),
('06620d3e-4b86-4327-959a-7e841c7dc2b4', 'mm_calculus', 'year_11', 'proficient', 'multiple_choice', 'A function has a local maximum where its derivative is:', '["Always positive","Always negative","Undefined","Zero and changing from positive to negative"]'::jsonb, 3, 'At a local maximum, the gradient is momentarily zero as the function changes from increasing to decreasing.', null, null, null, true, null, null, null, null),
('8ca1f6ef-055f-4a21-966a-da0b5269bde4', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'What is the derivative of f(x) = 5 (a constant)?', '["f''(x) = 1","f''(x) = x","f''(x) = 0","f''(x) = 5"]'::jsonb, 2, 'The derivative of any constant is zero, since a constant does not change.', null, null, null, true, null, null, null, null),
('eb4123c2-ff2a-414c-bb10-6ccf32138624', 'mm_calculus', 'year_11', 'proficient', 'multiple_choice', 'What is the gradient of the tangent to f(x) = x² at x = 3?', '["12","6","9","3"]'::jsonb, 1, 'f''(x) = 2x, so at x = 3, the gradient is 2 × 3 = 6.', null, null, null, true, null, null, null, null),
('51625179-29a0-4c54-bf30-6dd4dd6051ca', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'If P(A) = 0.5 and P(B) = 0.5 are independent events, what is P(A and B)?', '["0.25","1","0.5","1.5"]'::jsonb, 0, 'For independent events, P(A and B) = P(A) × P(B) = 0.5 × 0.5 = 0.25.', null, null, null, true, null, null, null, null),
('e4680419-4c16-42fb-8033-b5a904db0d96', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'If P(A) = 0.3 and P(B) = 0.7 are independent events, what is P(A and B)?', '["1","0.3","0.7","0.21"]'::jsonb, 3, 'For independent events, P(A and B) = P(A) × P(B) = 0.3 × 0.7 = 0.21.', null, null, null, true, null, null, null, null),
('2be47a67-edd5-4810-82e4-bc7b5aaf9c42', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'If P(A) = 0.6 and P(B) = 0.4 are independent events, what is P(A and B)?', '["0.6","0.4","0.24","1"]'::jsonb, 2, 'For independent events, P(A and B) = P(A) × P(B) = 0.6 × 0.4 = 0.24.', null, null, null, true, null, null, null, null),
('ca91e652-8d09-4ef2-b9f0-bf90f44eb30f', 'mm_probability', 'year_11', 'proficient', 'multiple_choice', 'If P(A) = 0.4, P(B) = 0.3, and P(A and B) = 0.1, what is P(A or B)?', '["0.4","0.6","0.7","0.1"]'::jsonb, 1, 'P(A or B) = P(A) + P(B) − P(A and B) = 0.4 + 0.3 − 0.1 = 0.6.', null, null, null, true, null, null, null, null),
('82da0061-47a2-48c1-9c21-5412952cb06a', 'mm_probability', 'year_11', 'proficient', 'multiple_choice', 'If P(A) = 0.5, P(B) = 0.2, and P(A and B) = 0.1, what is P(A or B)?', '["0.6","0.7","0.1","0.5"]'::jsonb, 0, 'P(A or B) = P(A) + P(B) − P(A and B) = 0.5 + 0.2 − 0.1 = 0.6.', null, null, null, true, null, null, null, null),
('cb27677f-ad98-478d-aa92-e3e98c0203ee', 'mm_probability', 'year_11', 'foundation', 'multiple_choice', 'Two events are described as independent when:', '["They always happen together","They can never happen together","They have equal probabilities","The outcome of one does not affect the probability of the other"]'::jsonb, 3, 'Independent events do not influence each other; the outcome of one has no effect on the probability of the other.', null, null, null, true, null, null, null, null),
('75a4d06a-d128-4815-b778-404a973c0d50', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'A fair six-sided die is rolled. What is the probability of rolling an even number?', '["1/6","2/3","1/2","1/3"]'::jsonb, 2, 'There are 3 even numbers (2, 4, 6) out of 6 possible outcomes, giving a probability of 3/6 = 1/2.', null, null, null, true, null, null, null, null),
('2f0cff1b-3684-4be1-ad81-3acaa5ba4d6b', 'mm_probability', 'year_11', 'proficient', 'multiple_choice', 'What is the probability of drawing a king from a standard 52-card deck?', '["1/52","1/13","1/4","4/13"]'::jsonb, 1, 'There are 4 kings in a deck of 52 cards, giving a probability of 4/52 = 1/13.', null, null, null, true, null, null, null, null),
('cbf48c4f-a3fd-4a1a-becd-459eeffe8173', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'A discrete random variable is best described as one that:', '["Can take only specific, countable values","Can take any value in a range","Is always equal to 1","Cannot be measured"]'::jsonb, 0, 'A discrete random variable takes distinct, countable values, unlike a continuous variable which can take any value in an interval.', null, null, null, true, null, null, null, null),
('73a49a89-6843-4d14-826d-1c31b8f32dab', 'mm_probability', 'year_11', 'proficient', 'multiple_choice', 'For a binomial distribution with n trials and success probability p, the expected value (mean) is given by:', '["n + p","np(1−p)","p/n","np"]'::jsonb, 3, 'The mean of a binomial distribution is calculated as the number of trials multiplied by the probability of success, np.', null, null, null, true, null, null, null, null),
('8ed2b902-989d-40e5-ba80-173237f28e3e', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'What is the mean of: 4, 7, 9, 10, 5, 12?', '["6.83","12","7.83","8.83"]'::jsonb, 2, 'Sum = 47. Mean = 47 ÷ 6 = 7.83.', null, null, null, true, null, null, null, null),
('5be8f566-09ce-4593-b7a9-fd4a5114342b', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'What is the mean of: 6, 8, 10, 12, 4, 14?', '["14","9","10","8"]'::jsonb, 1, 'Sum = 54. Mean = 54 ÷ 6 = 9.', null, null, null, true, null, null, null, null),
('5d29cc6e-aafb-435a-b1ba-f0e770a2b2bb', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'What is the range of: 3, 7, 4, 9, 2, 15?', '["13","15","2","16"]'::jsonb, 0, 'Range = max − min = 15 − 2 = 13.', null, null, null, true, null, null, null, null),
('d908d7a3-c5fc-4ef7-9d08-bbdfce5615ba', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'What is the range of: 10, 4, 12, 6, 8?', '["12","4","10","8"]'::jsonb, 3, 'Range = max − min = 12 − 4 = 8.', null, null, null, true, null, null, null, null),
('23ab2720-a108-4115-8abe-8580d6fd8f32', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'A data set has Q1 = 5 and Q3 = 20. What is the interquartile range?', '["5","21","15","20"]'::jsonb, 2, 'IQR = Q3 − Q1 = 20 − 5 = 15.', null, null, null, true, null, null, null, null),
('3ba40142-6bfe-4319-a80a-079977eb8e72', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'A data set has Q1 = 10 and Q3 = 30. What is the interquartile range?', '["31","20","30","10"]'::jsonb, 1, 'IQR = Q3 − Q1 = 30 − 10 = 20.', null, null, null, true, null, null, null, null),
('e276b18a-a60e-49ad-a8ab-c21fbf920163', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'A data set has Q1 = 8 and Q3 = 24. What is the interquartile range?', '["16","24","8","25"]'::jsonb, 0, 'IQR = Q3 − Q1 = 24 − 8 = 16.', null, null, null, true, null, null, null, null),
('ef6437b8-827a-4ca0-9c35-1d8a5c2e6f2b', 'gm_data_analysis', 'year_11', 'foundation', 'multiple_choice', 'Which measure of centre is most affected by an extreme outlier in a data set?', '["The median","The mode","The range","The mean"]'::jsonb, 3, 'The mean is calculated using every value, so a single extreme outlier can pull it strongly in one direction, unlike the median.', null, null, null, true, null, null, null, null),
('400cdc68-f4ac-443b-988f-acda1fe55ea7', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'In a box plot, what does the line inside the box represent?', '["The mode","The range","The median","The mean"]'::jsonb, 2, 'The line inside a box plot marks the median (the middle value) of the data set.', null, null, null, true, null, null, null, null),
('3f232a72-0e11-4f28-b1bf-49133d438cd3', 'gm_data_analysis', 'year_11', 'proficient', 'multiple_choice', 'A data set is described as positively skewed when:', '["It has no outliers","It has a long tail extending to the right","It has a long tail extending to the left","It is perfectly symmetric"]'::jsonb, 1, 'A positively skewed distribution has a longer tail on the right side, with the mean typically greater than the median.', null, null, null, true, null, null, null, null),
('eec6117a-44bf-433d-a3cf-931940534924', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'What does the standard deviation of a data set measure?', '["The spread of data around the mean","The middle value of the data","The most frequent value","The total of all values"]'::jsonb, 0, 'Standard deviation measures how spread out data values are from the mean.', null, null, null, true, null, null, null, null),
('6e1b5b35-e265-4737-b5d7-58a0dcaffb34', 'gm_financial', 'year_11', 'developing', 'multiple_choice', 'How much simple interest is earned on $1000 invested at 4% per year, over 3 years?', '["$130","$1000","$60","$120"]'::jsonb, 3, 'Simple interest = P × r × t = 1000 × 0.04 × 3 = $120.', null, null, null, true, null, null, null, null),
('521a3740-8510-4217-b96d-798a3c8c4ee3', 'gm_financial', 'year_11', 'developing', 'multiple_choice', 'How much simple interest is earned on $2000 invested at 5% per year, over 2 years?', '["$2000","$100","$200","$220"]'::jsonb, 2, 'Simple interest = P × r × t = 2000 × 0.05 × 2 = $200.', null, null, null, true, null, null, null, null),
('5c635027-be5a-4f76-9429-8b2d2d004e15', 'gm_financial', 'year_11', 'developing', 'multiple_choice', 'How much simple interest is earned on $1500 invested at 3% per year, over 4 years?', '["$90","$180","$195","$1500"]'::jsonb, 1, 'Simple interest = P × r × t = 1500 × 0.03 × 4 = $180.', null, null, null, true, null, null, null, null),
('573f379f-1c60-4633-8f67-b1c06e04f0a2', 'gm_financial', 'year_11', 'proficient', 'multiple_choice', 'Using compound interest, what is the value of $1000 invested at 5% per year (compounded annually) after 2 years?', '["$1103","$1100","$1000","$1153"]'::jsonb, 0, 'A = P(1 + r)^t = 1000 × (1 + 0.05)^2 = $1103.', null, null, null, true, null, null, null, null),
('6a0880f6-97cb-4c2e-9107-4d6dc92ad737', 'gm_financial', 'year_11', 'proficient', 'multiple_choice', 'Using compound interest, what is the value of $2000 invested at 4% per year (compounded annually) after 2 years?', '["$2160","$2000","$2213","$2163"]'::jsonb, 3, 'A = P(1 + r)^t = 2000 × (1 + 0.04)^2 = $2163.', null, null, null, true, null, null, null, null),
('ce8b7f9e-994e-404a-9e5e-a6f54acaa71a', 'gm_financial', 'year_11', 'foundation', 'multiple_choice', 'What term describes the original amount of money borrowed or invested, before interest?', '["Balance","Rate","Principal","Interest"]'::jsonb, 2, 'The principal is the original sum of money, before any interest is added.', null, null, null, true, null, null, null, null),
('9302a2b8-ec8b-4781-8373-e6ef99835c75', 'gm_financial', 'year_11', 'developing', 'multiple_choice', 'What is the main difference between simple and compound interest?', '["Simple interest changes every year","Compound interest is calculated on the principal plus previously earned interest","Simple interest is always higher","Compound interest is only used for loans"]'::jsonb, 1, 'Compound interest grows faster because it is calculated on the accumulated total, not just the original principal.', null, null, null, true, null, null, null, null),
('226873d3-9000-49cb-8af6-f99362a202d1', 'gm_financial', 'year_11', 'proficient', 'multiple_choice', 'A car valued at $20,000 depreciates by 15% in its first year. What is its value after one year?', '["$17,000","$3,000","$18,500","$15,000"]'::jsonb, 0, 'Depreciation of 15% means the car loses 0.15 × $20,000 = $3,000, leaving $20,000 − $3,000 = $17,000.', null, null, null, true, null, null, null, null),
('7ec6a61e-a615-464c-b923-ccc785640dc5', 'gm_financial', 'year_11', 'developing', 'multiple_choice', 'A loan repayment plan where equal amounts are paid at regular intervals is called:', '["A dividend","A principal","A deposit","An annuity"]'::jsonb, 3, 'An annuity is a series of equal payments made at regular intervals, commonly used to repay loans.', null, null, null, true, null, null, null, null),
('9c3b5c45-25f0-4f1f-851d-6847d5057a91', 'gm_financial', 'year_11', 'foundation', 'multiple_choice', 'Which of these best describes "flat rate" interest on a loan?', '["An interest rate of exactly 0%","A rate charged only in the final year","A fixed percentage charged on the original amount borrowed for the full term","An interest rate that changes daily"]'::jsonb, 2, 'Flat rate interest is calculated as a fixed percentage of the original principal, applied for the entire loan term, similar to simple interest.', null, null, null, true, null, null, null, null),
('0d928591-2223-4479-ac5b-2e88369d32ff', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is the modulus of the complex number 5 − 12i?', '["7","13","17","169"]'::jsonb, 1, '|a + bi| = √(a² + b²) = √(5² + (−12)²) = √(25 + 144) = √169 = 13.', 'VCE-SM-U1', null, null, true, null, null, null, null),
('bcc3aef1-1fcc-48eb-9e21-3120ecc54a52', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is the modulus of the complex number 5 + 12i?', '["12","17","13","15"]'::jsonb, 2, 'Modulus = √(5² + 12²) = √169 = 13.', null, null, null, true, null, null, null, null),
('32ee668b-2615-4e4c-a153-93f90f2c3289', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is the modulus of the complex number 8 + 6i?', '["14","10","12","9"]'::jsonb, 1, 'Modulus = √(8² + 6²) = √100 = 10.', null, null, null, true, null, null, null, null),
('6c139960-7a4e-4b3b-8686-f7ed84cc2bae', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is (2 + 3i) + (1 − 4i)?', '["3 − 1i","3 + 1i","3 − 7i","1 − 1i"]'::jsonb, 0, 'Add the real parts: 2 + 1 = 3. Add the imaginary parts: 3 + (−4) = −1, giving 3 − 1i.', null, null, null, true, null, null, null, null),
('b09765ca-7a25-4f4e-84c9-df4510e8ff17', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is (4 − 2i) − (1 + 3i)?', '["3 + 5i","5 − 5i","3 − 1i","3 − 5i"]'::jsonb, 3, 'Subtract the real parts: 4 − 1 = 3. Subtract the imaginary parts: −2 − 3 = −5, giving 3 − 5i.', null, null, null, true, null, null, null, null),
('aa542fe0-441f-4407-9de1-1d3e875057a7', 'sm_complex_numbers', 'year_11', 'foundation', 'multiple_choice', 'What is i³ (where i is the imaginary unit)?', '["1","−1","−i","i"]'::jsonb, 2, 'i³ = i² × i = (−1) × i = −i.', null, null, null, true, null, null, null, null),
('fbcaaace-58a7-4af4-b31c-77eb6e16fb65', 'sm_complex_numbers', 'year_11', 'proficient', 'multiple_choice', 'What is the complex conjugate of 5 − 3i?', '["3 − 5i","5 + 3i","−5 − 3i","−5 + 3i"]'::jsonb, 1, 'The complex conjugate flips the sign of the imaginary part: 5 − 3i becomes 5 + 3i.', null, null, null, true, null, null, null, null),
('7c9f7c4d-4231-4ee2-ad0e-700dcf63956f', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'In the complex plane, the real part of a complex number is plotted on the:', '["Horizontal axis","Vertical axis","Diagonal axis","Origin only"]'::jsonb, 0, 'By convention, the real part is plotted on the horizontal axis and the imaginary part on the vertical axis.', null, null, null, true, null, null, null, null),
('26e96f10-dfd5-4ba0-a320-44c414cc32ac', 'sm_vectors', 'year_11', 'developing', 'multiple_choice', 'What is the magnitude of the vector (3, 4)?', '["7","4","8","5"]'::jsonb, 3, 'Magnitude = √(3² + 4²) = √25 = 5.', null, null, null, true, null, null, null, null),
('57e7d811-de54-4c0c-a3fc-ea6f65ed8b1e', 'sm_vectors', 'year_11', 'developing', 'multiple_choice', 'What is the magnitude of the vector (9, 40)?', '["31","41","49","1681"]'::jsonb, 1, '|v| = √(9² + 40²) = √(81 + 1600) = √1681 = 41.', 'VCE-SM-U1', null, null, true, null, null, null, null),
('fb85968c-97c0-45a6-a459-94e8f3783354', 'sm_vectors', 'year_11', 'developing', 'multiple_choice', 'What is the magnitude of the vector (5, 12)?', '["17","13","15","12"]'::jsonb, 1, 'Magnitude = √(5² + 12²) = √169 = 13.', null, null, null, true, null, null, null, null),
('dc79b6d3-25cb-4e63-b710-3367a3d10807', 'sm_vectors', 'year_11', 'foundation', 'multiple_choice', 'Two vectors are parallel. What can be said about the angle between them?', '["It is 0° or 180°","It is always 90°","It is always 45°","It cannot be determined"]'::jsonb, 0, 'Parallel vectors point in the same direction (0°) or exactly opposite directions (180°).', null, null, null, true, null, null, null, null),
('e51e94b6-73a9-4e93-82d9-c99b6aed828a', 'sm_vectors', 'year_11', 'proficient', 'multiple_choice', 'What is the dot product of vectors (2, 3) and (4, 1)?', '["9","6","14","11"]'::jsonb, 3, 'Dot product = (2×4) + (3×1) = 8 + 3 = 11.', null, null, null, true, null, null, null, null),
('ecfb8afc-896b-4c15-9da7-9d96e2a95797', 'sm_vectors', 'year_11', 'developing', 'multiple_choice', 'A vector with magnitude 1 is called a:', '["Position vector","Scalar","Unit vector","Zero vector"]'::jsonb, 2, 'A unit vector has a magnitude of exactly 1 and is often used to indicate direction.', null, null, null, true, null, null, null, null),
('01ea0cce-4884-45b0-be52-ebfce2a5a127', 'number_operations', 'grade_3', 'foundation', 'multiple_choice', 'A farmer has 6 crates with 7 eggs in each crate. How many eggs does the farmer have in total?', '["13","36","42","48"]'::jsonb, 2, '6 × 7 means 6 groups of 7, which is 42.', 'AC9M3N05', null, null, true, null, null, null, null),
('13048b7c-2483-4894-8c05-911e7183897d', 'number_operations', 'grade_3', 'developing', 'short_answer', 'A shelf holds 60 library books. 24 of them are borrowed. How many books are left on the shelf?', null, null, 'Take the borrowed books away: 60 − 24 = 36 books left.', 'AC9M3N04', null, null, true, '36', null, null, null),
('71ac3bf7-3e2b-48ab-a453-6d7c26830637', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'Liam ate 3/6 of a block of chocolate. Which fraction below is equal to the amount he ate?', '["1/2","3/4","1/3","2/3"]'::jsonb, 0, '3/6 simplifies to 1/2 because 3 is half of 6.', 'AC9M3N02', null, null, true, null, null, null, null),
('d372d918-fad0-433f-8cb9-908607a9680e', 'number_operations', 'grade_3', 'proficient', 'multiple_choice', 'A parent volunteer has 24 apples to share equally into 4 fruit baskets for the classroom. How many apples go in each basket?', '["6","8","20","28"]'::jsonb, 0, '24 ÷ 4 = 6 apples in each basket.', 'AC9M3N05', null, null, true, null, null, null, null),
('c8debda9-717c-4942-aa40-dde0be9369a0', 'number_operations', 'grade_4', 'foundation', 'multiple_choice', 'A charity bake sale raised $3,482. Rounded to the nearest hundred dollars, how much did the bake sale raise?', '["$3,400","$3,000","$3,500","$3,480"]'::jsonb, 2, '3,482 is closer to 3,500 than to 3,400, so it rounds up to $3,500.', 'AC9M4N01', null, null, true, null, null, null, null),
('4fbb62a4-8c6e-4a92-9f4c-49aad19608ca', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'Leo eats 3/8 of a pizza and his sister eats another 2/8 of the same pizza. What fraction of the pizza have they eaten together?', '["1/8","5/8","6/8","5/16"]'::jsonb, 1, 'Same denominator, so add the numerators: 3 + 2 = 5, giving 5/8.', 'AC9M4N03', null, null, true, null, null, null, null),
('0aa0aa8d-a87f-4d60-a37b-cc22f9150245', 'number_operations', 'grade_4', 'developing', 'short_answer', 'A teacher has 128 pencils to share equally among 4 classroom tubs. How many pencils go in each tub?', null, null, '128 ÷ 4 = 32 pencils in each tub (4 × 32 = 128).', 'AC9M4N05', null, null, true, '32', null, null, null),
('db7a5af5-89a8-462d-bfba-e765c0701d97', 'number_operations', 'grade_4', 'proficient', 'multiple_choice', 'A recipe says to use 7/10 of a cup of milk. Written as a decimal, how much milk is that?', '["0.7","7.0","0.07","0.17"]'::jsonb, 0, 'Tenths are written as one decimal place: 7/10 = 0.7.', 'AC9M4N06', null, null, true, null, null, null, null),
('9a2d3e61-0aa6-4e86-a52e-fa3a2b0a9e7e', 'number_operations', 'grade_5', 'foundation', 'multiple_choice', 'A fundraiser sells 47 raffle tickets to each of the 12 classes in the school. How many raffle tickets are sold in total?', '["554","470","584","564"]'::jsonb, 3, '47 × 12 = 47 × 10 + 47 × 2 = 470 + 94 = 564.', 'AC9M5N04', null, null, true, null, null, null, null),
('4413d384-72f4-460a-99c9-b101c1b6898d', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'A recipe needs 2/3 cup of flour, but Noah has already added 1/3 cup. How much more flour does he need to add?', '["3/3","1/3","1/6","2/6"]'::jsonb, 1, 'Same denominator: 2 − 1 = 1, giving 1/3.', 'AC9M5N03', null, null, true, null, null, null, null),
('15ede988-3537-4eef-85de-958669f5e120', 'number_operations', 'grade_5', 'proficient', 'multiple_choice', 'A charity walk aims to raise $250. So far, donations have reached 10% of the target. How much money has been raised so far?', '["$50","$10","$25","$2.50"]'::jsonb, 2, '10% means 10/100, so $250 × 0.1 = $25.', 'AC9M5N06', null, null, true, null, null, null, null),
('f1bc1984-8fc0-4ef1-8a69-d3fdeaddffd3', 'number_operations', 'grade_5', 'proficient', 'short_answer', 'A baker has 144 muffins to pack equally into boxes of 6. How many boxes does she need?', null, null, '6 × 24 = 144, so 144 ÷ 6 = 24 boxes.', 'AC9M5N04', null, null, true, '24', null, null, null),
('15d1036b-3d57-4c75-aa02-8fda4b951b62', 'number_operations', 'grade_6', 'foundation', 'multiple_choice', 'A recipe uses 3/4 cup of butter, but Grandma wants to make only 2/5 of the full recipe. How much butter does she need?', '["3/10","5/9","6/9","2/9"]'::jsonb, 0, 'Multiply numerators and denominators: (3×2)/(4×5) = 6/20, which simplifies to 3/10.', 'AC9M6N04', null, null, true, null, null, null, null),
('a0c966bd-475e-4dc2-b739-5e016baced04', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'Two offcuts of timber measure 0.6 m and 0.35 m. What is their combined length?', '["0.41","9.5","0.65","0.95"]'::jsonb, 3, 'Line up decimal places: 0.60 + 0.35 = 0.95 m.', 'AC9M6N05', null, null, true, null, null, null, null),
('eacab220-da5d-4e17-a99c-b97891d75a15', 'number_operations', 'grade_6', 'proficient', 'multiple_choice', 'A pancake recipe uses a ratio of 2 cups of flour to 1 cup of milk. If a chef scales the recipe up to use 6 cups of flour, how much milk is needed?', '["3 cups","2 cups","6 cups","12 cups"]'::jsonb, 0, 'The ratio 2:1 scaled up by 3 (since 6 = 2×3) gives 3 cups of milk.', 'AC9M6N02', null, null, true, null, null, null, null),
('3d461de9-6a22-4132-9d2b-c6bc2ec124e9', 'number_operations', 'grade_6', 'advanced', 'multiple_choice', 'A bookshop marks down a $180 bookshelf by 25% for a warehouse sale. How much is the discount?', '["$35","$25","$45","$90"]'::jsonb, 2, '25% = 1/4, and $180 ÷ 4 = $45.', 'AC9M6N06', null, null, true, null, null, null, null),
('b30963a2-caf1-4289-8c55-06df7b4aac63', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'Ruby has these coins in her purse. How much money does Ruby have altogether?', '["50 cents","70 cents","80 cents","90 cents"]'::jsonb, 2, 'The three 20-cent coins make 60 cents, and the two 10-cent coins make 20 cents: 60 + 20 = 80 cents.', 'AC9M3N07', null, null, true, null, null, null, null),
('fa08326d-a8c7-4f16-bd9e-d7adbf2dfea3', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'For the school art show, 8 tables are set up with 5 paintings displayed on each table. How many paintings are on display in total?', '["13","40","35","45"]'::jsonb, 1, '8 groups of 5 is 8 × 5 = 40.', 'AC9M3N05', null, null, true, null, null, null, null),
('f77acbbd-0bd9-4978-9d75-200d0ff3b7b4', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'In a basketball match, the home team scored 34 points in the first half and 28 points in the second half. How many points did they score in total?', '["52","58","62","72"]'::jsonb, 2, 'Add the halves together: 34 + 28 = 62.', 'AC9M3N04', null, null, true, null, null, null, null),
('8679c91d-9fb1-4b7e-964e-f2efb1598b27', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'A packet of 48 balloons is shared equally between 6 party bags. How many balloons go in each bag?', '["7","9","6","8"]'::jsonb, 3, '48 ÷ 6 = 8 balloons in each bag.', 'AC9M3N05', null, null, true, null, null, null, null),
('6826f1c9-6c25-425a-81e8-867c7d9bc803', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'A vegetable garden bed is divided into 8 equal sections. Carrots are planted in 3 of the sections. What fraction of the bed is planted with carrots?', '["3/8","8/3","3/5","5/8"]'::jsonb, 0, '3 sections out of 8 equal sections is 3/8.', 'AC9M3N06', null, null, true, null, null, null, null),
('5f235448-b549-4ffe-899a-5ecec84d25ff', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'Sienna uses the number sentence 5 × 4 = 20 to solve a problem. Which problem could she solve with this number sentence?', '["Sienna has 5 stickers and gets 4 more. How many does she have now?","Sienna has 5 boxes with 4 pencils in each box. How many pencils does she have?","Sienna has 5 stickers and gives 4 away. How many does she have left?","Sienna shares 20 stickers between 5 friends. How many does each friend get?"]'::jsonb, 1, '5 × 4 means 5 groups of 4. Only the boxes problem describes 5 groups of 4 pencils.', 'AC9M3N01', null, null, true, null, null, null, null),
('d5393723-8dbc-4521-87ff-78a495a0e1fd', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'A school choir has 7 rows with 9 singers standing in each row. How many singers are in the choir in total?', '["16","56","63","72"]'::jsonb, 2, '7 rows of 9 is 7 × 9 = 63.', 'AC9M3N05', null, null, true, null, null, null, null),
('7fa4b4be-8bdb-4775-a27a-2021472d993c', 'number_operations', 'grade_3', 'proficient', 'multiple_choice', 'A family buys 4 movie tickets that cost $6 each and pays with a $50 note. How much change does the family receive?', '["24","20","30","26"]'::jsonb, 3, '4 tickets cost 4 × $6 = $24. Change from $50 is $50 − $24 = $26.', 'AC9M3N07', null, null, true, null, null, null, null),
('db1c0a90-54a6-4840-9a42-f02b75e87f20', 'number_operations', 'grade_3', 'proficient', 'multiple_choice', 'For sports carnival relays, 3 classes each need 9 batons, plus 5 spare batons are kept in the storeroom. How many batons are needed in total?', '["32","27","37","42"]'::jsonb, 0, '3 classes × 9 batons = 27, plus 5 spares: 27 + 5 = 32.', 'AC9M3N05', null, null, true, null, null, null, null),
('e9f16154-1853-4c99-93d4-6b1edaea0ae7', 'number_operations', 'grade_3', 'proficient', 'multiple_choice', 'A classroom has 4 tables with 5 chairs at each table, and 3 more chairs against the wall. How many chairs are in the classroom altogether?', '["12","20","23","35"]'::jsonb, 2, 'The tables have 4 × 5 = 20 chairs. Add the 3 spare chairs: 20 + 3 = 23.', 'AC9M3N04', null, null, true, null, null, null, null),
('832e4a5e-7f5e-49c1-9f14-bf765bacd497', 'number_operations', 'grade_3', 'proficient', 'multiple_choice', 'A recycling drive splits its cans into 10 equal parts. Room 4 collected 3 of those parts, and Room 5 collected another 4 of those parts. What fraction of the total cans did the two rooms collect together?', '["7/20","1/10","7/10","8/10"]'::jsonb, 2, 'Same denominator, so add the numerators: 3/10 + 4/10 = 7/10.', 'AC9M3N02', null, null, true, null, null, null, null),
('62c37da6-01db-42de-aa09-6ca551a837b9', 'number_operations', 'grade_3', 'advanced', 'multiple_choice', 'Ben and Zoe have 26 marbles altogether. Ben has 4 more marbles than Zoe. How many marbles does Ben have?', '["11","13","15","22"]'::jsonb, 2, 'Take the extra 4 off first: 26 − 4 = 22, shared evenly is 11 each. Zoe has 11 and Ben has 11 + 4 = 15.', 'AC9M3N04', null, null, true, null, null, null, null),
('31ee1072-42d1-4b60-aaad-f90bb0539328', 'number_operations', 'grade_3', 'advanced', 'multiple_choice', 'Tickets to the school concert cost $3 each. Mrs Lee buys 7 tickets. How much do the tickets cost altogether?', '["$10","$18","$21","$24"]'::jsonb, 2, '7 tickets at $3 each: 7 × 3 = $21.', 'AC9M3N07', null, null, true, null, null, null, null),
('25dadd18-5199-4448-bc9b-a1437980f083', 'number_operations', 'grade_3', 'developing', 'short_answer', 'Sasha thinks of a number. The number is less than 100. It has 7 tens. The digit in the ones place is 3. What is Sasha’s number?', null, null, '7 tens is 70, and 3 ones makes 73.', 'AC9M3N04', null, null, true, '73', null, null, null),
('69290335-682f-45bb-a6b4-34df75e1fa65', 'number_operations', 'grade_3', 'developing', 'short_answer', 'A toy box holds 96 building blocks. Grace packs them equally into 8 storage tubs. How many blocks go in each tub?', null, null, '96 ÷ 8 = 12 blocks in each tub.', 'AC9M3N05', null, null, true, '12', null, null, null),
('5acf9b97-4d6b-4991-bdb6-5602befbe85f', 'number_operations', 'grade_3', 'proficient', 'short_answer', 'A textbook costs $9. The school orders enough copies for 34 new students, plus 6 extra copies for the library. How much does the school spend in total?', null, null, '34 + 6 = 40 copies needed. 40 × $9 = $360.', 'AC9M3N07', null, null, true, '$360', ARRAY['360', '$360.00', '360.00']::text[], null, null),
