('93215a98-37e3-474d-b6a9-6987a9a734dc', 'number_operations', 'grade_3', 'advanced', 'short_answer', 'A school hall is set up with 14 rows of chairs. Each row has 12 chairs, except the very back row, which only has 8 chairs because of a fire exit. How many chairs are set up in total?', null, null, '13 full rows: 13 × 12 = 156. Plus the back row: 156 + 8 = 164.', 'AC9M3N05', null, null, true, '164', null, null, null),
('160c834c-e4f4-42ff-ba6d-abe8e0319801', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'A school athletics day had 4,215 spectators on Saturday. Rounded to the nearest thousand, how many spectators attended?', '["4200","4000","5000","4300"]'::jsonb, 1, '4,215 is closer to 4,000 than to 5,000, so it rounds to 4,000.', 'AC9M4N01', null, null, true, null, null, null, null),
('4fec8524-a365-4de2-86b1-98bc9ecf7434', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'At camp, 456 marshmallows are shared equally among 8 campers. How many marshmallows does each camper get?', '["47","67","57","65"]'::jsonb, 2, '456 ÷ 8 = 57 marshmallows each.', 'AC9M4N05', null, null, true, null, null, null, null),
('2c95cf83-d2cd-4c0e-bd47-a1341eb6f796', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'A tailor starts with a full roll of fabric and uses 2/5 of it to make a costume. What fraction of the roll is left?', '["2/5","1/5","4/5","3/5"]'::jsonb, 3, 'The whole roll is 5/5. Take away the amount used: 5/5 − 2/5 = 3/5.', 'AC9M4N03', null, null, true, null, null, null, null),
