('87dc6966-a440-4149-8bfc-f72fe87a17df', 'number_operations', 'grade_4', 'developing', 'multiple_choice', 'Four cross-country running times, in minutes, are recorded as 12.35, 12.5, 12.53 and 12.08. Which time is the fastest (shortest)?', '["12.35","12.5","12.53","12.08"]'::jsonb, 3, '12.08 has the smallest value in the tenths and hundredths place, so it is the shortest time.', 'AC9M4N06', null, null, true, null, null, null, null),
('0c54e978-dfa2-48f0-8a5c-7603047c12db', 'number_operations', 'grade_4', 'proficient', 'multiple_choice', 'A baker uses 3/4 of a cup of sugar for one batch of cookies and makes 5 batches for a market stall. How many cups of sugar does she use in total?', '["3 3/4","5 3/4","3","4 1/4"]'::jsonb, 0, '3/4 × 5 = 15/4, which is 3 3/4 cups.', 'AC9M4N03', null, null, true, null, null, null, null),
('75400701-ab1c-4e04-acda-7d29aa913901', 'number_operations', 'grade_4', 'proficient', 'multiple_choice', 'Concert tickets normally cost $18, but a $5 discount applies for students. A group of 7 students attends. How much do they pay in total?', '["81","91","126","96"]'::jsonb, 1, 'Each student pays $18 − $5 = $13. 7 × $13 = $91.', 'AC9M4N07', null, null, true, null, null, null, null),
('387fa982-bb35-4a70-a747-c8814e9facfd', 'number_operations', 'grade_4', 'proficient', 'multiple_choice', 'A farmer has 1,000 eggs and packs them into cartons of 12, selling only full cartons. How many full cartons can he pack?', '["80","84","83","82"]'::jsonb, 2, '1,000 ÷ 12 = 83 remainder 4, so 83 full cartons can be packed.', 'AC9M4N05', null, null, true, null, null, null, null),
('886cedf8-ddc7-41d3-81b2-39960a167b67', 'number_operations', 'grade_4', 'proficient', 'multiple_choice', 'A school tuck shop sells popcorn bags for $3 each. On fete day it sells 156 bags in the morning and 89 bags in the afternoon. How much money does the tuck shop make from popcorn on fete day?', '["245","725","745","735"]'::jsonb, 3, 'Total bags sold: 156 + 89 = 245. Money made: 245 × $3 = $735.', 'AC9M4N07', null, null, true, null, null, null, null),
('8732a716-dad2-440f-91f3-1232fbdf6298', 'number_operations', 'grade_4', 'advanced', 'multiple_choice', 'A box of 150 juice poppers is shared equally among 9 classes, with any leftover poppers kept aside for the office. How many poppers does each class get?', '["16","17","15","18"]'::jsonb, 0, '150 ÷ 9 = 16 remainder 6, so each class gets 16 poppers.', 'AC9M4N05', null, null, true, null, null, null, null),
('d6c1cf1b-174a-4761-b780-0c9aca98010f', 'number_operations', 'grade_4', 'advanced', 'multiple_choice', 'A school buys 8 boxes of 45 pencils each ready for the year. It later finds 36 pencils are water-damaged and unusable, and donates a further 60 pencils to a sister school. How many usable pencils remain for students?', '["300","264","324","254"]'::jsonb, 1, '8 × 45 = 360 pencils bought. Remove the damaged ones: 360 − 36 = 324. Remove the donated ones: 324 − 60 = 264.', 'AC9M4N05', null, null, true, null, null, null, null),
('be85354f-7df2-4fde-911a-a77dfaa3a8e1', 'number_operations', 'grade_4', 'developing', 'short_answer', 'A school garden bed produces 372 carrots in spring and 259 more in summer. How many carrots were harvested in total?', null, null, '372 + 259 = 631.', 'AC9M4N04', null, null, true, '631', null, null, null),
('c11c2e39-fa1c-48a0-a313-c7b32737fb9a', 'number_operations', 'grade_4', 'developing', 'short_answer', 'A stationery order of 216 pencils is shared equally among 6 classes. How many pencils does each class receive?', null, null, '216 ÷ 6 = 36 pencils each.', 'AC9M4N05', null, null, true, '36', null, null, null),
('26cd36bc-b6bb-427a-8d27-e1e74765dd52', 'number_operations', 'grade_4', 'proficient', 'short_answer', 'A camp store sells drink bottles for $7 each. A group buys 12 bottles and pays with a $100 note. How much change do they receive?', null, null, '12 × $7 = $84. Change from $100 is $100 − $84 = $16.', 'AC9M4N07', null, null, true, '$16', ARRAY['16', '$16.00', '16.00']::text[], null, null),
('3632c879-124e-4565-b1a2-e609f3824767', 'number_operations', 'grade_4', 'proficient', 'short_answer', 'A school photocopier prints flyers at a cost of $0.12 each. The office needs to print 1,250 flyers for an open day. How much will the printing cost in total?', null, null, '1250 × $0.12 = $150.', 'AC9M4N07', null, null, true, '$150', ARRAY['150', '$150.00', '150.00']::text[], null, null),
('8573768d-4e88-47c8-b56b-469a20b7dfaa', 'number_operations', 'grade_4', 'advanced', 'short_answer', 'A library has 1,344 books to shelve equally across 8 new shelving units, but 24 damaged books must be set aside first before shelving the rest. How many books go on each shelf?', null, null, 'Set aside the damaged books first: 1344 − 24 = 1320. Then share equally: 1320 ÷ 8 = 165.', 'AC9M4N05', null, null, true, '165', null, null, null),
('31423d8d-1fac-4a7f-8798-314928544653', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'What is the value of the digit 7 in the number 47 320?', '["7","700","7000","70 000"]'::jsonb, 2, 'Reading the places from the right: 0 ones, 2 tens, 3 hundreds, 7 thousands. The 7 is worth 7000.', 'AC9M5N01', null, null, true, null, null, null, null),
('c8ebddd3-f59d-4e22-8428-335b045f472f', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'A ribbon is 7/10 of a metre long. A piece 3/10 of a metre long is cut off. What length of ribbon is left?', '["3/10 m","4/10 m","4/20 m","10/10 m"]'::jsonb, 1, 'Both lengths are tenths, so subtract directly: 7/10 − 3/10 = 4/10 of a metre.', 'AC9M5N05', null, null, true, null, null, null, null),
('2f241bf8-a32f-482d-9d4f-17b819705158', 'number_operations', 'grade_5', 'proficient', 'multiple_choice', 'A cinema has 14 rows with 18 seats in each row. How many seats are in the cinema?', '["32","142","252","272"]'::jsonb, 2, '14 × 18 = (14 × 10) + (14 × 8) = 140 + 112 = 252 seats.', 'AC9M5N04', null, null, true, null, null, null, null),
('f6474727-fc68-4455-b5f9-78dc3fb87d13', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'A charity walks a 4.25 km loop. If the loop is walked 1,000 times across the year by different participants combined, what is the total distance walked, in kilometres?', '["425","4250","42.5","42500"]'::jsonb, 1, 'Multiplying by 1,000 moves the decimal point three places right: 4.25 × 1000 = 4250 km.', 'AC9M5N04', null, null, true, null, null, null, null),
('88bdc531-dd43-41a9-80df-eb93792d6355', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'A school choir of 60 students has 25% who sing soprano. How many students sing soprano?', '["12","20","15","24"]'::jsonb, 2, '25% of 60 = 1/4 × 60 = 15.', 'AC9M5N05', null, null, true, null, null, null, null),
('e46d8e8d-fcf2-4f68-bb51-4a8c7b78189e', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'A school hall needs to seat 275 students in rows of 9 seats. How many full rows of 9 can be filled?', '["31","29","32","30"]'::jsonb, 3, '275 ÷ 9 = 30 remainder 5, so 30 full rows can be filled.', 'AC9M5N04', null, null, true, null, null, null, null),
('31dca204-02c7-4cfa-a74e-a051ff8dbc66', 'number_operations', 'grade_5', 'developing', 'multiple_choice', 'A community garden harvested 452 kg of vegetables in spring and 387 kg in summer, then donated 210 kg to a food bank. How many kilograms of vegetables are left?', '["629","649","639","619"]'::jsonb, 0, '452 + 387 = 839. Then subtract the donation: 839 − 210 = 629.', 'AC9M5N04', null, null, true, null, null, null, null),
('675a3cbb-713e-4cd8-8a35-1655aeedd3bc', 'number_operations', 'grade_5', 'proficient', 'multiple_choice', 'A $120 bike is marked up by 15% before it goes on sale. What is the new price?', '["132","138","118","135"]'::jsonb, 1, '15% of $120 is $18. The new price is $120 + $18 = $138.', 'AC9M5N06', null, null, true, null, null, null, null),
('e31d089b-dc41-49a8-a289-3bdb27a7db14', 'number_operations', 'grade_5', 'proficient', 'multiple_choice', 'A charity has 3/5 of its $600 donation target still left to raise. How much has it already raised?', '["360","480","240","160"]'::jsonb, 2, 'The amount left to raise is 3/5 × $600 = $360. So the amount already raised is $600 − $360 = $240.', 'AC9M5N05', null, null, true, null, null, null, null),
('f71000ed-9eb8-438f-b67b-11e223006aec', 'number_operations', 'grade_5', 'proficient', 'multiple_choice', 'Pippa has 47 stickers. She shares them equally between 6 friends, giving each friend as many as possible, and keeps the rest for herself. How many stickers does Pippa keep?', '["5","6","7","41"]'::jsonb, 0, '6 friends can each get 7 stickers, which uses 6 × 7 = 42. That leaves 47 − 42 = 5 stickers for Pippa.', 'AC9M5N04', null, null, true, null, null, null, null),
('10761e54-7f4b-4731-b6d8-c48d36bc9a50', 'number_operations', 'grade_5', 'developing', 'short_answer', 'A drink bottle costs $3.40. How much do 5 drink bottles cost?', null, null, '5 × $3.40 = $17.00.', 'AC9M5N06', null, null, true, '$17.00', ARRAY['17', '$17', '17.00']::text[], null, null),
('92199cf7-b588-42bb-9ab8-509e52a1f87f', 'number_operations', 'grade_5', 'advanced', 'short_answer', 'There are 35 pieces of fruit in a bowl. Each piece is either an apple or an orange. There are 4 times as many apples as oranges. How many oranges are in the bowl?', null, null, 'For every orange there are 4 apples, so the fruit comes in groups of 5: 35 ÷ 5 = 7 groups, giving 7 oranges (and 28 apples).', 'AC9M5N04', null, null, true, '7', null, null, null),
('126084be-5868-42f5-b3ee-bd92281d0827', 'number_operations', 'grade_5', 'proficient', 'multiple_choice', 'A charity raises $600 at a school fair. One quarter of the money is given to a local hospital. How much money goes to the hospital?', '["$60","$120","$150","$450"]'::jsonb, 2, 'One quarter means the money is split into 4 equal parts: $600 ÷ 4 = $150.', 'AC9M5N05', null, null, true, null, null, null, null),
('958e5578-fd4e-471f-8e1d-1ff113a6665a', 'number_operations', 'grade_5', 'advanced', 'multiple_choice', 'A concert venue has 24 rows. The first 16 rows have 32 seats each, and the remaining rows have 18 seats each because of a stage extension. How many seats are in the venue in total?', '["620","600","640","656"]'::jsonb, 3, '16 × 32 = 512. The remaining 8 rows: 8 × 18 = 144. Total: 512 + 144 = 656.', 'AC9M5N04', null, null, true, null, null, null, null),
('8f0f71bd-d18c-4e9e-a510-e25e308165f0', 'number_operations', 'grade_5', 'developing', 'short_answer', 'A recycling program collects 1,248 cans in March and 976 cans in April. How many cans were collected across both months?', null, null, '1248 + 976 = 2224.', 'AC9M5N04', null, null, true, '2224', ARRAY['2,224']::text[], null, null),
('a2a3e65e-69a5-4435-a9cb-16e81ca9958b', 'number_operations', 'grade_5', 'developing', 'short_answer', 'A charity has 3,150 stickers to share equally among 9 classrooms. How many stickers does each classroom receive?', null, null, '3150 ÷ 9 = 350 stickers each.', 'AC9M5N04', null, null, true, '350', null, null, null),
('26f56c0a-882a-4120-9ae4-78b54eff2f24', 'number_operations', 'grade_5', 'proficient', 'short_answer', 'A café orders 240 muffins for the week. 3/4 of them are blueberry and the rest are chocolate chip. How many chocolate chip muffins were ordered?', null, null, 'Chocolate chip is 1/4 of the order: 1/4 × 240 = 60.', 'AC9M5N05', null, null, true, '60', null, null, null),
('2fc9467d-2294-45b7-a22b-c06476b82924', 'number_operations', 'grade_5', 'proficient', 'short_answer', 'A fundraiser raises $3,600. After paying $450 in venue costs and $180 in catering costs, how much profit is left?', null, null, '3600 − 450 = 3150. Then 3150 − 180 = 2970.', 'AC9M5N04', null, null, true, '$2970', ARRAY['2970', '$2,970', '2,970']::text[], null, null),
('20f85400-d855-4052-b8f2-067e6957aba9', 'number_operations', 'grade_5', 'proficient', 'short_answer', 'A bakery makes 12 trays of bread rolls with 20 rolls on each tray. It sells 200 rolls at the market. How many rolls are left?', null, null, 'The bakery made 12 × 20 = 240 rolls. After selling 200: 240 − 200 = 40 rolls left.', 'AC9M5N04', null, null, true, '40', null, null, null),
('63d40664-985e-4ea3-a9b1-d70f1f8b8547', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'A submarine is at a depth of −45 m. It rises 18 m, then descends another 7 m. What is its final depth?', '["-34","-40","-30","-52"]'::jsonb, 0, '−45 + 18 = −27. Then −27 − 7 = −34.', 'AC9M6N01', null, null, true, null, null, null, null),
('ac556e67-2823-4df8-b75c-5479605fada1', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'A maths competition scoring system awards points using the expression (8 + 2) × 3 − 5. What is the final score?', '["21","25","35","19"]'::jsonb, 1, 'Brackets first: 8 + 2 = 10. Then multiply: 10 × 3 = 30. Then subtract: 30 − 5 = 25.', 'AC9M6N02', null, null, true, null, null, null, null),
('2c2043d0-ee77-4304-ad4e-1ecf0e0fea82', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'A garden plot is 5/6 of a hectare. A farmer plants vegetables on 3/5 of that plot. What fraction of a hectare is planted with vegetables?', '["8/11","3/6","1/2","2/3"]'::jsonb, 2, 'Multiply the fractions: (5×3)/(6×5) = 15/30, which simplifies to 1/2.', 'AC9M6N03', null, null, true, null, null, null, null),
('84678926-4399-487d-8cd8-419d3801908b', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'A roll of wire measuring 12.6 m is cut into pieces that are each 0.9 m long. How many pieces can be cut?', '["13","12","15","14"]'::jsonb, 3, 'Multiply both numbers by 10 to remove the decimals: 126 ÷ 9 = 14 pieces.', 'AC9M6N03', null, null, true, null, null, null, null),
('ca3eddc2-c08b-4a92-81b4-7d90925449dd', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'A vending machine dispenses 0.35 L of juice into each cup for a school sports day. It fills 24 cups before running out. How many litres of juice does it dispense in total?', '["8.4","24.35","84","7.4"]'::jsonb, 0, '0.35 × 24 = 8.4 L.', 'AC9M6N03', null, null, true, null, null, null, null),
('77089b75-20f8-4bd6-9fe9-725788e4025d', 'number_operations', 'grade_6', 'developing', 'multiple_choice', 'A trail map uses a scale where 2 cm on the map represents 5 km in real life. If two towns are 9 cm apart on the map, how far apart are they in real life?', '["18","22.5","20","25"]'::jsonb, 1, 'Each cm on the map represents 5 ÷ 2 = 2.5 km. So 9 cm represents 9 × 2.5 = 22.5 km.', 'AC9M6N02', null, null, true, null, null, null, null),
('06bec720-b657-43ce-b572-566e1a57ef7d', 'number_operations', 'grade_6', 'proficient', 'multiple_choice', 'In a survey of Grade 6 students, 9/20 said basketball is their favourite sport. Written as a percentage, what proportion is that?', '["0.9%","9%","45%","90%"]'::jsonb, 2, '9/20 = 45/100, which is 45%.', 'AC9M6N06', null, null, true, null, null, null, null),
('32ea9441-3c0b-497f-aee9-a16c294873f2', 'number_operations', 'grade_6', 'proficient', 'multiple_choice', 'A $250 jacket is first discounted by 20%, and then a further 10% is taken off the already-discounted price at the checkout. What is the final price?', '["175","187.50","200","180"]'::jsonb, 3, '20% off $250 leaves $250 × 0.8 = $200. A further 10% off leaves $200 × 0.9 = $180.', 'AC9M6N04', null, null, true, null, null, null, null),
('25c75b6a-6bb5-4873-b518-410e3d081ba1', 'number_operations', 'grade_6', 'proficient', 'multiple_choice', 'The temperature at the start of the day was −6°C. It rose by 4°C every hour for 3 hours, then dropped 5°C. What was the final temperature?', '["1","7","-7","11"]'::jsonb, 0, '−6 + (4 × 3) = −6 + 12 = 6. Then 6 − 5 = 1.', 'AC9M6N01', null, null, true, null, null, null, null),
('48655c63-dff1-4fee-8ac5-6c776b0a3fda', 'number_operations', 'grade_6', 'proficient', 'multiple_choice', 'A cyclist rides at a steady pace, covering 3/4 of a km every 5 minutes. At this rate, how far does the cyclist travel in 40 minutes?', '["4.5","6","7.5","8"]'::jsonb, 1, '40 minutes is 8 lots of 5 minutes. 8 × 3/4 = 6 km.', 'AC9M6N03', null, null, true, null, null, null, null),
('c5110d2a-867d-4f97-bc16-51f1c40002dc', 'number_operations', 'grade_6', 'advanced', 'multiple_choice', 'A community fundraiser dinner charges $45 per adult ticket and 2/3 of that price for a child ticket. If 18 adults and 24 children attend, how much money is raised from ticket sales in total?', '["1500","1560","1530","1410"]'::jsonb, 2, 'Adults: 18 × $45 = $810. A child ticket is 2/3 × $45 = $30, so children: 24 × $30 = $720. Total: $810 + $720 = $1530.', 'AC9M6N03', null, null, true, null, null, null, null),
('36abc3e8-be1a-468b-ad2a-68b128f9c505', 'number_operations', 'grade_6', 'advanced', 'multiple_choice', 'A submersible robot starts at the surface (0 m) and descends 2/5 of the way to a 150 m deep trench floor, then descends a further 36 m. What is its depth now, as a negative number?', '["-84","-60","-90","-96"]'::jsonb, 3, '2/5 of 150 m is 60 m. Total descent: 60 + 36 = 96 m, so the depth is −96 m.', 'AC9M6N04', null, null, true, null, null, null, null),
('c4571478-1199-4933-adf2-c71e3abf26ad', 'number_operations', 'grade_6', 'developing', 'short_answer', 'A charity fun run''s total distance across all laps is 8.4 km, run in laps of 0.6 km each. How many laps were completed?', null, null, '8.4 ÷ 0.6 = 14 laps.', 'AC9M6N03', null, null, true, '14', null, null, null),
('f6241dd7-d7cb-4be4-84e5-eab660235fb7', 'number_operations', 'grade_6', 'developing', 'short_answer', 'A recipe requires 5/8 of a cup of oil per batch. A café makes 8 batches for a catering order. How many cups of oil are needed in total?', null, null, '5/8 × 8 = 5 cups.', 'AC9M6N03', null, null, true, '5', null, null, null),
('15a18a6a-d1ff-4f59-a372-f6b943f75f89', 'number_operations', 'grade_6', 'proficient', 'short_answer', 'A $95 pair of shoes is discounted by 20% for a sale, then an extra $5 loyalty voucher is applied at checkout. What is the final price?', null, null, '20% of $95 is $19, leaving $95 − $19 = $76. Then subtract the voucher: $76 − $5 = $71.', 'AC9M6N04', null, null, true, '$71', ARRAY['71', '$71.00', '71.00']::text[], null, null),
('e968ba6f-fa95-49b0-b50c-e4d593e7fcd4', 'number_operations', 'grade_6', 'proficient', 'short_answer', 'A hiking group starts at an elevation of 1,240 m, climbs 385 m, then descends 560 m to make camp. What is the group''s final elevation?', null, null, '1240 + 385 = 1625. Then 1625 − 560 = 1065.', 'AC9M6N01', null, null, true, '1065', ARRAY['1,065', '1065 m', '1,065 m']::text[], null, null),
('adf4015f-f099-49fc-a76b-b6448ea8bfc0', 'number_operations', 'grade_6', 'advanced', 'short_answer', 'A school fun run raises $4,800. 5/12 of the total covers medal costs, and the remaining amount is split equally between 4 local charities. How much does each charity receive?', null, null, 'Medal costs: 5/12 × 4800 = 2000. Remaining: 4800 − 2000 = 2800. Split among 4: 2800 ÷ 4 = 700.', 'AC9M6N04', null, null, true, '$700', ARRAY['700', '$700.00', '700.00']::text[], null, null),
('d29f6f71-e1a6-4f34-bace-2048ffff3cb7', 'number_operations', 'year_7', 'foundation', 'multiple_choice', 'Zoe''s savings tracker shows −8 points from a missed goal, then she earns back 3 points for a completed chore. What is her total now (−8 + 3)?', '["11","−5","−11","5"]'::jsonb, 1, 'Starting at −8 and moving 3 units up the number line gives −5.', 'AC9M7N02', null, null, true, null, null, null, null),
('8deca51a-ea5b-435d-bef7-d954d53f664b', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'A water tank''s level was dropping by 4 cm each hour. Looking back at the reading from 6 hours ago, how does that past level compare to now, calculated as −4 × −6?', '["−24","24","−10","10"]'::jsonb, 1, 'A negative times a negative gives a positive: 4 × 6 = 24 cm.', 'AC9M7N02', null, null, true, null, null, null, null),
('e6842764-aeae-4a1c-a64c-7c6aa6dcafe9', 'number_operations', 'year_7', 'proficient', 'short_answer', 'A phone plan charges a $3 flat fee plus $4 per hour of overage, and Priya used 2 hours of overage this month. Using 3 + 4 × 2, what is her total charge?', null, null, 'Order of operations: multiply first (4 × 2 = 8), then add: 3 + 8 = 11.', 'AC9M7N04', null, null, true, '11', null, null, null),
('37db7f1b-9e7c-4b35-897d-40e71172fe98', 'number_operations', 'year_7', 'proficient', 'short_answer', 'A survey of 640 students found that 0.45 of them own a pet. How many students own a pet?', null, null, '0.45 × 640 = 288 students.', 'AC9M7N03', null, true, true, '288', null, null, null),
('519ffa79-43b2-4f66-8d1b-623a80140cc5', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'The bar chart shows how many cans of food each class collected for a food drive. What is the total number of cans collected by all four classes?', '["118","128","138","148"]'::jsonb, 1, 'Add all four bars: 34 + 28 + 41 + 25 = 128 cans.', 'AC9M7N06', null, null, true, null, null, null, null),
('6c06f0b1-ff59-4f57-b638-eae535e7f516', 'number_operations', 'year_7', 'proficient', 'short_answer', 'The bar chart shows how much pocket money a student saved each week. What was the average (mean) amount saved per week, in dollars?', null, null, 'Total saved = 12 + 18 + 15 + 21 = 66. Mean = 66 ÷ 4 = $16.50.', 'AC9M7N06', null, true, true, '16.5', ARRAY['$16.50', '16.50', '$16.5']::text[], null, null),
