('c07f7ef2-46a2-46a7-bbe5-bdef3b5e50ed', 'geometry_measurement', 'year_7', 'advanced', 'short_answer', 'A rectangular yard has the dimensions shown. Fencing costs $6.50 per metre. What is the total cost to fence the entire yard?', null, null, 'Perimeter = 2 × (18.5 + 11.2) = 59.4 m. Cost = 59.4 × $6.50 = $386.10.', 'AC9M7M02', null, true, true, '386.10', ARRAY['$386.10', '386.1', '$386.1']::text[], null, null),
