('39c8861d-64e6-485b-a523-ea6ab626aabc', 'number_operations', 'year_8', 'proficient', 'multiple_choice', 'A trophy cabinet has 18 gold medals and 24 silver medals. Simplify the ratio of gold to silver medals.', '["3:4","9:12","2:3","6:8"]'::jsonb, 0, 'Divide both parts by their highest common factor, 6: 18÷6=3, 24÷6=4.', 'AC9M8N01', null, null, true, null, null, null, null),
