('b6fc3102-685f-47f5-b4fc-5702a355d68d', 'number_operations', 'year_9', 'developing', 'multiple_choice', 'A triangular sign has a height related to √75. Simplify √75 to simplest surd form.', '["25√3","5√3","15√5","3√5"]'::jsonb, 1, '75 = 25 × 3, and √25 = 5, so √75 = 5√3.', 'AC9M9N02', null, null, true, null, null, null, null),
('3d3f32b4-b1b9-4a56-8d9a-2694be3a2478', 'number_operations', 'year_9', 'proficient', 'multiple_choice', 'Calculate the total repayment on a $7,850 loan charged at 6.8% p.a. simple interest over 4 years, including the principal.', '["$9,785.20","$10,085.20","$9,635.20","$9,985.20"]'::jsonb, 3, 'Interest = 7850 × 0.068 × 4 = $2,135.20. Total repayment = 7850 + 2135.20 = $9,985.20.', 'AC9M9N03', null, true, true, null, null, null, null),
