('b7832e97-0caf-4878-b34b-7dd1d611c328', 'number_operations', 'year_7', 'developing', 'short_answer', 'A school music program has 72 students, and 5/8 of them play a string instrument. How many students play a string instrument?', null, null, '5/8 of 72 = 72 ÷ 8 × 5 = 9 × 5 = 45.', 'AC9M7N03', null, null, true, '45', ARRAY['45 students']::text[], null, null),
('2dba1f8e-e775-43db-8ee1-089e9989eaa4', 'number_operations', 'year_7', 'foundation', 'short_answer', 'The temperature in a walk-in freezer is −18°C. A display fridge nearby is set to 4°C. What is the difference between the two temperatures (4 − (−18))?', null, null, '4 − (−18) = 4 + 18 = 22.', 'AC9M7N02', null, null, true, '22', ARRAY['22°C', '22 degrees']::text[], null, null),
('23c3390f-ba6d-4485-b4ec-f7fa81038baa', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'A trivia team starts with 4 bonus points, then answers 5 questions correctly, earning 3 points each. Using 4 + 5 × 3, what is the team''s total score?', '["27","19","17","12"]'::jsonb, 1, 'Order of operations: multiply first (5 × 3 = 15), then add: 4 + 15 = 19.', 'AC9M7N04', null, null, true, null, null, null, null),
