('3b23cda6-f9fa-48ce-98c9-3d647280882a', 'number_operations', 'year_9', 'proficient', 'multiple_choice', 'An investment of $5,600 grows to $6,384.80 over 4 years under simple interest. What annual interest rate (p.a.) was applied?', '["4.0%","3.0%","3.5%","2.8%"]'::jsonb, 2, 'Total interest = 6384.80 − 5600 = $784.80 over 4 years, or $196.20 per year. Rate = 196.20 ÷ 5600 = 3.5% p.a.', 'AC9M9N03', null, true, true, null, null, null, null),
('72b47b97-7a1c-4b11-9704-f6cd7bd1c564', 'number_operations', 'year_9', 'proficient', 'short_answer', 'A city''s population of 128,450 grows by 2.3% this year. What is the population after this year''s growth (to the nearest whole person)?', null, null, '128,450 × 1.023 ≈ 131,428.', 'AC9M9N02', null, true, true, '131,428', ARRAY['131428']::text[], null, null),
('856b1ff8-ff92-4cc6-b43c-a62f4ac8367c', 'number_operations', 'year_9', 'advanced', 'multiple_choice', 'A car''s value depreciates from $28,600 to $19,304.75 over 3 years under a constant annual percentage decrease. Find the total percentage decrease over the 3 years.', '["30.5%","35%","27.5%","32.5%"]'::jsonb, 3, 'Decrease = 28,600 − 19,304.75 = $9,295.25. As a percentage of the original value: 9,295.25 ÷ 28,600 = 32.5%.', 'AC9M9N03', null, true, true, null, null, null, null),
