('4ff58016-73c3-4476-bc20-edadbb53bd40', 'number_operations', 'year_7', 'advanced', 'short_answer', 'Parking Garage A charges $4.50 per hour with no minimum. Parking Garage B charges a flat $28 for the whole day. For a 5.5-hour stay, which garage is cheaper, and by how much?', null, null, 'Garage A: 4.50 × 5.5 = $24.75. Garage B: $28.00. Garage A is cheaper by 28 − 24.75 = $3.25.', 'AC9M7N05', null, true, true, 'Garage A, by $3.25', ARRAY['A, $3.25', 'Garage A by $3.25', '$3.25']::text[], null, null),
('29f787b8-b563-4f7f-9ec9-e885a48d6f70', 'number_operations', 'year_7', 'advanced', 'multiple_choice', 'A worker''s normal pay rate is $22 per hour for a 38-hour week. Overtime hours are paid at 1.5 times the normal rate. If the worker works 6 hours of overtime on top of the normal week, what is the total pay?', '["$1,068.00","$968.00","$1,000.00","$1,034.00"]'::jsonb, 3, 'Normal pay: 22 × 38 = 836. Overtime rate: 22 × 1.5 = 33. Overtime pay: 33 × 6 = 198. Total: 836 + 198 = $1,034.00.', 'AC9M7N04', null, true, true, null, null, null, null),
('bd754a81-a993-49f4-8e12-45248258030b', 'number_operations', 'year_7', 'advanced', 'multiple_choice', 'A shop sells items for $27.95 each. Buying 5 or more gives a 15% discount on the total. What is the cost of buying 5 items?', '["$118.79","$139.75","$127.14","$110.46"]'::jsonb, 0, 'Total before discount: 27.95 × 5 = 139.75. Discount amount: 139.75 × 0.15 = 20.96 (approx). Final cost: 139.75 − 20.96 = $118.79.', 'AC9M7N04', null, true, true, null, null, null, null),
